window.ETC.igudziai = [
  {"id": 1, "grupe": "K", "pav": "Taktinė traumos apžiūra (MARCH PAWS eiga)", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Taktinė traumos apžiūra – nuosekli nukentėjusiojo apžiūra ir pagalba pagal MARCH PAWS, kai tiesioginės ugnies nebėra (TFC), ir vėl iš naujo evakuacijos metu (TACEVAC). Pirmiausia randamos ir šalinamos greičiausiai žudančios būklės: masyvus kraujavimas, kvėpavimo takų nepraeinamumas, krūtinės sužalojimai ir šokas. Šaulys gelbėtojas, atvykęs į sužeidimo vietą ar perimdamas nukentėjusįjį, apžiūrą pradeda nuo pradžių ir nepasitiki vien tuo, kas padaryta anksčiau.", "esme": ["Sauga pirmiausia: perimetrą saugo kiti, pagalbos teikėjas išlaiko situacinį budrumą. Sutrikusios sąmonės nukentėjusįjį nuginkluokite (ginklai, granatos, ryšio priemonės) – taktiškai, pvz., „duok pasaugoti“.", "M – greita kraujo apčiuopa: kaklas, pažastys, kirkšnys, kojos, rankos, pilvas, krūtinė, nugara; vis žiūrėkite į pirštines. Masyvus kraujavimas – pulsuoja, srūva, telkšo, amputacija, permirkę drabužiai; nukraujuoti galima per 3 min.", "A – kalbantis ar rėkiantis turi laisvus kvėpavimo takus. Sąmoningam leiskite užimti jam patogią padėtį (sėdėti, pasilenkti į priekį), nesąmoningą guldykite į stabilią šoninę padėtį.", "R – atidenkite krūtinę ir apžiūrėkite nugarą: atvirai (penetruojančiai, siurbiančiai) krūtinės žaizdai – krūtinės lipdukas (geriau su vožtuvu); stebėkite, ar nesivysto įtampos pneumotoraksas.", "C – patikrinkite visus turniketus ir tvarsčius, radialinį pulsą ir sąmonę: silpnas ar nečiuopiamas radialinis pulsas ir sutrikusi sąmonė (be galvos traumos) – šokas, skubi evakuacija.", "H, P, A, W, S – hipotermijos prevencija nuo pat pradžių, akies skydelis, CWMP ir antibiotikas, visų žaizdų ir nudegimų sutvarkymas, įtvėrimas; distalinį pulsą tikrinkite prieš įtvėrimą ir po jo.", "Po kiekvieno perkėlimo ir evakuacijos metu kartokite M–A–R–C: turniketai, tvarsčiai, kvėpavimas, pulsas, sąmonė; viską rašykite į DD 1380 kortelę."], "zingsniai": ["Įvertinkite taktinę situaciją: ar tikrai nebėra tiesioginės ugnies ir kas saugo perimetrą. Jei įmanoma, užsimaukite pirštines.", "Užkalbinkite: „Kaip jautiesi? Kur sužeistas?“ Įvertinkite sąmonę pagal AVPU. Sutrikusios sąmonės nukentėjusįjį nuginkluokite.", "M: atlikite greitą kraujo apčiuopą – kaklas, pažastys, kirkšnys, kojos, rankos, pilvas, krūtinė (grėbiamais judesiais), nugara; po kiekvienos srities pažiūrėkite į pirštines.", "Rastą masyvų kraujavimą stabdykite iš karto: galūnė – turniketas tiesiai ant odos 5–7,5 cm virš žaizdos (#5), jungties vietos – tamponavimas ir spaudimas ≥ 3 min (#6, #7). Patikrinkite CUF metu uždėtus turniketus.", "A: ar kalba aiškiai? Matomus svetimkūnius pašalinkite, aklai pirštais burnos nevalykite. Obstrukcijos požymiai (veido trauma, kraujas, knarkimas, gargaliavimas) – atverkite kvėpavimo takus (#9); nesąmoningą guldykite į stabilią šoninę padėtį (#10).", "R: atidenkite krūtinę, apžiūrėkite priekį ir nugarą, suskaičiuokite kvėpavimo dažnį. Kiaurinę krūtinės žaizdą užklijuokite krūtinės lipduku; sunkėjant kvėpavimui – atklijuokite lipduko kraštą arba atlikite adatinę dekompresiją (#14–#16).", "C: patikrinkite radialinį pulsą ir sąmonę (šoko požymiai, #17). Pakartotinai įvertinkite turniketus: reikalingus pažymėkite laiku, keiskite ar konvertuokite pagal taisykles (#8). Po sprogimo ar sunkios bukos traumos įtarkite dubens lūžį ir praneškite (dubens diržas – CMC, #18).", "H: kuo anksčiau saugokite nuo atšalimo – izoliacija nuo žemės, sausi drabužiai, užklotas (#21); įtarus galvos traumą stebėkite sąmonę ir praneškite (#22).", "Akys, P, A: penetruojančiai akies traumai – standus akies skydelis, ne spaudžiamasis tvarstis (#23); kovos gebančiam – CWMP, atviroms žaizdoms – antibiotikas per os (#24, #26). Ketaminas ir IV/IM vaistai – CMC lygis.", "W, S: apžiūrėkite ir sutvarstykite visas žaizdas, ieškokite nepastebėtų, sutvarkykite nudegimus; įtverkite lūžius, distalinį pulsą tikrinkite prieš ir po (#27–#29).", "Kalbėkite su nukentėjusiuoju (nuraminkite, paaiškinkite), praneškite vadui būklę ir evakuacijos poreikį; užpildykite DD 1380 kortelę (#31) ir parenkite nukentėjusįjį evakuacijai (#32, #33).", "Laukiant evakuacijos, jos metu ir po kiekvieno perkėlimo vertinkite iš naujo: M–A–R–C, turniketai, tvarsčiai, kvėpavimas, pulsas, sąmonė; pokyčius rašykite į kortelę (#30)."], "klaidos": ["Pradedama nuo labiausiai matomos, bet ne pavojingiausios žaizdos; praleidžiama kraujo apčiuopa – nepastebimas kraujavimas po nugara, pažastyje ar kirkšnyje.", "Pasitikima CUF metu „aklai“ ant drabužių uždėtu turniketu ir jis TFC metu neatidengiamas bei nepatikrinamas.", "Atidengiama per daug kūno ir taip paliekama – nukentėjusysis atšąla; apžiūrėjus drabužiai ir apsaugos priemonės neuždedami atgal.", "Užsižiūrima į pagalbą ir prarandamas situacinis budrumas; nenuginkluojamas sutrikusios sąmonės nukentėjusysis.", "Po perkėlimo ar pakrovimo į transportą apžiūra nekartojama; nepildoma DD 1380 kortelė."], "tccc": ["TCCC 2026 TFC 2: rūšiuoti nukentėjusiuosius, jei jų keli (Supplement A).", "TCCC 2026 TFC 3: ieškoti nepastebėto kraujavimo ir stabdyti visus šaltinius; turniketas tiesiai ant odos 5–7,5 cm virš žaizdos, jungties vietų ir kitam suspaudžiamam kraujavimui – hemostatinis tvarstis ir ≥ 3 min spaudimas.", "TCCC 2026 TFC 4: sąmoningas gali užimti kvėpavimo takus geriausiai apsaugančią padėtį; nesąmoningas – stabili šoninė padėtis, galva atlošta, smakras atitrauktas nuo krūtinės.", "TCCC 2026 TACEVAC 1: perimant nukentėjusįjį evakuacijos personalas iš naujo įvertina visus sužalojimus ir visas anksčiau atliktas intervencijas."], "vaizdai": [{"src": "img/tccc/CLS5__module-5-tactical-trauma-assessment-en-09.webp", "orig": "https://tccc.org.ua/files/uploads/CLS5/module-5-tactical-trauma-assessment-en-09.jpg", "cap": "Kraujo apčiuopa: greitas patikrinimas nuo kaklo iki kojų, žiūrint į pirštines"}, {"src": "img/tccc/CLS5__module-5-tactical-trauma-assessment-en-10.webp", "orig": "https://tccc.org.ua/files/uploads/CLS5/module-5-tactical-trauma-assessment-en-10.jpg", "cap": "Masyvus kraujavimas: pulsuojantis ar telkšantis kraujas, permirkę drabužiai, amputacija – nukraujuoti galima per 3 min"}, {"src": "img/tccc/CLS5__module-5-tactical-trauma-assessment-en-12.webp", "orig": "https://tccc.org.ua/files/uploads/CLS5/module-5-tactical-trauma-assessment-en-12.jpg", "cap": "Kvėpavimo takų obstrukcijos požymiai: distresas, knarkimas ar gurgimas, kraujas ar svetimkūniai, veido trauma"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS5/video5-1-en.mp4", "title": "5.1 Tactical Trauma Assessment How-To", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/tactical-trauma-assessment-how-to", "note": "Visa taktinė traumos apžiūra pagal MARCH PAWS – lėtai, žingsnis po žingsnio"}, {"url": "https://tccc.org.ua/files/uploads/CLS5/video5-2-en.mp4", "title": "5.2 Tactical Trauma Assessment: Combat Speed 'Firefight' Conscious Casualty", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/tactical-trauma-assessment-combat-speed-firefight-conscious-casualty", "note": "Ta pati apžiūra koviniu tempu: sąmoningas sužeistasis po susišaudymo"}], "kortele": {"url": "https://tccc.org.ua/en/guide/tactical-trauma-assessment-how-to", "pav": "CLS 5.1 Tactical Trauma Assessment How-To"}, "saltiniai": ["TCCC gairės 2026-05-01 (CUF; TFC 1–20; TACEVAC 1)", "JTS CLS 5 modulis „Tactical Trauma Assessment“ (skaidrės, video 5.1–5.2)", "M. Grinevičiaus kursas – „Taktinė lauko pagalba“, „MARCH PAWS“, „Masyvus kraujavimas (M)“, „Kraujotaka (C)“, „Taktinė nukentėjusiojo apžiūra“"]},
  {"id": 2, "grupe": "K", "pav": "Vieno žmogaus vilkimas ir nešimas", "lygis": "CLS", "fazes": ["CUF", "TFC"], "aprasas": "Nukentėjusįjį, kuris pats negali judėti, vienas gelbėtojas ištraukia iš ugnies zonos ar degančios technikos į priedangą arba perneša trumpą atstumą iki saugesnės vietos. Apšaudymo metu svarbiausia greitis ir kuo mažesnis abiejų matomumas, todėl dažniausiai velkama; nešama, kai nukentėjusysis sąmoningas, o tiesioginės ugnies nebėra. Sprendimą ištraukti priima vadas, o padalinys tuo metu slopina priešą ugnimi ar dengia dūmais.", "esme": ["Prieš ištraukiant vadas įvertina: ar sužeistasis gyvas, kokia rizika gelbėtojams, kur ir kaip toli priedanga, sužeistojo svorį, gelbėtojų skaičių ir priemones.", "Naikinimo zonoje medicininė pagalba neteikiama – nebent turniketas, gulint ir prisidengiant bent sužeistojo kūnu; tada iškart traukite į priedangą.", "Vilkimas už ekipuotės (liemenės vilkimo rankenos) ar rankos – greitas, bet tik trumpam atstumui, kai ugnis nepalieka kitos išeities; ekipuotė turi būti tvirtai užsegta.", "Vilkimas po savimi (kaklo) – mažiausias abiejų matomumas; netinka esant sunkiam rankos sužalojimui ar amputacijai; nesąmoningo galvą saugokite nuo žemės.", "Lopšio vilkimas (cradle-drop) – laiptais, laipteliais ar labai trumpam atstumui; sužeistasis pusiau sėdi, galva remiasi į gelbėtojo dilbius.", "Nešimas ant nugaros (pack-strap) – tik sąmoningam, 50–300 m; atramos nešimas – sąmoningam, galinčiam bent kiek eiti.", "Jei įmanoma, iš anksto pasakykite sužeistajam, ką darysite, ir paimkite jo ginklus."], "zingsniai": ["Gaukite vado sprendimą, susitarkite dėl ugnies priedangos (ugnis, dūmai, technika) ir pasakykite sužeistajam, ką darysite.", "Vilkimas už ekipuotės: sugriebkite už liemenės vilkimo rankenos, dirželio ar rankos ir, eidami atbulomis trumpais greitais brūkšniais, tempkite į priedangą.", "Vilkimas po savimi: sužeistojo rankas sunerkite ar suriškite ties riešais, užsėskite ant jo klūpėdami veidu į veidą ir jo rankas užmeskite sau ant kaklo.", "Šliaužkite į priekį, tempdami sužeistąjį po savimi; jis turi likti gulėti ant nugaros. Nesąmoningo galvą saugokite nuo žemės.", "Lopšio vilkimas: atsiklaupkite prie ant nugaros gulinčio sužeistojo galvos, delnais į viršų pakiškite rankas po pečiais ir tvirtai suimkite po pažastimis.", "Iš dalies atsistokite, sužeistojo galvą prilaikydami dilbiu (ar abiem sukištais dilbiais), ir tempkite atbulomis. Leisdamiesi laiptais prilaikykite galvą ir liemenį, o klubus ir kojas leiskite per laiptelius.", "Nešimas ant nugaros (sąmoningam): pritūpkite priešais sužeistąjį nugara į jį, kad jis apkabintų jūsų kaklą; geriausia vieną jo ranką praveskite po savo pažastimi.", "Suimkite jo riešą (ranka – per jūsų petį), pakelkite kojų raumenimis, pasilenkite ir užkelkite kuo aukščiau ant nugaros; toliau eikite kuo tiesesni, kad nesusižeistumėte nugaros.", "Atramos nešimas (sąmoningam): padėkite atsistoti, stipriąja ranka jo riešą užsimeskite už savo kaklo, kita ranka apkabinkite per juosmenį, suimdami už diržo ar drabužių, ir eikite kartu, būdami jam ramentu.", "Priedangoje iškart pereikite prie TFC: kraujo apčiuopa, turniketų patikra, kvėpavimo takai (#1)."], "klaidos": ["Bandoma teikti pagalbą naikinimo zonoje, užuot pirma ištraukus į priedangą.", "Velkama be ugnies priedangos ar be aiškaus plano – sužeidžiamas ir gelbėtojas.", "Velkama už neužsegtos ekipuotės – ji nusmunka; vilkimas už rankos taikomas ilgam atstumui ir dar labiau sužaloja.", "Vilkimas po savimi taikomas esant rankos sužalojimui ar amputacijai; nesąmoningo galva nesaugoma nuo žemės.", "Nešimas ant nugaros naudojamas nesąmoningam; keliama nugara, o ne kojomis.", "Pratybose nesilaikoma saugos – susižeidžia gelbėtojas ar „sužeistasis“."], "tccc": ["TCCC 2026 CUF 1–4: atsakyti ugnimi ir pasislėpti; nurodyti sužeistajam judėti į priedangą ir teikti sau pagalbą, jei gali; saugoti jį nuo papildomų sužeidimų.", "TCCC 2026 CUF 5: iš degančių transporto priemonių ar pastatų nukentėjusiuosius ištraukti į santykinai saugią vietą ir sustabdyti degimą.", "TCCC 2026 CUF 7: kvėpavimo takų tvarkymą paprastai geriausia atidėti iki TFC."], "vaizdai": [{"src": "img/tccc/cls3__cls-skill-card-3-6-one-person-drags-carries-1-en.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/cls-skill-card-3-6-one-person-drags-carries-1-en.jpg", "cap": "Vilkimas už ekipuotės ar rankos: sugriebti už liemenės rankenos ir trumpais brūkšniais tempti atbulomis į priedangą"}, {"src": "img/tccc/cls3__cls-skill-card-3-6-one-person-drags-carries-2-en.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/cls-skill-card-3-6-one-person-drags-carries-2-en.jpg", "cap": "Vilkimas po savimi (neck drag): suneriamos ar surištos sužeistojo rankos ant gelbėtojo kaklo, gelbėtojas šliaužia į priekį"}, {"src": "img/tccc/cls3__module3-care-under-fire-en-26.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/module3-care-under-fire-en-26.jpg", "cap": "Vieno žmogaus vilkimas ir nešimas: atrama, vilkimas už kaklo ar įrangos, nešimas ant rankų"}], "video": [{"url": "https://tccc.org.ua/files/uploads/cls3/mv3-6-eng.mp4", "title": "3.6 One Person Drags & Carries", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/one-person-drags-carries", "note": "Vieno gelbėtojo vilkimo ir nešimo būdai: už ekipuotės, po savimi, lopšio, ant nugaros, su atrama"}], "kortele": {"url": "https://tccc.org.ua/en/guide/one-person-drags-carries", "pav": "CLS 3.6 One Person Drags & Carries"}, "saltiniai": ["TCCC gairės 2026-05-01 (CUF 1–7)", "JTS CLS kortelė 3.6 One Person Drags & Carries", "M. Grinevičiaus kursas – „Kodėl planas yra būtent toks?“, „Nukentėjusiojo ištraukimas“"]},
  {"id": 3, "grupe": "K", "pav": "Dviejų žmonių vilkimas ir nešimas", "lygis": "CLS", "fazes": ["CUF", "TFC"], "aprasas": "Dviese nukentėjusįjį ištraukti ar pernešti greičiau ir mažiau vargina nei vienam, o vilkdami gelbėtojai gali laikyti ginklus parengtus. Apšaudymo metu dviese velkama už ekipuotės į priedangą; kai tiesioginės ugnies nebėra, nešama atramos arba „priekis–galas“ būdu iki saugesnės vietos ar neštuvų. Ilgesniam atstumui ir evakuacijai naudokite neštuvus (#33).", "esme": ["Prieš judėdami susitarkite, kas vadovauja, kokia kryptis ir kur priedanga; keliama ir einama pagal vieno komandą (pvz., „trys“).", "Vilkimas už ekipuotės dviese – tik trumpam atstumui į priedangą; ekipuotė turi būti tvirtai užsegta, gelbėtojai išlaiko ginklus parengtus.", "Atramos nešimas dviese tinka ir sąmoningam, ir nesąmoningam; nesąmoningą ar aukštesnį palaikykite po šlaunimis, kad kojos nesivilktų.", "„Priekis–galas“: aukštesnis gelbėtojas – prie galvos, laiko po pažastimis; kitas – tarp kojų, nugara į sužeistąjį, laiko po keliais.", "Kelkite kojų raumenimis ir vienu metu; eikite sutartinai.", "Priedangoje – iškart TFC pagal MARCH PAWS; po kiekvieno perkėlimo patikrinkite turniketus ir tvarsčius."], "zingsniai": ["Vilkimas už ekipuotės: atsistokite greta sužeistojo; kiekvienas sugriebkite už jo ekipuotės (vilkimo rankenos, dirželio) ar rankos.", "Velkite sužeistąjį už savęs, eidami į priekį kuo greičiau trumpais brūkšniais; laisva ranka laikykite ginklą parengtą.", "Atramos nešimas: sąmoningą pastatykite ant kojų ir prilaikykite rankomis per juosmenį; nesąmoningą – abu atsiklaupę pasodinkite veidu ta pačia kryptimi kaip jūs.", "Suimkite jo riešus ir jo rankas užsimeskite ant savo kaklų (jei gali – tegul laikosi pats).", "Kitomis rankomis apkabinkite per juosmenį ir suimkite už diržo ar drabužių; nesąmoningam ar aukštesniam rankas pakiškite po šlaunimis, kad kojos nesivilktų.", "Pakelkite ir, tvirtai laikydami, eikite į priekį.", "„Priekis–galas“: paguldykite sužeistąjį ant nugaros, rankas – prie šonų. Aukštesnis gelbėtojas atsiklaupia prie galvos veidu į kojas, pakiša rankas po pažastimis ir sukabina jas ant krūtinės.", "Antrasis praskečia sužeistojo kojas, atsiklaupia tarp jų nugara į sužeistąjį ir suima kojas, pakišęs rankas po keliais.", "Atsistokite kartu skaičiuodami iki trijų ir eikite sutartinai.", "Priedangoje ar evakuacijos taške iškart patikrinkite turniketus, tvarsčius ir kvėpavimą."], "klaidos": ["Judama be susitarimo ir komandos – keliamasi ne vienu metu, sužeistasis krenta.", "Velkama už neužsegtos ekipuotės; vilkimas taikomas ilgam atstumui.", "Keliama nugara, ne kojomis.", "Nesąmoningo kojos velkasi žeme, galva nekontroliuojama.", "Po perkėlimo nepatikrinama, ar nepasislinko turniketai ir tvarsčiai."], "tccc": ["TCCC 2026 CUF 3–4: nukreipti nukentėjusįjį į priedangą ir saugoti jį nuo papildomų sužeidimų.", "TCCC 2026 TFC 1: užtikrinti saugos perimetrą ir išlaikyti taktinį situacinį budrumą.", "TCCC 2026 TFC 20: ruošiant evakuacijai pritvirtinti tvarsčių galus, užklotus ir neštuvų diržus; nukentėjusiuosius išrikiuoti pagal padalinio SOP."], "vaizdai": [{"src": "img/tccc/cls3__cls-skill-card-3-7-two-person-drags-carries-1-en.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/cls-skill-card-3-7-two-person-drags-carries-1-en.jpg", "cap": "Vilkimas už ekipuotės dviese: gelbėtojai eina į priekį, tempdami sužeistąjį už savęs, ginklai parengti"}, {"src": "img/tccc/cls3__cls-skill-card-3-7-two-person-drags-carries-2-en.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/cls-skill-card-3-7-two-person-drags-carries-2-en.jpg", "cap": "Atramos nešimas dviese: sužeistojo rankos ant gelbėtojų kaklų, rankos per juosmenį arba po šlaunimis"}, {"src": "img/tccc/cls3__module3-care-under-fire-en-28.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/module3-care-under-fire-en-28.jpg", "cap": "Dviejų žmonių nešimas: dviejų žmonių atrama, nešimas priekis–galas"}], "video": [{"url": "https://tccc.org.ua/files/uploads/cls3/mv3-7-eng.mp4", "title": "3.7 Two Person Drags & Carries", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/two-person-drags-carries", "note": "Dviejų gelbėtojų vilkimas už ekipuotės, atramos ir „priekis–galas“ nešimas"}], "kortele": {"url": "https://tccc.org.ua/en/guide/two-person-drags-carries", "pav": "CLS 3.7 Two Person Drags & Carries"}, "saltiniai": ["TCCC gairės 2026-05-01 (CUF 3–4; TFC 1, 20)", "JTS CLS kortelė 3.7 Two Person Drags & Carries", "M. Grinevičiaus kursas – „Nukentėjusiojo ištraukimas“, „Neštuvai“"]},
  {"id": 4, "grupe": "M", "pav": "Turniketas sau apšaudymo metu (viena ranka)", "lygis": "CLS", "fazes": ["CUF"], "aprasas": "Apšaudymo metu sužeistasis pirmiausia padeda sau pats: užsideda turniketą ir toliau kovoja arba juda į priedangą. Šaulys gelbėtojas tai turi mokėti pats (gali būti sužeistas) ir nurodyti sužeistajam, kol prie jo dar negalima prieiti. Turniketas dedamas ant uniformos, aukštai ir tampriai, per mažiau nei 1 min.", "esme": ["Masyvus kraujavimas: kraujas pulsuoja, švirkščia ar teka srove, amputacija, kraujas telkšo ant žemės, permirkę drabužiai. Pažeidus stambią arteriją, nukraujuoti galima vos per 3 min. (JTS CLS 3 modulis).", "CUF metu turniketas dedamas ant uniformos, kiek įmanoma aukščiau galūnėje (aukštai ir tampriai), neieškant žaizdos; 1–5 žingsniai – greičiau nei per 1 min.", "Prieš sukdami veržtuvą pašalinkite visą juostos laisvumą: tarp juostos ir uniformos neturi tilpti 3 pirštai.", "Sukite, kol kraujavimas sustos; jei žaizdos nematyti – kiek tik pajėgiate (M. Grinevičiaus kurse – bent 3 kartus po 180°).", "CUF metu laiko nerašykite – tai padarysite TFC metu; kad nepamirštumėte, pasakykite laiką garsiai ir pakartokite su sužeistuoju 3 kartus.", "Turniketą laikykite paruoštą greitam ištraukimui, bet kuria ranka pasiekiamoje ir visame junginyje vienodoje vietoje; bent vienas – ant ekipuotės.", "Žaizdų tamponavimas CUF metu neatliekamas; kol ruošiate turniketą, kraujavimą galima pristabdyti spaudžiant žaizdą ar kirkšnį (pvz., keliu)."], "zingsniai": ["Atsakykite ugnimi ir, jei galite, pasitraukite už priedangos; praneškite artimiausiems kariams ar vadui, kad esate sužeistas.", "Ištraukite turniketą iš IFAK ar dėklo.", "Prakiškite ranką pro juostos kilpą (koją – apjuoskite ir juostą praverkite pro sagtį) ir turniketą užstumkite kiek įmanoma aukščiau ant uniformos, virš kraujavimo vietos.", "Veržtuvinis turniketas: patraukite juostą, kad neliktų laisvumo, užklijuokite ją atgal ant jos pačios ir tik tada sukite veržtuvo strypą.", "Sukite strypą, kol kraujavimas sustos (1–5 žingsniai – per < 1 min), ir užfiksuokite jį laikiklyje.", "Likusią juostą praveskite aplink strypą ir tarp laikiklių, užsekite saugos dirželį.", "Krumpliaratinis turniketas: kilpą suimkite dantimis (arba atsiremkite į kietą paviršių), kad neslystų, ir juostą užveržkite kuo tampriau.", "Kelkite krumpliaratinės sagties svirtį ir veržkite, kol kraujavimas sustos (< 1 min); užspauskite svirtį, kol spragtels. Kraujuoja toliau – veržkite toliau.", "Jei kito masyvaus kraujavimo nėra – judėkite į priedangą ir, jei galite, toliau dalyvaukite kovoje.", "Uždėjimo laiką pasakykite garsiai (CUF metu nerašykite). TFC metu ar atvykus gelbėtojui turniketas atidengiamas ir įvertinamas iš naujo (#5, #8)."], "klaidos": ["Juostoje paliekama laisvumo – sukant veržtuvą kraujavimas nesustoja.", "Turniketas dedamas žemai, ant kelio ar alkūnės ar ant kišenių su daiktais, užuot dėjus aukštai ir tampriai.", "Gaištamas laikas ugnies zonoje; bandoma tamponuoti CUF metu.", "Turniketas laikomas giliai kuprinėje ar vietoje, kurios nepasieksite viena ranka.", "Po CUF pamirštama turniketą patikrinti ir pažymėti laiką."], "tccc": ["TCCC 2026 CUF 6: gyvybei pavojingą išorinį kraujavimą stabdyti, jei taktiškai įmanoma; nurodyti sužeistajam pačiam stabdyti, jei gali; CoTCCC rekomenduojamą galūnės turniketą dėti proksimaliau kraujavimo vietos ant uniformos, suveržti ir judėti į priedangą.", "TCCC 2026 CUF 2–3: tikėtis, kad sužeistasis toliau kovos, jei gali; nurodyti jam judėti į priedangą ir teikti sau pagalbą.", "TCCC 2026 TFC 6a: kiekvieną turniketą pažymėti uždėjimo laiku nenuplaunamu žymekliu ir įrašyti į DD 1380 kortelę."], "vaizdai": [{"src": "img/tccc/cls3__skill-card__skill-cards-1-eng-page-1.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/skill-card/skill-cards-1-eng-page-1.jpg", "cap": "Veržtuvinis turniketas sau viena ranka: aukštai ant uniformos, sukti, kol sustos kraujavimas (< 1 min), užfiksuoti ir judėti į priedangą"}, {"src": "img/tccc/cls3__skill-card__sk33-eng_page-1.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/skill-card/sk33-eng_page-1.jpg", "cap": "Krumpliaratinis turniketas sau viena ranka: kilpą prilaikyti dantimis, veržti svirtimi, užspausti, kol spragtels"}, {"src": "img/tccc/cls3__module3-care-under-fire-en-14.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/module3-care-under-fire-en-14.jpg", "cap": "Nukraujuoti iš didelės arterijos galima vos per 3 min – turniketą dėkite nedelsdami"}], "video": [{"url": "https://tccc.org.ua/files/uploads/cls3/mv3-2-eng.mp4", "title": "3.2 One-Handed Windlass Tourniquet (Care Under Fire)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/one-handed-windlass-tourniquet-care-under-fire", "note": "Veržtuvinio turniketo užsidėjimas sau viena ranka apšaudymo metu"}, {"url": "https://tccc.org.ua/files/uploads/cls3/mv3-3-eng.mp4", "title": "3.3 One-Handed Ratchet Tourniquet (Care Under Fire)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/one-handed-ratchet-tourniquet-care-under-fire", "note": "Krumpliaratinio turniketo užsidėjimas sau viena ranka apšaudymo metu"}], "kortele": {"url": "https://tccc.org.ua/en/guide/one-handed-windlass-tourniquet-care-under-fire", "pav": "CLS 3.2 One-Handed Windlass Tourniquet (Care Under Fire)"}, "saltiniai": ["TCCC gairės 2026-05-01 (CUF 1–7; TFC 6a)", "JTS CLS kortelės 3.2 One-Handed Windlass ir 3.3 One-Handed Ratchet Tourniquet (CUF)", "M. Grinevičiaus kursas – „Kraujavimo stabdymas“, „Kodėl planas yra būtent toks?“, „IFAK“"]},
  {"id": 5, "grupe": "M", "pav": "Turniketas draugui abiem rankomis (CUF ir TFC)", "lygis": "CLS", "fazes": ["CUF", "TFC"], "aprasas": "Kai sužeistasis negali užsidėti turniketo pats, jį abiem rankomis uždeda gelbėtojas. CUF metu – greitai ant uniformos, aukštai ir tampriai, ir iškart į priedangą; TFC metu – atidengus žaizdą, tiesiai ant odos 5–7,5 cm virš jos. Kiekvienas turniketas turi sustabdyti kraujavimą ir (jei nėra amputacijos) panaikinti distalinį pulsą.", "esme": ["CUF: turniketas ant uniformos, aukštai galūnėje virš kraujavimo vietos; 1–5 žingsniai – per < 1 min; dirbkite gulėdami, prisidengę bent sužeistojo kūnu, tada ištraukite į priedangą.", "TFC: atidenkite ir įvertinkite žaizdą; turniketas tiesiai ant odos 5–7,5 cm (2–3 col.) virš žaizdos, ne ant sąnario; 1–6 žingsniai – per < 1 min, visiškai pritvirtintas – per ≤ 3 min.", "Sprogimo sužalotai galūnei turniketą gali tekti dėti didesniu atstumu nuo žaizdos (M. Grinevičius).", "Veiksmingas turniketas: kraujavimas sustojo IR distalinio pulso nėra (išskyrus amputaciją). Ne – suveržkite stipriau; nepakanka – antras turniketas greta pirmojo, be tarpo.", "Laiką TFC metu užrašykite ant turniketo nenuplaunamu žymekliu ir DD 1380 kortelėje; CUF metu laikas nerašomas.", "Po kiekvieno perkėlimo ir evakuacijos metu patikrinkite, ar turniketas nepasislinko ir neatsilaisvino, ar neatsinaujino kraujavimas."], "zingsniai": ["CUF: prisidenkite (gulėdami, bent sužeistojo kūnu) ir ištraukite turniketą iš sužeistojo IFAK ar dėklo.", "CUF: prakiškite galūnę pro juostos kilpą (arba apjuoskite galūnę ir juostos galą praverkite pro sagtį) ir turniketą užstumkite aukštai ant uniformos, virš kraujavimo vietos.", "CUF: ištempkite juostą be laisvumo, užklijuokite, sukite veržtuvą, kol kraujavimas sustos (1–5 žingsniai < 1 min), užfiksuokite strypą, užsekite saugos dirželį ir, jei kito masyvaus kraujavimo nėra, traukite sužeistąjį į priedangą.", "TFC: atidenkite ir įvertinkite žaizdą (prakirpkite drabužius); kol ruošiate turniketą, spauskite žaizdą ar kirkšnį.", "TFC: prakiškite galūnę pro kilpą (arba apjuoskite ir praverkite pro sagtį) ir turniketą dėkite 5–7,5 cm virš žaizdos tiesiai ant odos, ne ant sąnario.", "Ištempkite juostą kuo tampriau ir užklijuokite ją atgal visu ilgiu aplink galūnę.", "Sukite veržtuvo strypą, kol kraujavimas sustos (1–6 žingsniai < 1 min), užfiksuokite laikiklyje, juostą praveskite aplink strypą ir tarp laikiklių, užsekite saugos dirželį (visa procedūra – iki 3 min).", "Krumpliaratinis turniketas: juostą patraukite kuo tampriau, veržkite svirtimi, kol kraujavimas sustos, užspauskite iki spragtelėjimo, likusią juostą apvyniokite ir pritvirtinkite.", "Patikrinkite: kraujavimas sustojo ir distalinio pulso nėra. Jei ne – veržkite stipriau arba dėkite antrą turniketą greta pirmojo.", "Užrašykite uždėjimo laiką ant turniketo nenuplaunamu žymekliu, visus radinius ir veiksmus – DD 1380 kortelėje; ją pritvirtinkite prie sužeistojo.", "CUF metu uždėtą turniketą TFC metu atidenkite ir įvertinkite: pakeiskite nauju ant odos arba nuimkite, jei nereikalingas (#8).", "Po kiekvieno perkėlimo ir evakuacijos metu tikrinkite turniketą ir kraujavimą."], "klaidos": ["Turniketas suveržiamas nepakankamai – kraujavimas tęsiasi arba juntamas distalinis pulsas.", "TFC metu turniketas paliekamas ant drabužių aukštai ir tampriai, nors žaizda matoma; dedamas ant kelio ar alkūnės.", "Juostoje paliekama laisvumo arba ji užklijuojama ant veržtuvo laikiklių.", "Nededamas antras turniketas, kai pirmojo nepakanka.", "Laikas nepažymimas arba rašomas tik ant drabužių, o ne ant turniketo ir kortelės.", "Turniketas atlaisvinamas, kad galūnė „pakvėpuotų“."], "tccc": ["TCCC 2026 CUF 6: CoTCCC rekomenduojamą turniketą dėti proksimaliau kraujavimo vietos ant uniformos, suveržti ir judėti į priedangą.", "TCCC 2026 TFC 3: turniketu stabdomam kraujavimui ir trauminei amputacijai – turniketas tiesiai ant odos 5–7,5 cm virš kraujavimo vietos; nepakanka – antras turniketas greta.", "TCCC 2026 TFC 6a: veiksmingas turniketas – kraujavimas sustojęs ir (jei nėra amputacijos) distalinio pulso nėra; laiką žymėti nenuplaunamu žymekliu ant turniketo ir DD 1380 kortelėje."], "vaizdai": [{"src": "img/tccc/cls3__cls-skill-card-3-5-two-handed-windlass-tourniquet-care-under-fire-en.webp", "orig": "https://tccc.org.ua/files/uploads/cls3/cls-skill-card-3-5-two-handed-windlass-tourniquet-care-under-fire-en.jpg", "cap": "Turniketas draugui CUF metu: aukštai ant uniformos, sukti, kol sustos kraujavimas (< 1 min), tada – į priedangą"}, {"src": "img/tccc/CLS6__cls-skill-card-6-3-two-handed-windlass-tq-tfc-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS6/cls-skill-card-6-3-two-handed-windlass-tq-tfc-en.jpg", "cap": "Turniketas TFC metu: atidengti žaizdą, dėti 5–7,5 cm virš jos tiesiai ant odos, pritvirtinti per 3 min, užrašyti laiką, pildyti DD 1380"}, {"src": "img/tccc/CLS6__cls-skill-card-6-2-two-handed-ratchet-tq-tfc-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS6/cls-skill-card-6-2-two-handed-ratchet-tq-tfc-en.jpg", "cap": "Krumpliaratinis turniketas TFC metu: 5–7,5 cm virš žaizdos ant odos, veržti svirtimi, laiką rašyti ant juostos"}], "video": [{"url": "https://tccc.org.ua/files/uploads/cls3/mv3-5-eng.mp4", "title": "3.5 Two-Handed Windlass Tourniquet Application (Care Under Fire)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/two-handed-windlass-tourniquet-care-under-fire", "note": "Turniketas draugui abiem rankomis apšaudymo metu – aukštai ir tampriai"}, {"url": "https://tccc.org.ua/files/uploads/CLS6/video6-3-en.mp4", "title": "6.3 Two-handed Windlass TQ TFC", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/two-handed-windlass-tq-tfc", "note": "Turniketas tiesiai ant odos TFC metu, laiko žymėjimas ir DD 1380"}], "kortele": {"url": "https://tccc.org.ua/en/guide/two-handed-windlass-tq-tfc", "pav": "CLS 6.3 Two-handed Windlass TQ TFC"}, "saltiniai": ["TCCC gairės 2026-05-01 (CUF 6; TFC 3, 6a)", "JTS CLS kortelės 3.5 Two-Handed Windlass Tourniquet (CUF), 6.3 Two-Handed Windlass TQ (TFC), 6.2 Two-Handed Ratchet TQ (TFC)", "M. Grinevičiaus kursas – „Kraujavimo stabdymas“, „Masyvus kraujavimas (M)“, „Kraujotaka (C)“"]},
  {"id": 6, "grupe": "M", "pav": "Žaizdos tamponavimas ir spaudžiamasis tvarstis", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Kraujavimas iš vietos, kur turniketo uždėti negalima ar jo nereikia, stabdomas tamponuojant žaizdą hemostatiniu tvarsčiu, ne trumpiau kaip 3 min spaudžiant ir uždedant spaudžiamąjį tvarstį. Tamponavimo tikslas – ne užkimšti skylę, o sukurti spaudimą žaizdos viduje ir prispausti kraujagyslę prie kaulo ar kitų tvirtų audinių. Tai užtrunka, todėl daroma TFC metu, ne apšaudymo metu; tuo pačiu būdu atliekama ir turniketo konversija (#8).", "esme": ["Pirmo pasirinkimo hemostatinis tvarstis – Combat Gauze (ar kitas CoTCCC rekomenduojamas); nesant – marlė ar švarus sausas audinys.", "Tamponuokite tiesiai ant labiausiai kraujuojančios vietos ir užpildykite visą žaizdos ertmę; dažnai prireikia daugiau nei vieno tvarsčio.", "Tamponas turi kyšoti 2,5–5 cm (1–2 col.) virš odos; jei ne – pridėkite.", "Po tamponavimo spauskite ≥ 3 min ir neatleiskite, net jei tvarstis permirko.", "Kraujavimas nesustojo: hemostatinį tvarstį išimkite ir tamponuokite iš naujo; marlės – pridėkite ir spauskite dar 3 min.", "Spaudžiamasis tvarstis neturi tapti turniketu: šalta, melsva, tirpsta galūnė ar dingo distalinis pulsas – atlaisvinkite ir uždėkite iš naujo; kraujavimui atsinaujinus gali prireikti turniketo.", "Įsmigusio daikto netraukite – sutvirtinkite jį tvarsčiu vietoje."], "zingsniai": ["Jei įmanoma, užsimaukite pirštines. Atidenkite žaizdą (prakirpkite drabužius, nuimkite ekipuotę).", "Raskite labiausiai kraujuojančią vietą ir iškart spauskite tiesiogiai; jei įmanoma, išsemkite iš žaizdos kraują ir krešulius, kad matytumėte šaltinį.", "Atplėškite hemostatinį tvarstį (nesant – marlė ar švarus sausas audinys).", "Tamponuokite tvirtai tiesiai į kraujavimo vietą: tvarsčio galą pirštu prispauskite prie šaltinio ir, neatleisdami spaudimo, kitu pirštu kiškite vis naują porciją, kol užpildysite visą ertmę.", "Patikrinkite, ar tamponas kyšo 2,5–5 cm virš odos; jei ne – pridėkite tvarsčio.", "Tvirtai spauskite rankomis ne trumpiau kaip 3 min.", "Neatleisdami spaudimo patikrinkite, ar kraujas nesisunkia pro tvarstį ar aplink jį. Kraujuoja: hemostatinį tvarstį išimkite ir tamponuokite iš naujo; marlės – pridėkite ir spauskite dar 3 min.", "Išimkite spaudžiamąjį tvarstį iš pakuotės ir, toliau spausdami, pagalvėlę uždėkite tiesiai ant žaizdos ar tampono.", "Elastinę juostą tampriai vyniokite aplink galūnę, spaudimą sutelkdami ant žaizdos ir uždengdami pagalvėlės kraštus. Su spaudimo plokštele: juostą praveskite pro ją, patempkite ir atlenkite atgal per viršų, kad plokštelė spaustų pagalvėlę.", "Juostos galą pritvirtinkite kabliukais ar fiksatoriumi prie paskutinės vijos.", "Patikrinkite kraujotaką žemiau tvarsčio: distalinis pulsas, odos spalva, šiluma, jutimas. Šalta, melsva, tirpsta ar pulso nėra – atlaisvinkite ir uždėkite iš naujo.", "Užpildykite DD 1380 kortelę; po kiekvieno perkėlimo ir evakuacijos metu tikrinkite, ar tvarstis neprakraujavo."], "klaidos": ["Marlė uždedama ant paviršiaus, užuot tamponavus iki kraujavimo šaltinio; ertmė lieka neužpildyta.", "Spaudžiama trumpiau nei 3 min arba spaudimas atleidžiamas „pažiūrėti“.", "Ant prakraujavusio hemostatinio tvarsčio dedami nauji sluoksniai, užuot jį išėmus ir tamponavus iš naujo.", "Spaudžiamasis tvarstis suveržiamas per stipriai ir netikrinama distalinė kraujotaka.", "Hemostatinis tvarstis kemšamas į krūtinės žaizdą – jai skirtas krūtinės lipdukas (#15).", "Įsmigęs daiktas ištraukiamas."], "tccc": ["TCCC 2026 TFC 3: suspaudžiamam (jungties vietų ar turniketui netinkamam) kraujavimui – CoTCCC rekomenduojamas hemostatinis tvarstis (pirmas pasirinkimas – Combat Gauze) ir ne trumpiau kaip 3 min tiesioginis spaudimas.", "TCCC 2026 TFC 3: sustabdžius kraujavimą pakartotinai vertinti hemoraginio šoko požymius – sutrikusi sąmonė (be galvos traumos) ir silpnas ar nečiuopiamas radialinis pulsas.", "TCCC 2026 TFC 13–14: apžiūrėti ir sutvarstyti žinomas žaizdas, ieškoti papildomų."], "vaizdai": [{"src": "img/tccc/CLS6__cls-skill-card-6-4-wound-packing-pressure-bandage-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS6/cls-skill-card-6-4-wound-packing-pressure-bandage-en.jpg", "cap": "Tamponavimas ir spaudžiamasis tvarstis: tamponuoti ant kraujavimo šaltinio, spausti ≥ 3 min, tvarstyti ir patikrinti distalinį pulsą"}, {"src": "img/tccc/CLS6__cls-skill-card-9-2-wound-packing-pressure-bandage-1-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS6/cls-skill-card-9-2-wound-packing-pressure-bandage-1-en.jpg", "cap": "Teisingai – užpildyta visa žaizdos ertmė, tamponas kyšo 2,5–5 cm virš odos; neteisingai – marlė tik paviršiuje"}, {"src": "img/tccc/CLS6__cls-skill-card-9-2-wound-packing-pressure-bandage-2-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS6/cls-skill-card-9-2-wound-packing-pressure-bandage-2-en.jpg", "cap": "Spaudžiamasis tvarstis: pagalvėlė ant tampono, juosta tampriai dengia kraštus, su spaudimo plokštele – atlenkiama atgal; tikrinti kraujotaką"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS6/video6-4-en.mp4", "title": "6.4 Wound Packing and Pressure Bandage", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/cls-pressure-dressing", "note": "Žaizdos tamponavimas hemostatiniu tvarsčiu ir spaudžiamasis tvarstis"}, {"url": "https://tccc.org.ua/files/uploads/CLS9/video9-2-en.mp4", "title": "9.2 Wound Packing and Pressure Bandage", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/cls-pressure-bandage", "note": "Tas pats įgūdis C etape: pakartotinis tamponavimas ir tvarstymas, kraujotakos patikra"}], "kortele": {"url": "https://tccc.org.ua/en/guide/cls-pressure-dressing", "pav": "CLS 6.4 Wound Packing and Pressure Bandage"}, "saltiniai": ["TCCC gairės 2026-05-01 (TFC 3, 13–14)", "JTS CLS kortelės 6.4 ir 9.2 Wound Packing and Pressure Bandage", "M. Grinevičiaus kursas – „Masyvus kraujavimas (M)“, „Visa kita (W, S ir t. t.)“"]},
  {"id": 7, "grupe": "M", "pav": "Kraujavimas iš jungties vietų: kaklas, pažastis, kirkšnis", "lygis": "CLS", "fazes": ["TFC"], "aprasas": "Kaklo, pažasties ir kirkšnies (jungties vietų) kraujavimo galūnės turniketu sustabdyti negalima, bet jį galima suspausti: iškart tiesioginis spaudimas, tamponavimas hemostatiniu tvarsčiu per ~90 s, spaudimas ≥ 3 min ir sričiai pritaikytas tvarstymas. Kirkšniai CLS lygyje dar naudojamas improvizuotas spaudimo įtaisas (PDD, pvz., gertuvė) su turniketu aplink klubus. Specialų jungties turniketą (pvz., SAM JT) deda CMC lygio medikai.", "esme": ["Kol ruošiate priemones, spauskite iškart: kirkšnį – delnu, kumščiu, alkūne ar keliu; tamponavimą baikite per ~90 s.", "Tamponas turi kyšoti 2,5–5 cm virš odos; spauskite ≥ 3 min. Nesustojo – hemostatinį tvarstį išimkite ir tamponuokite iš naujo, marlės – pridėkite ir spauskite dar 3 min.", "Kaklas: elastinis tvarstis per tamponą ir įstrižai po priešinga pažastimi; spaudimo plokštelės ant kaklo nenaudokite.", "Pažastis: geriausia, kai nukentėjusysis sėdi; ranka atitraukta 90° (padėta ant jūsų peties); tvarstis du kartus aplink petį ir aštuoniuke per nugarą po priešinga pažastimi.", "Kirkšnis: PDD į kirkšnies duobę ant tampono, per jo vidurį – turniketas aplink klubus (ar du sujungti), sagtis kūno vidurio link; veržkite, kol kraujavimas sustos ir dings distalinis pulsas.", "Kaklą ar pažastį sutvarsčius, sužeistos pusės žastą pririškite prie krūtinės; nuolat stebėkite, ar kraujavimas neatsinaujino – jungties vietų sužalojimas reikalauja skubios evakuacijos."], "zingsniai": ["Atidenkite sužalojimą (prakirpkite drabužius; pažasčiai – pakelkite ranką) ir raskite kraujavimo šaltinį.", "Iškart spauskite tiesiogiai (kaklą – tvarsčiu iš sužeistojo IFAK, kirkšnį – delnu, kumščiu ar alkūne) ir atplėškite hemostatinį tvarstį.", "Pažastis: sužeistojo ranką atitraukite 90° ir padėkite ant savo peties.", "Tamponuokite tvirtai, kol užpildysite visą ertmę (per ~90 s); tamponas turi kyšoti 2,5–5 cm virš odos.", "Spauskite ≥ 3 min ir, neatleisdami spaudimo, patikrinkite. Kraujuoja – hemostatinį tvarstį išimkite ir tamponuokite iš naujo; marlės – pridėkite ir spauskite dar 3 min.", "Kaklas: elastinį tvarstį uždėkite ant tampono, palikdami galą mazgui; spausdami vyniokite per tamponą (ne mažiau kaip 1,5 karto), tada įstrižai per krūtinę po priešinga pažastimi, aplink nugarą ir vėl per žaizdą; tempkite tampriai. Spaudimo plokštelės nenaudokite.", "Pažastis: spausdami tamponą, spaudžiamąjį tvarstį du kartus apvyniokite aplink petį, uždengdami tamponą, tada per nugarą po priešinga pažastimi ir aplink priešingą petį – aštuoniuke.", "Kaklas ir pažastis: galus suriškite neslystančiu mazgu (ar užsekite fiksatorių), mazgą apvyniokite pleistru ≥ 1,5 karto; sužeistos pusės žastą skarele pririškite prie krūtinės.", "Kirkšnis: neatleisdami spaudimo, į kirkšnies duobę ant tampono įstatykite PDD (pvz., gertuvę); parinkite turniketą, kuris apjuostų klubus, arba sujunkite du.", "Turniketą uždėkite per PDD vidurį, sagtį nukreipę į kūno vidurį; laisvumą pašalinkite stumdami juostą per kūną ir veržkite, kol kraujavimas sustos ir distalinio pulso nebus.", "Apžiūrėkite, ar PDD nepasislinko ir ar veržtuvas ar krumpliaratis yra virš jo.", "Toliau stebėkite kraujavimą (ypač po kiekvieno perkėlimo), užpildykite DD 1380 kortelę."], "klaidos": ["Laukiama priemonių ir nespaudžiama iškart – jungties vietų kraujavimas žudo per kelias minutes.", "Marlė dedama tik ant paviršiaus arba spaudžiama trumpiau nei 3 min.", "Ant kaklo naudojama spaudimo plokštelė arba tvarstis vyniojamas vien aplink kaklą, ne per priešingą pažastį.", "Kirkšnyje PDD pasislenka nuo kirkšnies duobės arba turniketo veržtuvas atsiduria ne virš PDD.", "Po perkėlimo nepatikrinama, ar tvarstis ir PDD nepasislinko."], "tccc": ["TCCC 2026 TFC 3: suspaudžiamam (jungties vietų) kraujavimui – hemostatinis tvarstis (Combat Gauze – pirmas pasirinkimas) ir ≥ 3 min tiesioginis spaudimas; jungties vietai – jungties turniketas, jei jis yra (CMC).", "TCCC 2026 TFC 3: iTClamp galima naudoti suspaudžiamoms galvos ir kaklo žaizdoms, bet ne ant akies ar šalia jos.", "TCCC 2026 TFC 6a: jungties turniketai konvertuojami kaip ir galūnių, kai tenkinami visi 3 kriterijai (#8)."], "vaizdai": [{"src": "img/tccc/CLS6__cls-skill-card-6-5-neck-junctional-hemorrhage-control-1-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS6/cls-skill-card-6-5-neck-junctional-hemorrhage-control-1-en.jpg", "cap": "Kaklo kraujavimas: tamponuoti per 90 s, spausti ≥ 3 min, elastinį tvarstį vynioti per tamponą ir įstrižai po priešinga pažastimi"}, {"src": "img/tccc/CLS6__cls-skill-card-6-6-axillary-junctional-hemorrhage-control-2-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS6/cls-skill-card-6-6-axillary-junctional-hemorrhage-control-2-en.jpg", "cap": "Pažasties kraujavimas: tvarstis aplink petį ir aštuoniuke per nugarą, žastas skarele pririštas prie krūtinės"}, {"src": "img/tccc/CLS6__cls-skill-card-6-7-inguinal-hemorrhage-control-2-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS6/cls-skill-card-6-7-inguinal-hemorrhage-control-2-en.jpg", "cap": "Kirkšnies kraujavimas: turniketas per improvizuoto spaudimo įtaiso (gertuvės) vidurį, veržti, kol dings kraujavimas ir distalinis pulsas"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS6/video6-5-en.mp4", "title": "6.5 Neck Junctional Hemorrhage Control", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/neck-junctional-hemorrhage-control", "note": "Kaklo žaizdos tamponavimas ir tvarstymas per priešingą pažastį"}, {"url": "https://tccc.org.ua/files/uploads/CLS6/video6-7-en.mp4", "title": "6.7 Inguinal Hemorrhage Control with Improvised Junctional Pressure Device", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/pressure-delivery-devices-pdd-for-junctional-hemorrhage", "note": "Kirkšnies kraujavimas: tamponavimas ir improvizuotas spaudimo įtaisas su turniketu"}], "kortele": {"url": "https://tccc.org.ua/en/guide/neck-junctional-hemorrhage-control", "pav": "CLS 6.5 Neck Junctional Hemorrhage Control"}, "saltiniai": ["TCCC gairės 2026-05-01 (TFC 3, 6a)", "JTS CLS kortelės 6.5 Neck, 6.6 Axillary Junctional Hemorrhage Control, 6.7 Inguinal Hemorrhage Control (improvised junctional pressure device)", "M. Grinevičiaus kursas – „Masyvus kraujavimas (M)“, „Kraujavimo stabdymas“"]},
  {"id": 8, "grupe": "M", "pav": "Turniketo pakeitimas ir konversija", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "TFC metu kiekvienas anksčiau (ypač CUF metu „aklai“ ant drabužių) uždėtas turniketas atidengiamas ir įvertinamas: ar jo reikia, ar jis veikia ir ar ne per aukštai. Reikalingą turniketą pakeiskite nauju ant odos 5–7,5 cm virš žaizdos, o kai įmanoma – per 2 val. konvertuokite į hemostatinį ar spaudžiamąjį tvarstį, kad galūnė būtų išsaugota. Karo patirtis rodo, kad dalis turniketų uždedama ten, kur pakaktų tamponavimo ar spaudžiamojo tvarsčio.", "esme": ["Konversija – tik jei tenkinami visi 3: nukentėjusysis nėra šoke, žaizdą galima atidžiai stebėti, turniketas nestabdo kraujavimo iš amputuotos galūnės.", "Konversiją stenkitės atlikti per < 2 val. CLS po 2 val. konversijos nebando, nebent nurodo CMC ar aukštesnio lygio medikas – turniketas paliekamas ir stebimas iki aukštesnio lygio pagalbos.", "Turniketo, išbuvusio > 6 val., lauke nenuimkite.", "Pakeitimas: naują turniketą uždėkite ant odos 5–7,5 cm virš žaizdos, senąjį lėtai (~1 min) atlaisvinkite ir palikite virš naujojo – be laisvumo, bet neveržtą.", "Konversija: tamponavimas, spaudimas ≥ 3 min, spaudžiamasis tvarstis, tada lėtai (~1 min) atlaisvinkite turniketą ir stebėkite; kraujavimas atsinaujino – vėl suveržkite.", "Nereikalingą turniketą nuimkite. Visus laikus (uždėjimo, pakartotinio uždėjimo, konversijos, nuėmimo) rašykite nenuplaunamu žymekliu ant turniketo ir DD 1380 kortelėje.", "Konvertuotą galūnę stebėkite po kiekvieno perkėlimo ir visą evakuaciją; apie konversiją ir laikus praneškite evakuacijos ekipažui."], "zingsniai": ["Jei įmanoma, užsimaukite pirštines. Atidenkite sužalojimą ir įvertinkite kraujavimo šaltinį bei kiekvieną turniketą: ar stabdo kraujavimą ir ar ne per toli (aukštai) nuo žaizdos.", "Patikrinkite distalinį pulsą: juntamas – pabandykite suveržti stipriau; vis dar juntamas – iškart dėkite naują turniketą.", "Pakeitimas: naują CoTCCC rekomenduojamą turniketą uždėkite tiesiai ant odos 5–7,5 cm virš kraujavimo vietos (#5).", "Senąjį turniketą lėtai atlaisvinkite per ~1 min, stebėdami žaizdą. Kraujavimas atsinaujino – iškart vėl suveržkite senąjį, naująjį suveržkite stipriau ir kartokite.", "Įsitikinkite, kad kraujavimas sustojęs ir distalinio pulso nėra; senąjį turniketą palikite virš naujojo – be laisvumo, bet neveržtą. Ant naujojo užrašykite jo uždėjimo laiką, o kortelėje palikite ir pirmojo turniketo laiką – 2 ir 6 val. ribas skaičiuokite nuo pirmojo uždėjimo.", "Konversija (tik jei nėra šoko, žaizdą galima stebėti ir tai ne amputacija; per < 2 val.): atplėškite hemostatinį tvarstį (nesant – marlė ar švarus audinys).", "Tvirtai tamponuokite visą žaizdos ertmę, kad tamponas kyšotų 2,5–5 cm virš odos; įsmigusio daikto netraukite – sutvirtinkite jį vietoje.", "Spauskite ≥ 3 min, tada uždėkite spaudžiamąjį tvarstį: pagalvėlė ant tampono, tampriai vyniokite uždengdami kraštus, pritvirtinkite (#6).", "Turniketą LĖTAI atlaisvinkite per ~1 min, stebėdami, ar tvarstis neprakraujuoja; atlaisvintą palikite ant galūnės.", "Kraujavimas atsinaujino – vėl suveržkite turniketą, kol kraujavimas sustos ir dings distalinis pulsas.", "Įrašykite laikus ant turniketo ir DD 1380 kortelėje (uždėjimas, pakeitimas, konversija, nuėmimas).", "Po kiekvieno perkėlimo ir evakuacijos metu tikrinkite tvarstį ir galūnę; perduodami nukentėjusįjį praneškite apie konversiją ir laikus."], "klaidos": ["CUF metu uždėtas turniketas valandų valandas paliekamas ant drabužių nepatikrintas – didėja rizika netekti galūnės.", "Konvertuojama nukentėjusiajam, kuris yra šoke, esant amputacijai arba kai žaizdos nebus galima stebėti.", "Turniketas atlaisvinamas staigiai ir nestebimas kraujavimas; atlaisvintas turniketas nuimamas visai.", "CLS bando konvertuoti po 2 val. be CMC ar aukštesnio lygio mediko nurodymo; nuimamas ilgiau nei 6 val. uždėtas turniketas.", "Nedokumentuojami laikai – kitas pagalbos lygis nežino, kiek laiko galūnė be kraujotakos."], "tccc": ["TCCC 2026 TFC 6a: pakartotinai įvertinti turniketus – reikalingą pakeisti nauju ant odos 5–7,5 cm virš kraujavimo vietos ir tik tada atlaisvinti pirmąjį; nereikalingą nuimti ir užrašyti laiką.", "TCCC 2026 TFC 6a: galūnių ir jungties turniketus kuo skubiau konvertuoti, jei nėra šoko, žaizdą galima atidžiai stebėti ir tai ne amputacija; siekti per 2 val.; > 6 val. turniketo nenuimti, nebent yra atidi stebėsena ir laboratorija.", "TCCC 2026 TFC 6a: ASM ir CLS personalas po 2 val. konversijos nebando, nebent nurodo CMC, CPP ar aukštesnio lygio medikas – kitaip turniketas paliekamas ir stebimas.", "TCCC 2026 TFC 6a: turniketai ant amputuotų galūnių nekonvertuojami."], "vaizdai": [{"src": "img/tccc/CLS9__cls-skill-card-9-1-1-tourniquet-conversion-1-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS9/cls-skill-card-9-1-1-tourniquet-conversion-1-en.jpg", "cap": "Turniketo konversija (1): tamponuoti visą ertmę, tamponas kyšo 2,5–5 cm, spausti ≥ 3 min, uždėti spaudžiamąjį tvarstį"}, {"src": "img/tccc/CLS9__cls-skill-card-9-1-1-tourniquet-conversion-2-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS9/cls-skill-card-9-1-1-tourniquet-conversion-2-en.jpg", "cap": "Turniketo konversija (2): turniketą lėtai atlaisvinti per 1 min stebint tvarstį; konvertuoti per < 2 val., > 6 val. turniketo nenuimti"}, {"src": "img/tccc/CLS9__cls-skill-card-9-1-2-tourniquet-replacement-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS9/cls-skill-card-9-1-2-tourniquet-replacement-en.jpg", "cap": "Turniketo pakeitimas: naujas turniketas ant odos 5–7,5 cm virš žaizdos, senasis lėtai atlaisvinamas ir paliekamas virš naujojo"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS9/video9-1-en.mp4", "title": "9.1 Hemorrhage Control in TFC", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/hemorrhage-control-in-tfc", "note": "Turniketų pakartotinis vertinimas, pakeitimas ir konversija TFC metu"}], "kortele": {"url": "https://tccc.org.ua/en/guide/hemorrhage-control-in-tfc", "pav": "CLS 9.1 Hemorrhage Control in TFC (Tourniquet Conversion, Tourniquet Replacement)"}, "saltiniai": ["TCCC gairės 2026-05-01 (TFC 3a, 6a)", "JTS CLS kortelės 9.1.1 Tourniquet Conversion ir 9.1.2 Tourniquet Replacement", "M. Grinevičiaus kursas – „Kraujotaka (C)“, „TCCC gairės“"]},
  {"id": 9, "grupe": "A", "pav": "Kvėpavimo takų atvėrimas: galvos atlošimas ir žandikaulio stūmimas", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Kvėpavimo takų nepraeinamumas – antra pagal dažnį potencialiai mirtina problema mūšio lauke: nesąmoningam, gulinčiam ant nugaros, liežuvio šaknis užveria kvėpavimo takus (girdimas knarkimas, gargaliavimas). Rankomis kvėpavimo takai atveriami galvos atlošimu ir smakro pakėlimu, o įtarus kaklo ar stuburo traumą – žandikaulio stūmimu. Atvėrus vertinamas kvėpavimas („žiūrėk, klausyk, jausk“), o nesąmoningas guldomas į stabilią šoninę padėtį (#10).", "esme": ["Kalba, rėkia ar verkia – kvėpavimo takai laisvi; vis tiek stebėkite, nes būklė gali bet kada pasikeisti.", "Nepraeinamumo požymiai: veido ir žandikaulių trauma, kraujas ar svetimkūniai burnoje, sako negalintis kvėpuoti, knarkimas ar gargaliavimas.", "Matomus svetimkūnius ir vėmalus pašalinkite (vėmalus – paguldę ant šono); aklai pirštais burnos nevalykite.", "Galvos atlošimas ir smakro pakėlimas – kai kaklo ar stuburo trauma neįtariama; žandikaulio stūmimas – kai ji įtariama (bukas smūgis, kritimas, sprogimas, eismo įvykis). Esant tik penetruojančiai traumai, kaklo stabilizuoti nereikia.", "Sąmoningas su veido trauma: neguldykite per prievartą – leiskite sėdėti pasilenkus į priekį, kad kraujas tekėtų lauk.", "Kvėpavimo dažnį skaičiuokite 15 s ir padauginkite iš 4; nepakankamas kvėpavimas – NPA ir ventiliacija ambu maišu (#11, #12)."], "zingsniai": ["Užkalbinkite: atsako aiškiai – kvėpavimo takai laisvi. Neatsako – jei reikia, paverskite ant nugaros ant kieto, lygaus paviršiaus.", "Atverkite burną ir apžiūrėkite: matomus svetimkūnius, kraują ar vėmalus pašalinkite (paguldę ant šono); aklai pirštais nekrapštykite.", "Galvos atlošimas ir smakro pakėlimas (kaklo trauma neįtariama): atsiklaupkite šone ties pečiais, delną uždėkite ant kaktos ir tvirtai atloškite galvą.", "Kitos rankos pirštų galiukus pakiškite po kauline apatinio žandikaulio dalimi ir pakelkite smakrą į priekį.", "Žandikaulio stūmimas (įtariama kaklo ar stuburo trauma): atsiklaupkite už galvos, žiūrėdami į kojas, alkūnes atremkite į žemę.", "Delnus uždėkite abipus apatinio žandikaulio žemiau ausų, dilbiais stabilizuokite galvą.", "Smiliais kelkite apatinį žandikaulį aukštyn, nykščiais stumkite smakrą į priekį; galvos neatloškite.", "Išlaikydami atvertus kvėpavimo takus, priglauskite ausį prie burnos ir nosies, veidu į krūtinę: žiūrėkite, ar kyla krūtinė, klausykite iškvepiamo oro, jauskite oro srovę skruostu.", "Suskaičiuokite kvėpavimo dažnį (15 s × 4).", "Toliau: nesąmoningą be obstrukcijos guldykite į stabilią šoninę padėtį (#10); kvėpavimas nepakankamas – NPA ir ventiliacija ambu maišu (#11, #12).", "Užpildykite DD 1380 kortelę; evakuacijos metu ir po kiekvieno perkėlimo vėl patikrinkite kvėpavimo takus ir kvėpavimą."], "klaidos": ["Galva atlošiama, nors įtariama kaklo ar stuburo trauma (bukas smūgis, kritimas, sprogimas).", "Smakras keliamas spaudžiant minkštuosius audinius po smakru – kvėpavimo takai užspaudžiami.", "Burna aklai valoma pirštais.", "Atleidus manevrą kvėpavimo takai vėl užsiveria – nesąmoningas paliekamas gulėti ant nugaros be priežiūros.", "Sąmoningas sužeistasis su veido trauma per prievartą guldomas ant nugaros."], "tccc": ["TCCC 2026 TFC 4: įvertinti kvėpavimo takų praeinamumą; esant ar gresiant trauminei obstrukcijai – ruoštis tiesioginei kvėpavimo takų intervencijai (krikotiroidotomija – CMC).", "TCCC 2026 TFC 4: sąmoningas gali užimti bet kokią kvėpavimo takus geriausiai apsaugančią padėtį (ir sėdėti pasilenkęs); nesąmoningas – stabili šoninė padėtis, galva atlošta; atsiurbti, jei yra kuo.", "TCCC 2026 TFC 4: kaklo stuburo stabilizacija nebūtina, jei trauma tik penetruojanti.", "TCCC 2026 TFC 17: sprogimo ar penetruojančios traumos nukentėjusiajam be pulso, kvėpavimo ir kitų gyvybės ženklų gaivinimas TFC metu nebandomas; liemens traumos atveju prieš nutraukiant pagalbą – abipusė adatinė dekompresija."], "vaizdai": [{"src": "img/tccc/CLS7__cls-skill-card-7-1-head-tilt-chin-lift-airway-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS7/cls-skill-card-7-1-head-tilt-chin-lift-airway-en.jpg", "cap": "Galvos atlošimas ir smakro pakėlimas: delnas ant kaktos, pirštų galiukai po kauline apatinio žandikaulio dalimi; tada „žiūrėk, klausyk, jausk“ ir kvėpavimo dažnis per 15 s"}, {"src": "img/tccc/CLS7__cls-skill-card-7-1-jaw-thrust-maneuvers-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS7/cls-skill-card-7-1-jaw-thrust-maneuvers-en.jpg", "cap": "Žandikaulio stūmimas įtarus kaklo ar stuburo traumą: gelbėtojas už galvos, alkūnės ant žemės, smiliai kelia žandikaulį, nykščiai stumia smakrą"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS7/video7-1-en.mp4", "title": "7.1 Head-Tilt/Chin-Lift and Jaw-Thrust Maneuvers", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/head-tiltchin-lift-and-jaw-thrust-maneuvers", "note": "Galvos atlošimas su smakro pakėlimu, žandikaulio stūmimas ir kvėpavimo vertinimas"}], "kortele": {"url": "https://tccc.org.ua/en/guide/head-tiltchin-lift-and-jaw-thrust-maneuvers", "pav": "CLS 7.1 Head-Tilt/Chin-Lift and Jaw-Thrust Maneuvers"}, "saltiniai": ["TCCC gairės 2026-05-01 (TFC 4, 17)", "JTS CLS kortelės 7.1 Head-Tilt/Chin-Lift ir Jaw-Thrust Maneuver", "JTS CLS 5 modulis „Tactical Trauma Assessment“ (kvėpavimo takų nepraeinamumo požymiai)", "M. Grinevičiaus kursas – „Atviri kvėpavimo takai (A)“"]},
  {"id": 10, "grupe": "A", "pav": "Stabili šoninė (atsigavimo) padėtis", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Nesąmoningą nukentėjusįjį, kurio kvėpavimo takai neužkimšti, TCCC 2026 nurodo guldyti į stabilią šoninę padėtį, galvą atlošus ir smakrą atitraukus nuo krūtinės. Gulint ant šono liežuvio šaknis ir antgerklis mažiau užveria kvėpavimo takus, o kraujas ir vėmalai išteka lauk, o ne į plaučius. Padėtis turi būti tikrai stabili, nes nukentėjusysis dažnai bus nešamas neštuvais.", "esme": ["Kam: nesąmoningam, kuris kvėpuoja ir neturi kvėpavimo takų obstrukcijos; taip pat įvedus NPA (#11).", "Galva atlošta, smakras atitrauktas nuo krūtinės – taip kvėpavimo takai lieka atviri.", "Sąmoningo per prievartą neguldykite: jis gali sėdėti ar pasilenkti į priekį – kaip jam lengviau kvėpuoti.", "Esant krūtinės sužeidimui, guldykite ant sužeistos pusės (M. Grinevičius).", "Rankos ir kojos neturi kyšoti už neštuvų krašto ir už nieko kliūti nešant.", "Nuolat stebėkite kvėpavimą; po kiekvieno perkėlimo patikrinkite padėtį, kvėpavimo takus, turniketus ir tvarsčius."], "zingsniai": ["Paguldykite nukentėjusįjį ant nugaros, nesukeldami papildomų sužalojimų, ir atsiklaupkite šone.", "Jums artimesnę jo ranką padėkite stačiu kampu į kūną, sulenktą per alkūnę, delnu aukštyn.", "Tolimesnės rankos plaštakos nugarėlę priglauskite prie jums artimesnio skruosto ir laikykite ją ten savo ranka – taip verčiant prilaikysite galvą.", "Tolimesnę koją sulenkite per kelį, kad pėda remtųsi į žemę.", "Atsargiai traukite sulenktą kelį į save – nukentėjusysis apsivers ant šono veidu į jus; galvą prilaikykite.", "Sulenktą koją padėkite priekyje taip, kad keliu remtųsi į žemę – padėtis taps stabili.", "Švelniai kilstelėkite smakrą ir šiek tiek atloškite galvą (smakras atitrauktas nuo krūtinės), kad skysčiai laisvai ištekėtų iš burnos.", "Patikrinkite kvėpavimą („žiūrėk, klausyk, jausk“) ir sutvarkykite galūnes, kad nekyšotų (ruošiant neštuvams).", "Užpildykite DD 1380 kortelę; nuolat stebėkite kvėpavimą, evakuacijos metu ir po kiekvieno perkėlimo patikrinkite padėtį ir kvėpavimo takus."], "klaidos": ["Nesąmoningas paliekamas gulėti ant nugaros – liežuvis, kraujas ar vėmalai užkemša kvėpavimo takus.", "Galva palenkta, smakras prie krūtinės – kvėpavimo takai susiaurėja.", "Padėtis nestabili: nukentėjusysis nusiverčia ant nugaros ar ant veido, rankos kyšo už neštuvų krašto.", "Sąmoningas sužeistasis per prievartą guldomas, nors sėdėdamas kvėpuoja lengviau.", "Paguldytas nukentėjusysis paliekamas be priežiūros – nebestebimas kvėpavimas."], "tccc": ["TCCC 2026 TFC 4: nesąmoningą nukentėjusįjį guldyti į stabilią šoninę padėtį, galva atlošta, smakras atitrauktas nuo krūtinės; sąmoningam leisti užimti kvėpavimo takus geriausiai apsaugančią padėtį (ir sėdėti pasilenkus).", "TCCC 2026 TFC 5: įtariant įtampos pneumotoraksą – guldyti ant nugaros ar į stabilią šoninę padėtį, nebent sąmoningam dėl veido traumos reikia sėdėti.", "TCCC 2026 TFC 20: ruošiant evakuacijai pritvirtinti užklotus ir neštuvų diržus, ilgai evakuacijai – paminkštinti."], "vaizdai": [{"src": "img/tccc/CLS7__cls-skill-card-7-6-recovery-position-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS7/cls-skill-card-7-6-recovery-position-en.jpg", "cap": "Stabili šoninė padėtis: ranka stačiu kampu, kitos plaštakos nugarėlė prie skruosto, kelias sulenktas, verčiama į save, galva šiek tiek atlošta"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc7/recovery-position-en.mp4", "title": "7.2 Recovery Position", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/recovery-position-cmc", "note": "Stabilios šoninės padėties demonstracija (JTS CMC)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/recovery-position-cls", "pav": "CLS 7.6 Recovery Position"}, "saltiniai": ["TCCC gairės 2026-05-01 (TFC 4, 5, 20)", "JTS CLS kortelė 7.6 Recovery Position", "M. Grinevičiaus kursas – „Atviri kvėpavimo takai (A)“ (stabili šoninė padėtis), „Kvėpavimas (R)“"]},
  {"id": 11, "grupe": "R", "pav": "Nazofaringinis vamzdelis", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Nazofaringinis vamzdelis (NPA) – minkštas vamzdelis, per nosį įvedamas iki ryklės: jis pakelia minkštąjį gomurį ir liežuvio šaknį ir atveria orui kelią, bet nuo aspiracijos neapsaugo. TCCC 2026 gairėse NPA kvėpavimo takų (A) skyriuje nebeminimas – nesąmoningam be obstrukcijos taikoma stabili šoninė padėtis; NPA nurodomas kvėpavimo (R) skyriuje kartu su ventiliacija ambu maišu, kai hipoksijos nepavyksta ištaisyti. Įvedimo techniką tebemoko JTS CLS kortelė ir M. Grinevičiaus kursas, NPA tebėra IFAK sudėtyje.", "esme": ["TCCC 2026: sutrikus ventiliacijai ir esant neištaisomai hipoksijai (SpO₂ < 90 %, su galvos trauma < 92 %) – tinkamo dydžio NPA ir ventiliacija 1000 ml ambu maišu (#12).", "Dydis: vyrams paprastai 28 Fr (7 mm) ar 32 Fr (8 mm), moterims 24 Fr (6 mm) ar 26 Fr (6,5 mm); ilgis – maždaug nuo nosies galo iki ausies spenelio (vyrui ~150 mm, moteriai ~130 mm). Skirtingų gamintojų ilgiai skiriasi.", "Sutepkite vandens pagrindo lubrikantu (nėra – vandeniu ar paties nukentėjusiojo seilėmis); netepkite dalies, kurią laikote pirštais.", "Kiškite statmenai veidui, palei nosies dugną žemyn (ne link viršugalvio), nuožulnų galą nukreipę į nosies pertvarą; paprastai į dešinę šnervę.", "Niekada nestumkite jėga: pasipriešinus – pasukiokite; žiaukčioja – šiek tiek ištraukite; nepavyksta – kita šnervė.", "Įvedus – sėdima ar stabili šoninė padėtis (#10) ir nuolatinis kvėpavimo stebėjimas."], "zingsniai": ["Paguldykite nukentėjusįjį ant nugaros, galva neutralioje padėtyje; atsiklaupkite prie galvos (galite ją fiksuoti tarp kelių).", "Apžiūrėkite nosį ir šnerves – ar nėra kliūčių vamzdeliui.", "Išimkite NPA iš IFAK, parinkite dydį ir sutepkite apatinę dalį vandens pagrindo lubrikantu (nėra – vandeniu).", "Švelniai pakelkite nosies galą aukštyn („paršiuko nosis“), kad atsivertų dešinė šnervė.", "Vamzdelį laikykite taip, kad nuožulnus galas būtų nukreiptas į nosies pertvarą.", "Įveskite į dešinę šnervę 90° kampu į veidą ir vienu tolygiu judesiu stumkite žemyn (link žemės, ne link viršugalvio), kol platusis galas atsirems į šnervę.", "Pasipriešinus – šiek tiek atitraukite, pasukiokite ir vėl švelniai stumkite. Žiaukčioja ar springsta – šiek tiek ištraukite ir palikite. Nepavyksta – ištraukite, vėl sutepkite ir bandykite kairę šnervę.", "Prireikus pritvirtinkite vamzdelį pleistru prie odos.", "Iš naujo įvertinkite kvėpavimą: žiūrėkite, klausykite, jauskite.", "Paguldykite į stabilią šoninę padėtį arba pasodinkite (#10); kvėpavimas nepakankamas – ventiliuokite ambu maišu (#12).", "Užpildykite DD 1380 kortelę; po kiekvieno perkėlimo patikrinkite, ar vamzdelis neiškrito ir ar nukentėjusysis kvėpuoja."], "klaidos": ["Vamzdelis kišamas į viršų (link viršugalvio), o ne palei nosies dugną žemyn.", "Stumiama jėga – kraujavimas iš nosies dar labiau trikdo kvėpavimo takus.", "Vamzdelis nesutepamas arba parenkamas netinkamo ilgio.", "Manoma, kad su NPA kvėpavimo takai apsaugoti, ir nesąmoningas paliekamas gulėti ant nugaros be stebėjimo.", "Dėl NPA vėluojama paguldyti nesąmoningą į stabilią šoninę padėtį."], "tccc": ["TCCC 2026 TFC 5: sutrikusi ventiliacija su neištaisoma hipoksija (SpO₂ < 90 %, su galvos trauma < 92 %) – apsvarstyti tinkamo dydžio NPA ir ventiliaciją 1000 ml ambu maišu.", "TCCC 2026 TFC 4: nesąmoningą nukentėjusįjį guldyti į stabilią šoninę padėtį; NPA kvėpavimo takų skyriuje nebenurodomas.", "TCCC 2026 TFC 8: vidutinės ar sunkios galvos traumos atveju palaikyti SpO₂ ≥ 92 %."], "vaizdai": [{"src": "img/tccc/CLS7__cls-skill-card-7-2-nasopharyngeal-airway-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS7/cls-skill-card-7-2-nasopharyngeal-airway-en.jpg", "cap": "NPA įvedimas: sutepti, nuožulnus galas – į pertvarą, kišti į dešinę šnervę 90° kampu žemyn iki flanšo; po to – sėdima ar stabili šoninė padėtis"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS7/video7-2-en.mp4", "title": "7.2 Nasopharyngeal Airway (NPA) Insertion", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/nasopharyngeal-airway-insertion", "note": "NPA įvedimas per dešinę šnervę ir kvėpavimo įvertinimas"}], "kortele": {"url": "https://tccc.org.ua/en/guide/nasopharyngeal-airway-insertion", "pav": "CLS 7.2 Nasopharyngeal Airway (NPA) Insertion"}, "saltiniai": ["TCCC gairės 2026-05-01 (TFC 4, 5, 8)", "JTS CLS kortelė 7.2 Nasopharyngeal Airway (NPA) Insertion", "M. Grinevičiaus kursas – „Atviri kvėpavimo takai (A)“ (nazofaringinis vamzdelis), „IFAK“"]},
  {"id": 12, "grupe": "R", "pav": "Ventiliacija ambu maišu (1 ir 2 asmenų)", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Ambu maišu (BVM) ventiliuojama, kai nukentėjusysis turi pulsą, bet kvėpuoja nepakankamai ar hipoksijos nepavyksta ištaisyti kitomis priemonėmis. TCCC 2026 nurodo apsvarstyti tinkamo dydžio NPA ir 1000 ml ambu maišą, kai SpO₂ lieka < 90 % (su galvos trauma < 92 %). Vienam sandariai laikyti kaukę ir kartu spausti maišą sunku, todėl, jei yra antras žmogus, ventiliuokite dviese.", "esme": ["Prieš ventiliuodami atverkite kvėpavimo takus (#9), įveskite NPA (#11), sujunkite kaukę su maišu; kaukė turi dengti nosį ir burną.", "Vienas – „EC“ rankena: nykštys ir smilius sudaro „C“ ir prispaudžia kaukę (ties nosies šaknimi ir smakru), likę trys pirštai – „E“ – kelia apatinį žandikaulį į kaukę.", "Dviese: vienas abiem rankomis sandariai laiko kaukę (nykščiai ir smiliai ant kaukės, kiti pirštai palei apatinį žandikaulį), kitas abiem rankomis spaudžia maišą.", "Spauskite 1–2 s, kol pakils krūtinė, kas 5–6 s (10–12 kartų per min.). Galvos trauma be EtCO₂ – 10 kartų per min. (TCCC 2026).", "Krūtinė nekyla – pataisykite kaukę ir iš naujo atverkite kvėpavimo takus (galvos atlošimas, smakro pakėlimas).", "Nepūskite per stipriai ir per dažnai: oras patenka į skrandį, didėja vėmimo ir aspiracijos rizika.", "Ventiliuodami stebėkite, ar neatsirado savarankiškas kvėpavimas, ir periodiškai tikrinkite pulsą."], "zingsniai": ["Atsiklaupkite už nukentėjusiojo galvos.", "Atverkite kvėpavimo takus ir įveskite nazofaringinį vamzdelį (#9, #11).", "Surinkite ambu maišą – kaukę prijunkite prie maišo jungties.", "Vienas: „C“ – nykštį uždėkite ant kaukės dalies ties nosies šaknimi, smilių – ties smakro duobute ir tvirtai prispauskite kaukę prie veido.", "„E“ – likusiais trimis pirštais kelkite apatinį žandikaulį į kaukę (galvos atlošimas, smakro pakėlimas); sandarumą išlaikykite viena ranka.", "Kita ranka spauskite maišą 1–2 s, stebėdami, ar kyla krūtinė; kartokite kas 5–6 s (10–12 kartų per min.). Pavargus maišą galima spausti prie savo kūno ar dilbio.", "Dviese: pirmasis abiem rankomis laiko kaukę – mažasis, bevardis ir didysis pirštai palei apatinį žandikaulį, nykštys ant kaukės viršutinės dalies virš jungties, smilius – ant apatinės dalies po jungtimi.", "Antrasis lėtai spaudžia maišą abiem rankomis 1–2 s, kol pakyla krūtinė, ir kartoja kas 5–6 s (10–12 kartų per min.).", "Stebėkite, ar krūtinė kyla ir leidžiasi; nekyla – pataisykite kaukę, kad būtų sandari, atloškite galvą ir pakelkite smakrą.", "Ventiliuodami stebėkite, ar neatsirado savarankiškas kvėpavimas, ir periodiškai tikrinkite pulsą.", "Užpildykite DD 1380 kortelę ir pritvirtinkite ją prie nukentėjusiojo; perduodami evakuacijos ekipažui pasakykite, kad nukentėjusysis ventiliuojamas, ir ventiliacijos nenutraukite."], "klaidos": ["Nesandari kaukė – oras išeina pro šonus, krūtinė nekyla.", "Pučiama per dažnai ar per stipriai – oras patenka į skrandį, nukentėjusysis vemia, gresia aspiracija.", "Ventiliuojama vienam, nors šalia yra antras žmogus.", "Nestebima, ar kyla krūtinė; nepastebima, kad atsirado savarankiškas kvėpavimas ar dingo pulsas.", "Prieš ventiliaciją neatveriami kvėpavimo takai ir neįvedamas NPA.", "TFC metu gaivinama sprogimo ar penetruojančios traumos auka be pulso, kvėpavimo ir kitų gyvybės ženklų, nors TCCC to nerekomenduoja."], "tccc": ["TCCC 2026 TFC 5: sutrikusi ventiliacija su neištaisoma hipoksija (SpO₂ < 90 %, galvos trauma – < 92 %) – apsvarstyti tinkamo dydžio NPA ir ventiliaciją 1000 ml ambu maišu.", "TCCC 2026 TFC 8: ventiliuojamam su galvos trauma – EtCO₂ 35–45 mmHg; be EtCO₂ – 10 įpūtimų per minutę.", "TCCC 2026 TACEVAC (kvėpavimas): daugumai kovos nukentėjusiųjų papildomo deguonies nereikia; jis naudingas esant mažai SpO₂, galvos traumai, šokui, nesąmoningam, dideliame aukštyje ar įkvėpus dūmų.", "TCCC 2026 TFC 17: sprogimo ar penetruojančios traumos nukentėjusiajam be pulso, kvėpavimo ir kitų gyvybės ženklų gaivinimas TFC metu nebandomas."], "vaizdai": [{"src": "img/tccc/CLS7__cls-skill-card-7-3-1-one-person-bag-valve-mask-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS7/cls-skill-card-7-3-1-one-person-bag-valve-mask-en.jpg", "cap": "Ventiliacija vienam: NPA, „EC“ rankena kaukei laikyti ir žandikauliui kelti, maišą spausti 1–2 s kas 5–6 s"}, {"src": "img/tccc/CLS7__cls-skill-card-7-3-2-two-person-bag-valve-mask-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS7/cls-skill-card-7-3-2-two-person-bag-valve-mask-en.jpg", "cap": "Ventiliacija dviese: vienas abiem rankomis sandariai laiko kaukę, kitas lėtai spaudžia maišą abiem rankomis, kol pakyla krūtinė"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS7/video7-3-en.mp4", "title": "7.3 One and Two Person Bag Valve Mask (BVM)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/one-and-two-person-bag-valve-mask", "note": "Ventiliacija ambu maišu vienam ir dviese"}], "kortele": {"url": "https://tccc.org.ua/en/guide/one-and-two-person-bag-valve-mask", "pav": "CLS 7.3 One and Two Person Bag Valve Mask (BVM)"}, "saltiniai": ["TCCC gairės 2026-05-01 (TFC 5, 8, 17; TACEVAC – kvėpavimas)", "JTS CLS kortelės 7.3.1 One-Person BVM ir 7.3.2 Two-Person BVM", "M. Grinevičiaus kursas – „Atviri kvėpavimo takai (A)“"]},
  {"id": 13, "grupe": "A", "pav": "Krikotiroidotomija", "lygis": "CMC", "fazes": ["TFC", "TACEVAC"], "aprasas": "Chirurginis kvėpavimo takų atvėrimas per krikotiroidinę (žiedinę–skydinę) membraną, kai obstrukcijos nepavyksta pašalinti padėtimi, galvos atlošimu ar žandikaulio išstūmimu ir atsiurbimu – dažniausiai dėl veido ir žandikaulių traumos, kraujo, tiesioginio kvėpavimo takų sužalojimo ar nudegimų. Tai CMC lygio įgūdis; CLS padeda: paduoda priemones, ventiliuoja ambu maišu ir stebi. TACEVAC metu apmokytas personalas vietoj jos gali rinktis intubaciją.", "esme": ["Indikacija (TCCC 2026): obstrukcija išlieka, nors išbandyta padėtis, galvos atlošimas ar žandikaulio išstūmimas ir atsiurbimas – veido ir žandikaulių lūžiai, kvėpavimo takų sužalojimas, kraujas, deformacija, nudegimai (taip pat karštų ir toksiškų dujų įkvėpimas).", "Technika – atvira chirurginė: su bužu arba standartinė atvira. Kaniulė – flanšinė su manžete: išorinis skersmuo < 10 mm, vidinis 6–7 mm, 5–8 cm trachėjoje.", "Orientyras – įduba tarp skydinės ir žiedinės kremzlių. Gerklas stabilizuokite nedominuojančia ranka, membraną tikslinkite smiliumi; vertikalus odos pjūvis ~2,5 cm (1 col.), skersinis per membraną (~1,3 cm anga).", "Padėtį patvirtinkite nuolatine kapnografija (EtCO₂), vienodu krūtinės kilimu ir kvėpavimo garsais abipus. Sąmoningam – vietinis lidokainas.", "Kontraindikacijos (JTS CMC): galima užtikrinti mažiau invazinį kvėpavimo taką, trachėjos perplėšimas, masyvus kaklo tinimas ar kvėpavimo takų trauma, vaikas iki 10–12 m.", "Po procedūros dažnai kartokite SpO₂, EtCO₂ ir praeinamumo vertinimą. Vien penetruojančiai traumai kaklo stuburo stabilizacija nereikalinga."], "zingsniai": ["Naudokite asmenines apsaugos priemones; jei yra CLS – paskirkite jį padėti (priemonės, ambu maišas).", "Dar kartą įvertinkite kvėpavimo takus galvos atlošimu su smakro pakėlimu ar žandikaulio išstūmimu – įsitikinkite, kad obstrukcija nepašalinama.", "Paguldykite ant nugaros, kaklas neutralioje padėtyje; atsistokite dominuojančios rankos pusėje. Surinkite ir patikrinkite priemones: skalpelis, trachėjos kabliukas, bužas, kaniulė su manžete, 10 ml švirkštas, ambu maišas, tvirtinimo juosta.", "Raskite krikotiroidinę membraną; jei laikas leidžia – nuvalykite antiseptiku; sąmoningam – lidokaino infiltracija.", "Nedominuojančia ranka stabilizuokite gerklas, dominuojančios rankos smiliumi dar kartą patikrinkite membraną.", "Virš membranos atlikite ~2,5 cm vertikalų odos pjūvį.", "Pasukite skalpelį skersai ir perpjaukite membraną (~1,3 cm anga) – pasigirs oro šnyptelėjimas. Nepjaukite giliau – pažeisite užpakalinę trachėjos sieną ir stemplę.", "Kabliuku užkabinkite žiedinę kremzlę ir pakelkite – anga stabilizuojama; skalpelį ištraukite ir saugiai padėkite.", "Pro angą įstumkite bužą link plaučių (jausite trachėjos žiedus), ant jo užmaukite kaniulę ir įstumkite į trachėją; bužą ir kabliuką ištraukite.", "Pripūskite manžetę 10 ml oro, prijunkite ambu maišą; patvirtinkite padėtį – EtCO₂, vienodas krūtinės kilimas, kvėpavimo garsai abipus, rasojimas kaniulėje.", "Apie kaniulę uždėkite tvarstį, kaniulę pritvirtinkite; prijunkite pulsoksimetrą – ventiliuokite maišu, jei kvėpuoja < 8 ar > 30 k./min arba SpO₂ < 90 %.", "Užrašykite DD1380; evakuacijos metu po kiekvieno perkėlimo tikrinkite kaniulės padėtį ir EtCO₂."], "klaidos": ["Sprendimas atidedamas – kartojami neveiksmingi manevrai, kol sužeistasis tampa hipoksiškas.", "Per trumpas odos pjūvis – neįmanoma rasti membranos ir įvesti kaniulės.", "„Duriama“ nekontroliuojamai ar per giliai – pažeidžiama užpakalinė trachėjos siena ir stemplė.", "Kaniulė įvedama šalia trachėjos (į poodį), o padėtis netikrinama kapnografija.", "Nepritvirtinta kaniulė išsitraukia perkeliant ar evakuojant."], "tccc": ["TCCC 2026 (TFC 4): kai padėtis, manevrai ir atsiurbimas nepadeda, o obstrukcija išlieka (veido lūžiai, kvėpavimo takų sužalojimas, kraujas, deformacija, nudegimai) – chirurginė krikotiroidotomija atvira technika su bužu arba standartine atvira technika.", "Flanšinė kaniulė su manžete (išorinis skersmuo < 10 mm, vidinis 6–7 mm, 5–8 cm trachėjoje); patvirtinti nuolatine EtCO₂ kapnografija; sąmoningam – lidokainas; dažnai kartoti SpO₂, EtCO₂ ir praeinamumo vertinimą.", "TCCC 2026 (TACEVAC): apmokytas personalas vietoj krikotiroidotomijos gali rinktis endotrachėjinę intubaciją."], "vaizdai": [{"src": "img/tccc/tccc-cmc7__module-7-airway-management-in-tfc-20.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc7/module-7-airway-management-in-tfc-20.jpg", "cap": "Krikotiroidotomijos indikacijos"}, {"src": "img/tccc/tccc-cmc7__module-7-airway-management-in-tfc-22.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc7/module-7-airway-management-in-tfc-22.jpg", "cap": "TCCC atvira technika: membranos nustatymas, gerklų stabilizavimas, 2,5 cm vertikalus odos ir skersinis membranos pjūvis, kabliukas"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc7/bougie-aided-open-cricothyroidotomy-en.mp4", "title": "7.10 Bougie-Aided Open Cricothyroidotomy", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/bougie-aided-open-cricothyroidotomy-cmc", "note": "Atvira krikotiroidotomija su bužu (EN)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/skill-card-bougie-aided-cricothyroidotomy-cmc", "pav": "Skill Card 55: Cricothyroidotomy Instruction (Bougie Aided)"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 4 (kvėpavimo takai), TACEVAC (kvėpavimo takai)", "JTS CMC kortelė 55 „Cricothyroidotomy Instruction (Bougie Aided)“", "JTS CMC 7 modulis „Airway Management in TFC“ (skaidrės 20–22)", "JTS CMC vaizdo įrašas 7.10 „Bougie-Aided Open Cricothyroidotomy“", "M. Grinevičiaus TCCC CLS kursas – „Atviri kvėpavimo takai (A)“"]},
  {"id": 14, "grupe": "R", "pav": "Kvėpavimo vertinimas ir įtampos pneumotoraksas", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Prie raidės R atidenkite ir apžiūrėkite visą krūtinę ir nugarą, įvertinkite kvėpavimą ir atpažinkite dvi gyvybei pavojingas būkles – atvirą (siurbiančią) krūtinės žaizdą ir įtampos (vožtuvinį) pneumotoraksą. Įtampos pneumotoraksas – viena dažniausių išvengiamų mirties priežasčių mūšio lauke; jį gali sukelti ir buka ar sprogimo trauma be išorinės žaizdos. MEDEVAC metu kvėpavimą vertinkite iš naujo po kiekvieno perkėlimo ir pablogėjus būklei.", "esme": ["Vertinkite: ar kvėpuoja, kvėpavimo dažnį, gylį ir pastangas, ar krūtinė kyla abipus vienodai, ar sužeistasis gali kalbėti; jei yra – pulsoksimetras (SpO₂).", "Atviros krūtinės žaizdos požymiai: penetruojanti žaizda, putos ar burbulai aplink ją, siurbiantis ar šnypščiantis garsas įkvepiant, kosėjimas krauju, kvėpavimo distresas – iškart uždenkite ranka, tada krūtinės lipduku (#15).", "Įtampos pneumotoraksą įtarkite (TCCC 2026): reikšminga liemens ar pirminė sprogimo trauma IR bent vienas požymis – sunkus ar progresuojantis kvėpavimo distresas, sunki ar progresuojanti tachipnėja, vienoje pusėje nėra ar labai susilpnėję kvėpavimo garsai, SpO₂ < 90 %, šokas, trauminis širdies sustojimas be akivaizdžiai mirtinų sužalojimų.", "Pradinis gydymas: „atpūskite“ ar nuimkite krūtinės lipduką, prijunkite pulsoksimetrą, paguldykite ant nugaros ar į stabilią šoninę padėtį (sėdėti – tik sąmoningam, kuriam to reikia kvėpavimo takams išlaikyti, pvz., esant veido traumai), atlikite adatinę dekompresiją pažeistoje pusėje (#16).", "Išsipūtusios kaklo venos ir trachėjos poslinkis – vėlyvi požymiai, jų nelaukite. Įtampos pneumotoraksas gali išsivystyti ir po užklijuoto lipduko.", "Neištaisoma hipoksija (SpO₂ < 90 %, esant galvos traumai < 92 %) dėl nepakankamo kvėpavimo – nazofaringinis vamzdelis ir ventiliacija 1000 ml ambu maišu (#11, #12).", "TACEVAC: daugumai sužeistųjų deguonies nereikia; jis naudingas esant mažai SpO₂, galvos traumai (SpO₂ ≥ 92 %), šokui, sąmonės netekimui, skrendant aukštyje ar įkvėpus dūmų (CMC / MEDEVAC įranga)."], "zingsniai": ["Atidenkite krūtinę; apžiūrėkite priekį, šonus, pažastis ir nugarą (paverskite ar pasodinkite), braukite ranka su pirštine ieškodami žaizdų ir kraujo.", "Įvertinkite kvėpavimą: ar kvėpuoja, dažnis per minutę, gylis, pastangos, krūtinės kilimo simetrija; paklauskite, ar sunku kvėpuoti.", "Jei aplinka leidžia – paklausykite kvėpavimo garsų abiejose pusėse; pačiuopkite krūtinę (deformacijos, traškėjimas, skausmingumas).", "Prijunkite pulsoksimetrą, jei yra; užrašykite SpO₂ ir kvėpavimo dažnį.", "Radę atvirą krūtinės žaizdą – iškart uždenkite ranka ir užklijuokite ventiliuojamą krūtinės lipduką (#15); kelias žaizdas tvarkykite ta tvarka, kuria randate.", "Patikrinkite įtampos pneumotorakso kriterijus (žr. esmę); jei jie yra – „atpūskite“ ar nuimkite lipduką ir įvertinkite iš naujo.", "Nepagerėjus – adatinė dekompresija pažeistoje pusėje (#16); jei nepadeda ir antra – pereikite prie C.", "Padėtis: be sąmonės – stabili šoninė sužeista puse žemyn; sąmoningam – kvėpuoti patogiausia; įtariant įtampos pneumotoraksą – ant nugaros ar stabili šoninė, nebent sėdėti būtina kvėpavimo takams.", "Kvėpavimą ir SpO₂ vertinkite pakartotinai, ypač po kiekvieno perkėlimo (į neštuvus, transporto priemonę); pablogėjus – vėl „atpūskite“ lipduką ar kartokite NDC.", "Užrašykite radinius ir veiksmus DD1380; perduodami MEDEVAC komandai praneškite apie krūtinės žaizdas, lipdukus ir NDC (vieta, laikas)."], "klaidos": ["Neapžiūrimos nugara ir pažastys – praleidžiamos išėjimo žaizdos.", "Laukiama vėlyvų požymių (kaklo venų, trachėjos poslinkio) – dekompresija atidedama.", "Manoma, kad užklijuotas lipdukas apsaugo nuo įtampos pneumotorakso, ir sužeistasis nebestebimas.", "Šokas po liemens traumos priskiriamas tik kraujavimui – nepagalvojama apie įtampos pneumotoraksą.", "Pulsoksimetro rodmeniu aklai pasitikima šoko ar hipotermijos metu – jis gali klaidinti."], "tccc": ["TCCC 2026 (TFC 5): įtampos pneumotoraksą įtarti po reikšmingos liemens ar pirminės sprogimo traumos, jei yra bent vienas požymis – sunkus ar progresuojantis distresas ar tachipnėja, vienoje pusėje nėra ar labai susilpnėję kvėpavimo garsai, SpO₂ < 90 %, šokas, trauminis sustojimas be akivaizdžiai mirtinų sužalojimų.", "Pradinis gydymas: „atpūsti“ ar nuimti lipduką, pulsoksimetrija, padėtis ant nugaros ar stabili šoninė, adatinė dekompresija pažeistoje pusėje.", "Atviras krūtinės žaizdas iškart uždengti ventiliuojamu lipduku; neištaisomai hipoksijai (SpO₂ < 90 %, su GST < 92 %) – nazofaringinis vamzdelis ir 1000 ml ambu maišas.", "TCCC 2026 (TACEVAC): daugumai deguonies nereikia; O₂ – esant mažai SpO₂, GST (SpO₂ ≥ 92 %), šokui, sąmonės netekimui, aukštyje, įtariant dūmų inhaliaciją."], "vaizdai": [{"src": "img/tccc/tccc-cmc8__module-08-respiration-assessment-management-in-tfc-06.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc8/module-08-respiration-assessment-management-in-tfc-06.jpg", "cap": "Gyvybei pavojinga krūtinės trauma: penetruojanti ir buka"}, {"src": "img/tccc/tccc-cmc8__module-08-respiration-assessment-management-in-tfc-19.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc8/module-08-respiration-assessment-management-in-tfc-19.jpg", "cap": "Įtampos pneumotoraksas – išvengiama mirties priežastis; lauke gydoma adatos dekompresija"}, {"src": "img/tccc/tccc-cmc8__skill-card-needle-decompression-of-the-chest-ndc-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc8/skill-card-needle-decompression-of-the-chest-ndc-en.jpg", "cap": "TCCC kortelė „Needle Decompression of the Chest (NDC)“"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS8/video8-1-en.mp4", "title": "8.1 Respiration Assessment & Management in TFC", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/respiration-assessment-management-in-tfc", "note": "Kvėpavimo vertinimas TFC fazėje: krūtinės žaizdos ir įtampos pneumotorakso atpažinimas (EN)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/needle-decompression-of-the-chest", "pav": "CLS kortelė 8.2: Needle Decompression of the Chest (NDC)"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 5 (kvėpavimas), 10 (stebėsena); TACEVAC (kvėpavimas, deguonis)", "JTS CLS vaizdo įrašas 8.1 „Respiration Assessment & Management in TFC“", "JTS CLS įgūdžių vertinimo lapas, 8 modulis", "JTS CMC 8 modulis „Respiration Assessment and Management in TFC“ (skaidrės 6, 10, 19)", "M. Grinevičiaus TCCC CLS kursas – „Kvėpavimas (R)“"]},
  {"id": 15, "grupe": "R", "pav": "Krūtinės lipdukas (ventiliuojamas)", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Per atvirą krūtinės žaizdą oras patenka į pleuros ertmę ir pažeistos pusės plautis subliūkšta (atviras pneumotoraksas). Visas atviras ar siurbiančias liemens žaizdas nuo kaklo iki bambos nedelsdami uždenkite ventiliuojamu (su vožtuvu) orui nelaidžiu krūtinės lipduku, o jo nesant – neventiliuojamu. Po to sužeistąjį nuolat stebėkite – įtampos pneumotoraksas gali išsivystyti ir po lipduko, taip pat evakuacijos metu.", "esme": ["Pirmenybė – ventiliuojamas lipdukas: įkvepiant plėvelė prisisiurbia, iškvepiant oras išeina pro vožtuvą. Neventiliuojamas – tik jei ventiliuojamo nėra.", "Kol ruošiate lipduką, žaizdą laikinai uždenkite delnu ar plaštakos nugarėle (pirštai lieka laisvi).", "Klijuokite sužeistajam iškvepiant ant nuvalytos odos; lipnus kraštas – apie 5 cm (2 col.) už žaizdos kraštų.", "Ieškokite visų žaizdų – priekyje, pažastyse, nugaroje; kiekvieną tvarkykite ta tvarka, kuria randate.", "Improvizuotas lipdukas (neventiliuojamas): orui nelaidi plėvelė (pvz., plastikinis maišelis), dengianti bent 5 cm aplink žaizdą, priklijuota iš visų 4 pusių.", "Įtampos požymiai po lipduko (hipoksija, progresuojantis distresas, hipotenzija ar šokas) – „atpūskite“: pakelkite vieną kraštą, išleiskite orą ir vėl prispauskite; nepadeda – adatinė dekompresija (#16)."], "zingsniai": ["Atidenkite krūtinę ir apžiūrėkite visas žaizdas.", "Atvirą žaizdą uždenkite delnu ar plaštakos nugarėle – laikinas sandarinimas.", "Visiškai atplėškite lipduko pakuotę.", "Pakuotėje esančia marle nuvalykite purvą, kraują ir skysčius aplink žaizdą.", "Nuplėškite apsauginę plėvelę nuo lipnios pusės.", "Sužeistajam iškvepiant uždėkite lipnią pusę tiesiai ant angos ir tvirtai prispauskite; kraštas – ~5 cm už žaizdos kraštų.", "Įsitikinkite, kad lipdukas gerai prilipęs, ir patikrinkite vožtuvo veikimą sužeistajam kvėpuojant.", "Paverskite sužeistąjį ir apžiūrėkite pažastis bei nugarą; radę kitą žaizdą – užklijuokite taip pat.", "Sąmoningą pasodinkite ar leiskite užimti kvėpuoti patogiausią padėtį; be sąmonės – stabili šoninė padėtis sužeista puse žemyn.", "Stebėkite įtampos pneumotorakso požymius; atsiradus – pakelkite lipduko kraštą („atpūskite“), tada vėl tvirtai prispauskite.", "Požymiai išlieka – atlikite adatinę dekompresiją (#16).", "Užrašykite DD1380 ir pritvirtinkite prie sužeistojo; evakuacijos metu tikrinkite, ar lipdukas neatšoko."], "klaidos": ["Lipdukas klijuojamas ant kruvinos, prakaituotos ar purvinos odos – neprilimpa.", "Nepastebimos pažasties ir nugaros (išėjimo) žaizdos.", "Po lipduko sužeistasis nestebimas – praleidžiamas besivystantis įtampos pneumotoraksas.", "Blogėjant kvėpavimui lipdukas neatpučiamas ir neatliekama dekompresija.", "Neventiliuojamas lipdukas renkamasi, nors yra ventiliuojamas."], "tccc": ["TCCC 2026 (TFC 5): visas atviras ir (ar) siurbiančias krūtinės žaizdas nedelsiant uždengti ventiliuojamu krūtinės lipduku; nesant – neventiliuojamu.", "Stebėti dėl įtampos pneumotorakso; esant hipoksijai, kvėpavimo distresui ar hipotenzijai – „atpūsti“ ar nuimti lipduką arba atlikti adatinę dekompresiją."], "vaizdai": [{"src": "img/tccc/CLS8__cls-skill-card-8-3-chest-seal-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS8/cls-skill-card-8-3-chest-seal-en.jpg", "cap": "JTS CLS kortelė „Chest Seal“: laikinas sandarinimas ranka, odos nuvalymas, klijavimas iškvepiant, nugaros apžiūra, padėtis ir lipduko „atpūtimas“ įtampos atveju"}, {"src": "img/tccc/tccc-cmc8__module-08-respiration-assessment-management-in-tfc-10.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc8/module-08-respiration-assessment-management-in-tfc-10.jpg", "cap": "Atviro pneumotorakso požymiai"}, {"src": "img/tccc/tccc-cmc8__module-08-respiration-assessment-management-in-tfc-12.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc8/module-08-respiration-assessment-management-in-tfc-12.jpg", "cap": "Vožtuviniai ir nevožtuviniai krūtinės tvarsčiai"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS8/video8-3-en.mp4", "title": "8.3 Chest Seal", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/chest-seal", "note": "Ventiliuojamo krūtinės lipduko uždėjimas ir „atpūtimas“ (EN)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/chest-seal", "pav": "CLS kortelė 8.3: Chest Seal"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 5 (kvėpavimas)", "JTS CLS kortelė 8.3 „Chest Seal“ (#TCCC-CLS-SC1-23, 2020)", "JTS CLS įgūdžių vertinimo lapas, 8 modulis", "JTS CMC 8 modulis (skaidrės 10, 12)", "M. Grinevičiaus TCCC CLS kursas – „Kvėpavimas (R)“ (okliuzinis tvarstis, improvizuotas tvarstis)"]},
  {"id": 16, "grupe": "R", "pav": "Adatos dekompresija (NDC)", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Adatinė krūtinės dekompresija (NDC) – pirmasis lauko gydymas įtariant įtampos pneumotoraksą: adata su kateteriu išleidžiamas pleuros ertmėje susikaupęs suspaustas oras. CLS ją atlieka pažeistoje pusėje, kai yra TCCC kriterijai (#14). Evakuacijos metu kateteris gali užsikimšti ar užsilenkti, todėl kvėpavimą vertinkite nuolat.", "esme": ["Priemonė: 14 G arba 10 G, 3,25 col. (8 cm) adata su kateteriu.", "Vieta pažeistoje pusėje (rinkitės pasiekiamesnę): 5-as tarpšonkaulinis tarpas priekinėje pažasties linijoje ARBA 2-as tarpšonkaulinis tarpas vidurinėje raktikaulio linijoje – ne mediališkiau spenelio linijos.", "Technika: statmenai krūtinės sienai (ne žemei), tiesiai virš apatinio šonkaulio viršutinio krašto, iki pat jungties; laikykite 5–10 s, adatą ištraukite, kateterį palikite.", "Sėkmė: palengvėja kvėpavimo distresas, girdimas oro šnypštimas, SpO₂ ≥ 90 % (gali užtrukti kelias minutes), be gyvybės ženklų buvusiam grįžta sąmonė ar radialinis pulsas.", "Nepadėjo – antra NDC toje pačioje pusėje kitoje vietoje nauja adata; apsvarstykite priešingą pusę. Po sėkmės simptomai grįžo – kartokite toje pačioje vietoje nauja adata. Nepadėjo ir antra – pereikite prie C.", "Liemens trauma ar politrauma be pulso ir kvėpavimo – prieš nutraukdami pagalbą dekompresuokite abi puses (#35)."], "zingsniai": ["Įvertinkite įtampos pneumotorakso požymius (#14).", "Jei užklijuotas krūtinės lipdukas – „atpūskite“ ar nuimkite (netinkamai uždėtą – pakeiskite) ir įvertinkite iš naujo.", "Paguldykite ant nugaros ar į stabilią šoninę padėtį (sėdėti – tik sąmoningam, kuriam to reikia kvėpavimo takams išlaikyti).", "Pažeistoje pusėje (ar ten, kur susilpnėję kvėpavimo garsai) raskite vietą: 5-as tarpšonkaulinis tarpas priekinėje pažasties linijoje arba 2-as tarpšonkaulinis tarpas vidurinėje raktikaulio linijoje.", "Paimkite 10 G ar 14 G, 3,25 col. (8 cm) adatą su kateteriu; jei yra – nuvalykite vietą antiseptiku; nuimkite Luer jungties kamštelį (jei yra).", "Durkite tiesiai virš apatinio šonkaulio viršutinio krašto, 90° kampu krūtinės sienai (ne žemei), iki pat jungties.", "Laikykite 5–10 s, tada adatą ištraukite, kateterį palikite vietoje.", "Įvertinkite sėkmę: oro šnypštimas, lengvesnis kvėpavimas, gerėjanti SpO₂.", "Nepadėjo – antra NDC toje pačioje pusėje kitoje vietoje nauja adata.", "Stebėkite toliau: simptomai grįžo po sėkmingos NDC – kartokite toje pačioje vietoje nauja adata; nepadėjo ir antra – pereikite prie C (MARCH).", "Toliau prižiūrėkite stabilioje šoninėje padėtyje sužeista puse žemyn ar sužeistajam patogiausioje padėtyje.", "Užrašykite vietą, laiką ir rezultatą DD1380; MEDEVAC komandai perduokite, kiek NDC ir kur atlikta."], "klaidos": ["Duriama mediališkiau spenelio (vidurinės raktikaulio) linijos – širdies ir stambiųjų kraujagyslių pažeidimo rizika.", "Duriama po šonkaulio apatiniu kraštu – pažeidžiamos tarpšonkaulinės kraujagyslės ir nervas.", "Adata nukreipiama statmenai žemei, o ne krūtinės sienai, arba neįvedama iki jungties.", "Nepavykus kartojama toje pačioje vietoje, užuot rinkusis kitą, arba naudojama ta pati adata.", "Triukšme negirdint šnypštimo daroma išvada, kad dekompresija nepavyko ar nereikalinga – vertinkite kvėpavimą ir SpO₂.", "Po NDC sužeistasis nestebimas – kateteris užsilenkia ar užsikemša, įtampa atsinaujina."], "tccc": ["TCCC 2026 (TFC 5): NDC pažeistoje pusėje 14 G arba 10 G, 3,25 col. (8 cm) adata su kateteriu – 5-as tarpšonkaulinis tarpas priekinėje pažasties linijoje arba 2-as vidurinėje raktikaulio linijoje (ne mediališkiau spenelio linijos); statmenai, virš apatinio šonkaulio, iki jungties, laikyti 5–10 s.", "Nesėkmė – antra NDC kitoje vietoje toje pačioje pusėje nauja adata, apsvarstyti priešingą pusę; simptomai grįžo – kartoti toje pačioje vietoje; nepadėjo ir antra – pereiti prie kraujotakos.", "TCCC 2026 (TFC 5, 17): liemens trauma ar politrauma be pulso ir kvėpavimo – prieš nutraukiant pagalbą dekompresuoti abi puses.", "Refrakterinis šokas – įtarti negydytą įtampos pneumotoraksą: kartoti NDC (aukštesnis lygis – pirštinė torakostomija ar drenas pagal kompetenciją) (TFC 6f)."], "vaizdai": [{"src": "img/tccc/CLS8__cls-skill-card-8-2-needle-decompression-chest-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS8/cls-skill-card-8-2-needle-decompression-chest-en.jpg", "cap": "JTS CLS kortelė „Needle Decompression of the Chest“: lipduko atpūtimas, dūrio vietos A ir B, 90° dūris virš apatinio šonkaulio, laikymas 5–10 s, antras bandymas kitoje vietoje"}, {"src": "img/tccc/tccc-cmc8__module-08-respiration-assessment-management-in-tfc-19.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc8/module-08-respiration-assessment-management-in-tfc-19.jpg", "cap": "Įtampos pneumotoraksas – išvengiama mirties priežastis; lauke gydoma adatos dekompresija"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS8/video8-2-en.mp4", "title": "8.2 Needle decompression of the chest (NDC)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/needle-decompression-of-the-chest", "note": "Adatinės dekompresijos technika žingsnis po žingsnio (EN)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/needle-decompression-of-the-chest", "pav": "CLS kortelė 8.2: Needle Decompression of the Chest (NDC)"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 5 (kvėpavimas), 6f (refrakterinis šokas), 17 (CPR)", "JTS CLS kortelė 8.2 „Needle Decompression of the Chest (NDC)“ (#TCCC-CLS-SC1-24, 2020)", "JTS CLS įgūdžių vertinimo lapas, 8 modulis", "JTS CMC 8 modulis (skaidrė 19)", "M. Grinevičiaus TCCC CLS kursas – „Kvėpavimas (R)“ (adatinė dekompresija)"]},
  {"id": 17, "grupe": "C", "pav": "Šoko atpažinimas: radialinis ir miego arterijos pulsas, sąmonė", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Hemoraginis šokas – audinių deguonies badas dėl kraujo netekimo; netekus 2–2,5 l kraujo jis dažnai baigiasi mirtimi. TCCC šoką lauke atpažįsta dviem paprastais požymiais – sąmonės sutrikimu be galvos traumos ir (ar) silpnu ar nečiuopiamu radialiniu pulsu. CLS šoko skysčiais negydo, bet jį atpažįsta, iš naujo patikrina kraujavimo stabdymą, saugo nuo hipotermijos, praneša medikui ir skubina evakuaciją.", "esme": ["Šoko kriterijai (TCCC 2026): sąmonės sutrikimas, kai nėra galvos smegenų traumos, ir (arba) silpnas ar nečiuopiamas radialinis pulsas.", "Sąmonę vertinkite AVPU skale: A – budrus, V – reaguoja į balsą, P – reaguoja tik į skausmą, U – nereaguoja. Šoko metu sąmonė blogėja nuo sujaudinimo ir sumišimo iki komos.", "Kiti požymiai: dažnas ar paviršinis kvėpavimas, blyški ar melsvai marmurinė, prakaituota, bet šalta oda, neramumas, pykinimas ar vėmimas; netekus ~2 l – pulsas > 120 k./min ir sunkiai čiuopiamas.", "Radialinis pulsas – riešo vidinėje pusėje, nykščio pusėje. Čiuopiamas – kraujotaka pakankama net galūnėse; nečiuopiamas – čiuopkite miego arteriją kaklo šone prie trachėjos.", "Pulso dažnis: dūžius skaičiuokite 15 s ir padauginkite iš 4; užrašykite DD1380 su laiku.", "Atpažinus šoką: iš naujo patikrinkite visus kraujavimo šaltinius ir turniketus, pagalvokite apie dubens lūžį (#18) ir įtampos pneumotoraksą (#14), pradėkite hipotermijos prevenciją, kvieskite mediką (CMC: IV/IO, TXA, kraujas) ir skubinkite evakuaciją.", "TACEVAC: sąmonę, pulsą ir kvėpavimą kartokite reguliariai ir po kiekvieno perkėlimo – blogėjanti dinamika yra svarbi informacija MEDEVAC komandai."], "zingsniai": ["Įvertinkite sąmonę AVPU: užkalbinkite; neatsako – sukelkite skausmą (pvz., paspauskite nago guolį); užrašykite.", "Sudėkite dominuojančios rankos smilių ir didįjį pirštą.", "Radialinis pulsas: pirštus dėkite riešo vidinėje pusėje šalia sausgyslės, nykščio pusėje; jei jaučiate kietus riešo kaulus – pastumkite pirštus palei sausgyslę į minkštesnę vietą.", "Įspauskite pirštus į įdubą ir jauskite stipininę arteriją; nejaučiant – spauskite kiek stipriau, nesukeldami skausmo, arba slinkite pirštus palei sausgyslę iki riešo kaulų pagrindo – ten pulsas jaučiamas lengviau.", "Su laikrodžiu skaičiuokite dūžius 15 s ir padauginkite iš 4; įvertinkite pulso stiprumą (stiprus, silpnas, nečiuopiamas).", "Nečiuopiant radialinio – miego arterija: du pirštai kaklo šone, šalia trachėjos, įspauskite į įdubą; skaičiuokite 15 s × 4.", "Miego arterijos nespauskite per stipriai – sužeistajam gali imti svaigti galva.", "Įvertinkite odą (spalva, temperatūra, drėgmė) ir kvėpavimo dažnį.", "Esant šoko požymiams – iš naujo patikrinkite kraujavimo stabdymą, pradėkite hipotermijos prevenciją, praneškite vadui ir medikui.", "Užrašykite AVPU, pulsą (vieta, dažnis, stiprumas) ir laiką DD1380; vertinimą kartokite evakuacijos metu."], "klaidos": ["Pulsas čiuopiamas nykščiu – galima pajusti savo pulsą.", "Radialinis pulsas tikrinamas toje rankoje, kurioje uždėtas turniketas ar yra sužalojimas – rinkitės sveiką ranką.", "Laukiama hipotenzijos ar visų požymių – šokas atpažįstamas per vėlai; čiuopiamas miego arterijos pulsas šoko neatmeta.", "Sąmonės sutrikimas priskiriamas tik galvos traumai ar stresui – abejojant gydykite kaip hemoraginį šoką.", "Pulsas ir sąmonė įvertinami tik kartą – nekartojama ir neužrašoma dinamika."], "tccc": ["TCCC 2026 (TFC 3, 6): hemoraginis šokas – sąmonės sutrikimas be galvos smegenų traumos ir (arba) silpnas ar nečiuopiamas radialinis pulsas; sustabdžius kraujavimą šoką vertinti iš naujo.", "Šoke nesančiam IV skysčių iš karto nereikia – sąmoningas, galintis nuryti, gali gerti; šoke medikas gaivina kraujo produktais, kol čiuopiamas radialinis pulsas, pagerėja sąmonė ar sAKS pasiekia 100 mm Hg.", "Šokas kartojasi – iš naujo patikrinti visas kraujavimo stabdymo priemones; refrakterinis šokas – įtarti negydytą įtampos pneumotoraksą."], "vaizdai": [{"src": "img/tccc/CLS5__module-5-tactical-trauma-assessment-en-18.webp", "orig": "https://tccc.org.ua/files/uploads/CLS5/module-5-tactical-trauma-assessment-en-18.jpg", "cap": "Šoko požymiai: sumišimas, dažnas kvėpavimas, šalta prakaituota blyški oda, silpnas ar nečiuopiamas radialinis pulsas"}, {"src": "img/tccc/CLS18__cls-skill-card-18-1-radial-pulse-assessment-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS18/cls-skill-card-18-1-radial-pulse-assessment-en.jpg", "cap": "JTS CLS kortelė: radialinio pulso čiuopimas – du pirštai riešo vidinėje pusėje nykščio pusėje, dūžiai skaičiuojami 15 s ir dauginami iš 4"}, {"src": "img/tccc/CLS18__cls-skill-card-18-2-carotid-pulse-assessment-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS18/cls-skill-card-18-2-carotid-pulse-assessment-en.jpg", "cap": "JTS CLS kortelė: miego arterijos pulsas – du pirštai kaklo šone prie trachėjos, 15 s × 4, nespausti per stipriai"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS10/video10.mp4", "title": "10. Shock Recognition", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/shock-recognition", "note": "Hemoraginio šoko požymiai ir veiksmai CLS lygiu (EN)"}, {"url": "https://tccc.org.ua/files/uploads/CLS18/video18-eng.mp4", "title": "18.1 Radial Pulse Assessment", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/avpu-assessment", "note": "Radialinio pulso čiuopimas ir skaičiavimas (EN)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/avpu-assessment", "pav": "CLS kortelė 18.1: Radial Pulse Assessment"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 3, 6b–6e (šokas, skysčiai)", "JTS CLS kortelės 18.1 „Radial Pulse Assessment“ (#TCCC-CLS-SC1-28) ir 18.2 „Carotid Pulse Assessment“ (#TCCC-CLS-SC1-27), 2020", "JTS CLS kortelė 11 „Hypothermia Treatment“ – šoko požymių pastaba", "JTS CLS vaizdo įrašai 10 „Shock Recognition“ ir 18.1", "M. Grinevičiaus TCCC CLS kursas – „Kraujotaka (C)“ (hemoraginis šokas, AVPU)"]},
  {"id": 18, "grupe": "C", "pav": "Dubens diržas", "lygis": "CMC", "fazes": ["TFC", "TACEVAC"], "aprasas": "Dubens lūžis po sunkios bukos ar sprogimo traumos gali sukelti masyvų vidinį kraujavimą ir šoką be matomo išorinio kraujavimo; dubens kompresinis diržas sumažina ir stabilizuoja lūžį. Diržą deda CMC, o CLS lūžį įtaria, praneša medikui ir padeda (išima daiktus iš kišenių, rankomis stabilizuoja dubenį). Uždėtas diržas paliekamas visą evakuaciją, šoko požymiai stebimi nuolat.", "esme": ["Indikacijos (TCCC 2026): sunki buka ar sprogimo trauma IR bent vienas – dubens skausmas, bet kokia didelė apatinės galūnės amputacija ar beveik amputacija, apžiūros radiniai, leidžiantys įtarti dubens lūžį, sąmonės netekimas, šokas.", "Lūžio požymiai: nestabilumas, krepitacija, nevienodas kojų ilgis; deformacijos, kraujosruvos, nubrozdinimai, žaizdos ar nudegimai dubens srityje; mėlynės kapšelio, tarpvietės, išangės srityje; kraujas šlaplėje ar šlapime.", "Diržas dedamas didžiųjų gūbrių (trochanter major) lygyje – ne ant klubakaulių keterų ir ne ant juosmens.", "Sprogimo sukeltą kojų amputaciją dažnai lydi dubens lūžis – uždėtas turniketas diržo poreikio neatmeta. Diržas netrukdo naudoti jungties turniketo, jei jo reikia.", "Kraujuojantys dubens lūžiai su nestabilia hemodinamika – didelis mirštamumas, todėl diržą dėkite anksti.", "Po uždėjimo stebėkite šoką (sąmonė, radialinis pulsas) – vidinis kraujavimas nematomas; šokui atsiradus ar blogėjant, jei taktinė situacija leidžia, diržą uždėkite iš naujo."], "zingsniai": ["Naudokite asmenines apsaugos priemones; jei įmanoma, CLS paveskite rankomis stabilizuoti dubenį.", "Išimkite daiktus iš kišenių ir nuo klubų srities.", "Paguldykite sužeistąjį ant nugaros.", "Apžiūrėkite (deformacijos, sumušimai, nubrozdinimai, žaizdos, nudegimai, patinimas) ir švelniai apčiuopkite (skausmingumas, nestabilumas, krepitacija); dubens nekilnokite ir neskėskite.", "Diržą prakiškite po šlaunimis ir pastumkite aukštyn iki didžiųjų gūbrių lygio.", "Juostą perkiškite pro sagtį ir pratraukite iki galo.", "Galus tvirtai traukite priešingomis kryptimis, kol pajusite sagties spragtelėjimą (jo gali ir nebūti).", "Išlaikydami įtempimą, laisvą galą iškart prispauskite prie diržo paviršiaus (antras spragtelėjimas – ne problema).", "Suriškite kojas (kelius ir (ar) pėdas), kad šlaunys nesisuktų į išorę.", "Stebėkite šoko požymius (sąmonės sutrikimas be galvos traumos, silpnas ar nečiuopiamas radialinis pulsas); blogėjant – diržą uždėkite iš naujo.", "Užrašykite DD1380 (uždėjimo laikas); evakuacijos metu diržo nenuimkite, sužeistąjį perkelkite atsargiai."], "klaidos": ["Diržas per aukštai – ant klubakaulių keterų ar juosmens: lūžis nesumažinamas.", "Dubens stabilumas „tikrinamas“ pakartotinai spaudžiant ar kilnojant – gali atsinaujinti kraujavimas.", "Nesurištos kojos – šlaunys sukasi į išorę.", "Uždėjus turniketą dėl kojos amputacijos pamirštamas dubens diržas.", "Kišenėse ir ties klubais palikti daiktai lieka po diržu."], "tccc": ["TCCC 2026 (TFC 6a): dubens diržas – sunki buka ar sprogimo trauma su dubens skausmu, didele apatinės galūnės (beveik) amputacija, lūžį leidžiančiais įtarti radiniais, sąmonės netekimu ar šoku.", "Hemoraginis šokas – sąmonės sutrikimas be galvos traumos ir (arba) silpnas ar nečiuopiamas radialinis pulsas; šokui kartojantis – iš naujo patikrinti visas kraujavimo stabdymo priemones."], "vaizdai": [{"src": "img/tccc/tccc-cmc9__module-9-circulation-and-hemorrhage-control-in-tfc-07.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc9/module-9-circulation-and-hemorrhage-control-in-tfc-07.jpg", "cap": "Dubens lūžio požymiai ir indikacijos dubens diržui"}, {"src": "img/tccc/tccc-cmc9__skill-card-pelvic-compression-device-pcd-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc9/skill-card-pelvic-compression-device-pcd-en.jpg", "cap": "TCCC kortelė „Pelvic Compression Device (PCD)“"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc9/pelvic-compression-device-pcd-en.mp4", "title": "9.2 Pelvic Compression Device (PCD)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/pelvic-compression-device-pcd-cmc", "note": "Dubens kompresinio diržo uždėjimas (EN)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/skill-card-pelvic-compression-device-pcd-cmc", "pav": "Skill Card 32: Pelvic Compression Device (PCD)"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 6a (dubens diržas), 6b (šokas)", "JTS CMC kortelė „Pelvic Compression Device (PCD)“ (#TCCC-CMC-SC-37, 2021)", "JTS CMC 9 modulis „Circulation/Hemorrhage Control in TFC“ (skaidrė 7)", "JTS CMC vaizdo įrašas 9.2 „Pelvic Compression Device (PCD)“", "M. Grinevičiaus TCCC CLS kursas – „Kraujotaka (C)“ (dubens kaulų lūžis)"]},
  {"id": 19, "grupe": "C", "pav": "IV / IO prieiga", "lygis": "CMC", "fazes": ["TFC", "TACEVAC"], "aprasas": "Kraujagyslių prieiga reikalinga gaivinti kraujo produktais ir leisti TXA, kalcį bei kitus vaistus, kai sužeistasis jų negali gerti. TCCC 2026: pirmenybė – 18 G venos kateteris arba „saline lock“, o jei IV greitai įvesti nepavyksta – intrakaulinė (IO) prieiga. Tai CMC įgūdis; CLS padeda – paruošia priemones, laiko galūnę, saugo liniją perkeliant.", "esme": ["Indikacijos: hemoraginis šokas ar didelė jo rizika; vaistų reikia, bet jų negalima duoti per burną.", "Šoke nesančiam IV skysčių iš karto nereikia – „saline lock“ palieka paruoštą prieigą be infuzijos.", "IV: 18 G kateteris į gerai matomą ar čiuopiamą veną; tvirtinkite patikimai – lauko sąlygoms sutvirtintas „saline lock“.", "IO – jei IV greitai neįvedamas (pvz., 2 nesėkmingi bandymai, venos nepasiekiamos, blogas matomumas); per IO leidžiami tie patys skysčiai, kraujas ir vaistai. Vietos: žastikaulis ir blauzdikaulis (EZ-IO), krūtinkaulis (FAST1).", "IO kontraindikacijos: lūžis, infekcija ar sužalojimas toje vietoje, osteoporozė, osteogenesis imperfecta; FAST1 – mažo sudėjimo ar < 50 kg sužeistiesiems, esant krūtinkaulio operacijos randui.", "Žastikaulio IO vieta – ~1 cm virš chirurginio kaklo, didžiojo gumburo srityje; sužeistojo delnas ant bambos, žastas priglaustas.", "Skysčius ir kraują leiskite per šildytuvą; IO sąmoningam skausminga – vietinis anestetikas pagal protokolą."], "zingsniai": ["Įvertinkite poreikį (šokas ar jo rizika, vaistai ne per burną); asmeninės apsaugos priemonės; CLS paveskite padėti.", "IV: virš dūrio vietos uždėkite venas spaudžiančią juostą, parinkite veną (dilbis, alkūnės linkis), nuvalykite antiseptiku.", "Įveskite 18 G kateterį; kateterio kameroje pasirodžius kraujui, nustumkite kateterį nuo adatos į veną, atleiskite juostą, adatą išmeskite į aštrių atliekų talpą.", "Prijunkite „saline lock“ ar užpildytą sistemą, praplaukite fiziologiniu tirpalu – turi stumtis lengvai, audiniai netinsta; tvirtai pritvirtinkite.", "IV greitai nepavyksta – IO. Žastikaulis: sužeistojo delnas ant bambos, žastas priglaustas; apčiuopkite didįjį gumburą ir po juo chirurginį kaklą („golfo kamuoliukas ant stovelio“) – vieta ~1 cm virš kaklo.", "Užpildykite IO jungiamąją liniją steriliu tirpalu, prijunkite tinkamą adatą prie gręžtuvo (magnetas spragtelėja), nuvalykite vietą antiseptiku.", "Nuimkite adatos dangtelį; nedominuojančia ranka stabilizuokite ranką, pirštus laikykite toliau nuo adatos; gręžtuvą laikykite 45° kampu.", "Pradurkite odą iki kaulo – virš odos turi matytis ≥ 5 mm adatos (bent viena žymė); tada gręžkite, kol pajusite pasipriešinimo išnykimą.", "Nuimkite gręžtuvą, išsukite stiletą (į aštrių atliekų talpą), prijunkite užpildytą liniją; sąmoningam – anestetikas pagal protokolą; praplaukite ir infuzuokite su spaudimu.", "Patikrinkite, ar netinsta aplinkiniai audiniai, pritvirtinkite stabilizatorių; vietą ir laiką užrašykite DD1380.", "Evakuacijos metu saugokite liniją perkeliant, tikrinkite pralaidumą ir infiltraciją."], "klaidos": ["Per ilgai bandoma įvesti IV šoke esančiam – vėluoja TXA ir kraujas; greitai nepavykus – IO.", "Nepastebima infiltracija (tinimas, kietumas) – skysčiai ir vaistai patenka į audinius.", "IO duriama į lūžusį ar sužalotą kaulą arba į tą patį kaulą po nesėkmingo bandymo.", "Per trumpa IO adata – virš odos nesimato 5 mm žymės, adata nepasiekia kaulų čiulpų ertmės.", "Nepritvirtinta linija išsitraukia perkeliant ar evakuojant."], "tccc": ["TCCC 2026 (TFC 6c): IV/IO prieiga – esant hemoraginiam šokui ar didelei jo rizikai arba kai vaistų reikia, bet jų negalima duoti per burną.", "Pirmenybė – 18 G IV kateteris ar „saline lock“; jei IV greitai gauti nepavyksta – IO.", "TFC 7: IV/IO skysčius leisti per baterinį šildytuvą (iki 150 ml/min, 38 °C)."], "vaizdai": [{"src": "img/tccc/tccc-cmc10__module-10-shock-recognition-and-management-17.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc10/module-10-shock-recognition-and-management-17.jpg", "cap": "Intrakaulinės prieigos indikacijos ir kontraindikacijos"}, {"src": "img/tccc/tccc-cmc10__skill-card-ez-io-humerus-intraosseous-io-device-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc10/skill-card-ez-io-humerus-intraosseous-io-device-en.jpg", "cap": "TCCC kortelė: EZ-IO žastikaulyje"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc10/field-ruggedized-saline-lock-en.mp4", "title": "10.1 Field Ruggedized IV Saline Lock", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/field-ruggedized-iv-saline-lock-cmc", "note": "Venos kateterio įvedimas ir „saline lock“ tvirtinimas lauke"}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc10/intraosseous-io-ez-humerus-en.mp4", "title": "10.3 Intraosseous (IO) EZ: Humerus", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/intraosseous-io-ez-humerus-cmc", "note": "EZ-IO įvedimas į žastikaulį"}], "kortele": {"url": "https://tccc.org.ua/en/guide/skill-card-ez-io-humerus-intraosseous-io-device-cmc", "pav": "Skill Card 34: EZ-IO (Humerus) Intraosseous (IO) Device"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 6c (IV/IO), 7 (skysčių šildymas)", "JTS CMC kortelė „Humeral Intraosseous (EZ-IO)“ (#TCCC-CMC-SC-38, 2021)", "JTS CMC 10 modulis „Shock Recognition and Management“ (skaidrė 17)", "JTS CMC vaizdo įrašai 10.1 „Field Ruggedized IV Saline Lock“ ir 10.3 „Intraosseous (IO) EZ: Humerus“"]},
  {"id": 20, "grupe": "C", "pav": "TXA, kalcis ir kraujo perpylimas", "lygis": "CMC", "fazes": ["TFC", "TACEVAC"], "aprasas": "Hemoraginio šoko gydymas lauke: sustabdžius kraujavimą, kuo greičiau skiriama traneksamo rūgštis (TXA), perpilami kraujo produktai ir po pirmojo vieneto – kalcis. Tai CMC (ir aukštesnio lygio) veiksmai; CLS atpažįsta šoką, paruošia priemones, šildo, stebi ir dokumentuoja. Gaivinama tik iki tikslo – čiuopiamo radialinio pulso, pagerėjusios sąmonės ar sAKS 100 mm Hg.", "esme": ["TXA indikacijos: tikėtina transfuzija (hemoraginis šokas, ≥ 1 didelė amputacija, penetruojanti liemens trauma, sunkaus kraujavimo požymiai) ARBA reikšmingos galvos smegenų traumos ar sąmonės sutrikimo po sprogimo ar bukos traumos požymiai.", "TXA: 2 g lėtai IV/IO stūmimu kuo greičiau, ne vėliau kaip per 3 val. po sužeidimo.", "Produktų eilė: šaltai laikytas mažo titro O pilnas kraujas → iš anksto ištirtų donorų šviežias mažo titro O pilnas kraujas → plazma : eritrocitai : trombocitai 1:1:1 → plazma : eritrocitai 1:1 → vien plazma ar eritrocitai.", "Kalcis (TCCC – „1 g kalcio“): 30 ml 10 % kalcio gliukonato (ne 10 ml!) arba 10 ml 10 % kalcio chlorido IV/IO po pirmojo perpilto produkto.", "Po kiekvieno vieneto vertinkite iš naujo; gaivinkite, kol čiuopiamas radialinis pulsas, pagerėja sąmonė ar sAKS pasiekia 100 mm Hg – pasiekus tikslą stabdykite.", "Rh neigiamas – jei iš karto prieinamas, kitaip hemoraginiam šokui tinka Rh teigiamas. Neištirtas O grupės ar grupei specifinis šviežias pilnas kraujas – tik mediko nurodymu, apmokyto personalo.", "Šoke nesančiam IV skysčių nereikia. Šokas kartojasi – iš naujo patikrinkite visą kraujavimo stabdymą; refrakterinis šokas – įtarkite negydytą įtampos pneumotoraksą."], "zingsniai": ["Įsitikinkite, kad išorinis kraujavimas sustabdytas, ir įvertinkite šoką (sąmonė, radialinis pulsas).", "Užtikrinkite IV (18 G) ar IO prieigą (#19).", "Esant indikacijai, suleiskite TXA 2 g lėtai IV/IO stūmimu; užrašykite laiką (ne vėliau kaip 3 val. nuo sužeidimo).", "Kraujo grupę (pvz., EldonCard) nustatykite lygiagrečiai – tai neturi vėlinti mažo titro O pilno kraujo perpylimo.", "Pasirinkite produktą pagal TCCC eilę; patikrinkite ženklinimą (grupė, Rh, galiojimas) ir maišelio vientisumą.", "Naudokite sistemą su kraujo filtru, veskite ją per šildytuvą, užpildykite ir prijunkite prie IV/IO.", "Po pirmojo perpilto produkto suleiskite kalcio: 30 ml 10 % kalcio gliukonato arba 10 ml 10 % kalcio chlorido IV/IO.", "Po kiekvieno vieneto įvertinkite radialinį pulsą, sąmonę ir (jei galima) sAKS; pasiekus tikslą – perpylimą stabdykite.", "Stebėkite perpylimo reakcijas (pvz., dusulys, dilgėlinė, karščiavimas, staiga blogėjanti būklė) – įtarus reakciją perpylimą nutraukite ir praneškite gydytojui.", "Visą laiką saugokite nuo hipotermijos – šildykite sužeistąjį ir perpilamus skysčius.", "Užrašykite TXA, kalcio, kiekvieno vieneto laiką ir atsaką DD1380; MEDEVAC metu tęskite vertinimą po kiekvieno vieneto ir perduokite informaciją."], "klaidos": ["TXA pamirštama arba skiriama praėjus > 3 val. po sužeidimo.", "TXA suleidžiama greitai, o ne lėtu stūmimu.", "Pamirštamas kalcis po pirmojo perpilto produkto.", "Perpylimas vėlinamas laukiant kraujo grupės nustatymo.", "Perpilama be filtro ar šildytuvo arba toliau pasiekus tikslą („daugiau ne visada geriau“).", "Skysčiais „vejamasi“ šoko, nors kraujavimas nesustabdytas ar neieškoma įtampos pneumotorakso."], "tccc": ["TCCC 2026 (TFC 6d): TXA 2 g lėtai IV/IO kuo greičiau, ne vėliau nei per 3 val. – jei tikėtina transfuzija arba yra reikšmingos GST ar sąmonės sutrikimo po sprogimo ar bukos traumos požymių.", "TFC 6e: šaltai laikytas mažo titro O pilnas kraujas → ištirtas šviežias mažo titro O → 1:1:1 → 1:1 → plazma ar eritrocitai; gaivinti iki radialinio pulso, pagerėjusios sąmonės ar sAKS 100 mm Hg.", "Kalcis („1 g kalcio“ – 30 ml 10 % kalcio gliukonato arba 10 ml 10 % kalcio chlorido) IV/IO po pirmojo perpilto produkto.", "Hipotermijos prevenciją pradėti gaivinimo metu; šokas kartojasi – tikrinti visą kraujavimo stabdymą; refrakterinis – įtarti įtampos pneumotoraksą."], "vaizdai": [{"src": "img/tccc/tccc-cmc10__module-10-shock-recognition-and-management-09.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc10/module-10-shock-recognition-and-management-09.jpg", "cap": "Hemoraginio šoko valdymas: TXA, skysčiai (kraujas), hipotermijos prevencija, pakartotinis vertinimas"}, {"src": "img/tccc/tccc-cmc11__module-11-hemorrhagic-shock-fluid-resuscitation-13.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc11/module-11-hemorrhagic-shock-fluid-resuscitation-13.jpg", "cap": "Mažo titro O grupės pilnas kraujas (LTOWB): indikacijos ir pranašumai"}, {"src": "img/tccc/tccc-cmc11__skill-card-tactical-field-care-determining-blood-type-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc11/skill-card-tactical-field-care-determining-blood-type-en.jpg", "cap": "TCCC kortelė: kraujo grupės nustatymas EldonCard"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc11/administration-of-blood-products-en.mp4", "title": "11.1 Administration of Blood Products", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/administration-of-blood-products-cmc", "note": "Kraujo produktų perpylimas: filtras, šildytuvas, stebėjimas"}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc11/determining-blood-type-using-eldoncard-en.mp4", "title": "11.3 Determining Blood Type (Using EldonCard)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/determining-blod-type-using-eldoncard-cmc", "note": "Kraujo grupės nustatymas EldonCard kortele"}], "kortele": {"url": "https://tccc.org.ua/en/guide/skill-card-tactical-field-care-determining-blood-type-cmc", "pav": "Skill Card 36: Tactical Field Care Determining Blood Type"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 6d (TXA), 6e (skysčiai, kalcis), 7 (hipotermija)", "JTS CMC 10 modulis (skaidrė 9) ir 11 modulis „Hemorrhagic Shock Fluid Resuscitation in TFC“ (skaidrė 13)", "JTS CMC kortelė „Tactical Field Care Determining Blood Type“", "JTS CMC vaizdo įrašai 11.1 „Administration of Blood Products“ ir 11.3 „Determining Blood Type (Using EldonCard)“", "M. Grinevičiaus TCCC CLS kursas – „Kraujotaka (C)“ (hemoraginis šokas)"]},
  {"id": 21, "grupe": "H", "pav": "Hipotermijos prevencija", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Hipotermija (kūno temperatūra < 35 °C) blogina kraujo krešėjimą ir didina mirties nuo kraujavimo riziką; sužeistasis atšąla net šiltu oru – guli ant žemės, nejuda, yra šlapias ir kraujuoja. TCCC reikalauja hipotermijos prevencijos anksti ir aktyviai visiems sužeistiesiems ir sunkiai nudegusiems. MEDEVAC metu – ypač sraigtasparnyje ar atviroje transporto priemonėje – saugokite nuo vėjo ir kritulių.", "esme": ["Lengviau išvengti nei gydyti: atidenkite ar kirpkite tik tiek, kiek reikia žaizdoms, po apžiūros vėl uždenkite.", "Izoliuokite nuo šaltos žemės, vėjo ir oro; šlapius drabužius pakeiskite sausais; apsaugines priemones (liemenę, šalmą) laikykite su sužeistuoju.", "Aktyvaus šildymo antklodė – ant priekinio liemens ir pažasčių, ne tiesiai ant odos ir neapvyniojant aplink liemenį.", "Apgaubkite nepralaidžiu išoriniu maišu ar apvalkalu; kuo greičiau pereikite prie gerai izoliuojančios sistemos – miegmaišio su gobtuvu garų barjero apvalkale.", "Apvyniokite visą sužeistąjį, įskaitant galvą, bet veido neuždenkite.", "CMC: IV/IO skysčius ir kraują leiskite per baterinį šildytuvą (iki 150 ml/min, 38 °C).", "Labiausiai rizikuoja šoke esantys, be sąmonės, dideli nudegimai ir gabenami nešildomose ar atvirose transporto priemonėse."], "zingsniai": ["Sumažinkite sąlytį su aplinka: perkelkite ant izoliuojančio paviršiaus (kilimėlis, neštuvai), pridenkite nuo vėjo.", "Įsitikinkite, kad kraujavimas sustabdytas, ir įvertinkite hemoraginį šoką (#17).", "Atidarykite aktyvaus šildymo priemonę ir (ar) pasyvaus šildymo medžiagas, išimkite priemonę ar antklodę.", "Aktyvaus šildymo priemonę atidenkite orui (pagal gamintojo instrukciją), kad imtų šilti.", "Nuimkite šlapius drabužius ir, jei įmanoma, pakeiskite sausais drabužiais ar kitomis sausomis medžiagomis.", "Jei yra – išimkite ir visiškai išskleiskite šildantį apvalkalą, sužeistąjį paguldykite jo viduryje.", "Aktyvaus šildymo priemonę uždėkite ant priekinio liemens ir pažasčių – ne tiesiai ant odos.", "Nesant aktyvaus šildymo – apgaubkite pasyviomis medžiagomis (antklodė, palapinsiaustė, miegmaišis).", "Visiškai apvyniokite sužeistąjį, įskaitant galvą; veido neuždenkite.", "Apvalkalą ar antklodę pritvirtinkite juosta, kad nenusmuktų nešant.", "Atidžiai stebėkite gyvybei pavojingas būkles; evakuacijos metu saugokite nuo vėjo ir kritulių, tikrinkite, ar sužeistasis sausas ir šiltas.", "Užrašykite radinius ir veiksmus DD1380."], "klaidos": ["Manoma, kad šiltu oru hipotermija negresia – ją skatina ir kraujo netekimas.", "Aktyvaus šildymo priemonė dedama tiesiai ant odos – nudegimai.", "Sužeistasis paliekamas gulėti tiesiai ant žemės ar šlapiais drabužiais.", "Šildyti pradedama tik prieš evakuaciją, o ne iškart sustabdžius kraujavimą.", "Uždengiamas veidas – nebematyti kvėpavimo ir būklės."], "tccc": ["TCCC 2026 (TFC 7): hipotermijos prevencija – anksti ir aktyviai visiems traumą ar sunkius nudegimus patyrusiems; mažinti šaltos žemės, vėjo ir oro poveikį, izoliuoti nuo žemės, keisti šlapius drabužius, apsaugines priemones laikyti su sužeistuoju.", "Aktyvaus šildymo antklodė ant priekinio liemens ir pažasčių (ne tiesiai ant odos, neapvynioti liemens); apgaubti nepralaidžiu maišu, kuo greičiau – miegmaišis su gobtuvu garų barjero apvalkale.", "IV/IO skysčiai per baterinį šildytuvą (iki 150 ml/min, 38 °C); TACEVAC – saugoti nuo vėjo ir kritulių evakuacijos platformoje."], "vaizdai": [{"src": "img/tccc/CLS11__cls-skill-card-11-hypothermia-treatment-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS11/cls-skill-card-11-hypothermia-treatment-en.jpg", "cap": "JTS CLS kortelė „Hypothermia Treatment“: aktyvaus šildymo priemonė, šlapių drabužių keitimas, šildantis apvalkalas ir visiškas apvyniojimas su galva, veidas atidengtas"}, {"src": "img/tccc/tccc-cmc12__module-12-hypothermia-prevention-treatment-12.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc12/module-12-hypothermia-prevention-treatment-12.jpg", "cap": "Hipotermijos prevencija: izoliuoti, sausai, aktyvus šildymas, nepralaidus apvalkalas"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS11/video11eng.mp4", "title": "11. Hypothermia Treatment", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/hypothermia-prevention", "note": "Hipotermijos prevencija ir apvyniojimas (EN); pagal TCCC 2026 aktyvaus šildymo antklodę dėkite ant priekinio liemens ir pažasčių, ne aplink liemenį"}], "kortele": {"url": "https://tccc.org.ua/en/guide/hypothermia-prevention", "pav": "CLS kortelė 11: Hypothermia Treatment"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 7 (hipotermija), TACEVAC (hipotermija)", "JTS CLS kortelė 11 „Hypothermia Treatment“ (#TCCC-CLS-SC1-29, 2020)", "JTS CMC 12 modulis „Hypothermia Prevention and Treatment“ (skaidrė 12)", "M. Grinevičiaus TCCC CLS kursas – „Hipotermija, galvos trauma (H)“"]},
  {"id": 22, "grupe": "H", "pav": "Galvos smegenų trauma", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Galvos smegenų trauma (GST) dažna po sprogimų, kritimų ir šūvių; antrinį smegenų pažeidimą lauke labiausiai sukelia hipoksija ir hipotenzija. CLS GST atpažįsta, palaiko kvėpavimo takus ir kvėpavimą, tinkamai paguldo, saugo ir dažnai kartoja neurologinį vertinimą; CMC skiria deguonį, TXA, plazmą, o esant išvaržos požymiams – hipertoninį NaCl. Vidutinė ar sunki GST – skubi MEDEVAC: chirurgija geriausia per 5 val. nuo traumos.", "esme": ["Vidutinė ar sunki GST: sužeistasis > 10 min. po traumos negali vykdyti paprastų komandų (nykštys aukštyn, parodyti du pirštus, mirktelėti), įtariama galvos trauma ir nėra kitos priežasties. Abejojant – gydykite kaip hemoraginį šoką.", "Kiti požymiai: blogėjanti sąmonė, dvejinimasis akyse, neramumas ar agresija, pakartotinis vėmimas, traukuliai, silpnumas ar dilgčiojimas galūnėse, stiprus ar stiprėjantis galvos skausmas.", "Tikslai: SpO₂ ≥ 92 %, sAKS > 100 mm Hg (ar normalus radialinis pulsas); ventiliuojamam – EtCO₂ 35–45 mm Hg, be kapnografo – 10 įkvėpimų/min. Hemoraginio šoko gydymas – pirmiau.", "Ne šoke ir taktiškai įmanoma – pakelkite galvą ir liemenį daugiau kaip 30°; kaklo įtvarą atlaisvinkite, galvą laikykite tiesiai, nesuktą.", "Išvaržos požymiai: asimetriški arba fiksuoti ir išsiplėtę vyzdžiai, patologinė laikysena. CMC: hipertoninis NaCl – 250 ml 3 % ar 5 % arba 30 ml 23,4 % IV/IO per ≥ 10 min, po to praplauti; nėra atsako – kartoti 1 kartą po 20 min (iš viso ≤ 2 dozės); ne profilaktiškai ir ne kaip gaivinimo skystis.", "Penetruojanti GST ar atviras kaukolės lūžis nėra automatiškai beviltiški: paviršinis tvarstis, aktyviai kraujuojant – hemostatinė marlė su švelniu spaudimu; žaizdos nekamšykite ir neuždarykite; antibiotikai.", "CMC: TXA 2 g IV/IO (≤ 3 val.) esant reikšmingai GST ar sąmonės sutrikimui po sprogimo ar bukos traumos; jei kraujavimo požymių nėra – skirti 1–2 vnt. plazmos (lengvai GST ir smegenų sukrėtimui – neskirti); ažitacijai – analgezija (ketaminas GST nedraudžia)."], "zingsniai": ["Sutrikusios sąmonės sužeistajam paimkite ginklą ir granatas.", "Įvertinkite AVPU ir paprastų komandų vykdymą, vyzdžius (dydis, simetrija) ir galūnių judesius; užrašykite pradinius duomenis ir laiką.", "Užtikrinkite kvėpavimo takus: be sąmonės – stabili šoninė padėtis, galva atlošta; vemiant – paverskite ant šono ir išvalykite burną.", "Prijunkite pulsoksimetrą (visiems su vidutine ar sunkia GST); SpO₂ < 92 % – CMC skiria deguonį; nepakankamai kvėpuojant – nazofaringinis vamzdelis ir ambu maišas, 10 įkvėpimų/min (kas 6 s).", "Šoką gydykite pirmiau: sustabdykite kraujavimą; tikslas – čiuopiamas normalus radialinis pulsas (sAKS > 100 mm Hg).", "Ne šoke – pakelkite galvą ir liemenį > 30°, atlaisvinkite kaklo įtvarą, galvą laikykite tiesiai.", "Galvos žaizdą uždenkite paviršiniu tvarsčiu; aktyviai kraujuojant – hemostatinė marlė su švelniu spaudimu; į žaizdą nieko nekiškite.", "Saugokite nuo hipotermijos (#21).", "Išvaržos požymiai (asimetriški arba fiksuoti ir išsiplėtę vyzdžiai, patologinė laikysena) – nedelsdami praneškite medikui: CMC skiria hipertoninį NaCl (žr. esmę).", "Neurologinę būklę (AVPU, komandos, vyzdžiai) kartokite kas 5–10 min., dinamiką užrašykite DD1380.", "Prašykite skubios MEDEVAC (chirurgija – per 5 val.); perduodami praneškite pradinę ir dabartinę sąmonę, vyzdžius, SpO₂ ir gautus vaistus."], "klaidos": ["Sąmonės sutrikimas priskiriamas galvos traumai, nors priežastis – hemoraginis šokas ar hipoksija.", "Toleruojama SpO₂ < 92 % ar silpnas radialinis pulsas (hipotenzija).", "Ventiliuojama per dažnai – be EtCO₂ kontrolės daugiau nei 10 kartų per minutę.", "Hipertoninis NaCl skiriamas profilaktiškai ar kaip gaivinimo skystis.", "Į atvirą kaukolės žaizdą kemšama marlė ar žaizda uždaroma.", "Neurologinis vertinimas nekartojamas ir neužrašomas – nepastebimas blogėjimas."], "tccc": ["TCCC 2026 (TFC 8): vidutinė ar sunki GST – negali vykdyti paprastų komandų > 10 min. po traumos; abejojant gydyti kaip hemoraginį šoką; evakuoti kuo greičiau (chirurgija geriausia < 5 val.).", "SpO₂ ≥ 92 %, sAKS > 100 mm Hg (ar normalus radialinis pulsas); ventiliuojamam EtCO₂ 35–45 mm Hg (be jo – 10 įkvėpimų/min); ne šoke – galva ir liemuo > 30°; neurologinė būklė kas 5–10 min.", "Išvaržos požymiai – hipertoninis NaCl 250 ml 3 % ar 5 % arba 30 ml 23,4 % IV/IO per ≥ 10 min; nėra atsako – kartoti po 20 min (≤ 2 dozės); ne profilaktiškai, ne gaivinimui.", "Penetruojanti GST nėra automatiškai beviltiška: paviršinis tvarstis, hemostatinė marlė su švelniu spaudimu, ertmės nekamšyti ir neuždaryti, antibiotikai."], "vaizdai": [{"src": "img/tccc/cls12__module-12-head-injuries-en-07.webp", "orig": "https://tccc.org.ua/files/uploads/cls12/module-12-head-injuries-en-07.jpg", "cap": "Galvos traumos požymiai ir IED kontrolinis sąrašas po sprogimo"}, {"src": "img/tccc/cls12__module-12-head-injuries-en-06.webp", "orig": "https://tccc.org.ua/files/uploads/cls12/module-12-head-injuries-en-06.jpg", "cap": "Galvos traumos mechanizmai: sprogimas, smūgis, apvirtimas, buvimas ≤ 50 m nuo sprogimo"}, {"src": "img/tccc/tccc-cmc13__module-13-head-injuries-07.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc13/module-13-head-injuries-07.jpg", "cap": "Galvos traumos mechanizmai: sprogimas, eismo įvykis, smūgis, šautinis sužalojimas"}], "video": [], "kortele": null, "saltiniai": ["TCCC gairės 2026-05-01, TFC 6d (TXA), 8 (GST), 10 (stebėsena)", "JTS CMC 13 modulis „Head Injuries“ (skaidrė 7)", "M. Grinevičiaus TCCC CLS kursas – „Hipotermija, galvos trauma (H)“ (GST simptomai)"]},
  {"id": 23, "grupe": "H", "pav": "Akies sužalojimas: standus skydelis", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Penetruojantis akies sužalojimas gali baigtis apakimu, jei akis spaudžiama ar užkrečiama. TCCC 2026 numato tris veiksmus: greitą regėjimo aštrumo patikrą ir jos užrašymą, standų akies skydelį (NE spaudžiamąjį tvarstį) ir antibiotiką kuo greičiau. Geriausia prevencija – balistiniai akiniai.", "esme": ["Įtarkite, kai matyti svetimkūnis, akies deformacija, plėštinė žaizda, kraujosruva, patinimas ar sumažėjęs regėjimas; abejojant gydykite kaip penetruojantį sužalojimą.", "Regėjimo patikra kiekvienai akiai atskirai, per ištiestos rankos atstumą: skaito tekstą → skaičiuoja pirštus → mato rankos judesį → skiria šviesą nuo tamsos → nieko nemato; užrašykite abiejų akių rezultatą.", "Standus skydelis remiasi į kaulines akiduobės iškyšas ir neliečia akies; nesant – improvizuokite (SAM įtvaras, putplasčio ar plastiko puodelis).", "Įsmigusio daikto netraukite: skydelyje išpjaukite angą daiktui arba aplink daiktą dėkite storą tvarstį.", "Uždenkite tik sužeistą akį (abi – tik jei abi sužeistos).", "Antibiotikas kuo greičiau: CLS – cefadroksilis 1 g per burną (jei gali nuryti); CMC – ceftriaksonas 2 g IV/IM, jei per burną negali.", "Skausmui sąmoningam – CWMP (#24); CMC – ketaminas (akies sužalojimas jo nedraudžia)."], "zingsniai": ["Paguldykite ar pasodinkite patogiai, kad pasiektumėte akis ir galvą; prireikus nuimkite šalmą.", "Apžiūrėkite akis: deformacijos, sumušimai, nubrozdinimai, įsmigę daiktai, mėlynės, plėštinės žaizdos, patinimas.", "Greitai patikrinkite regėjimą: sveiką akį uždenkite, patinusios akies jėga neatverkite; tikrinkite tekstą, pirštus, rankos judesį, šviesą; pakartokite kitai akiai.", "Sužeistą akį uždenkite standžiu skydeliu – NE spaudžiamuoju tvarsčiu; skydelis remiasi į kaulus ir akies nespaudžia.", "Įsmigus daiktui – skydelyje išpjaukite angą daiktui arba aplink jį dėkite storą tvarstį ir pritvirtinkite.", "Jei skydelis liečia akį ar spaudžia – naudokite improvizuotą (pvz., puodelį).", "Skydelį pritvirtinkite pleistru 45° kampu per kaktą ir skruostą.", "Sąmoningam duokite CWMP nuo skausmo ir užtikrinkite antibiotiką: cefadroksilis 1 g per burną; negalinčiam gerti – CMC ceftriaksonas 2 g IV/IM.", "Užrašykite regėjimo patikros rezultatą (abiem akims), veiksmus ir vaistų laiką DD1380, kortelę pritvirtinkite prie sužeistojo.", "Evakuacijos metu skydelio nenuimkite; tikrinkite, ar jis nepasislinko ir nespaudžia akies."], "klaidos": ["Ant akies dedamas spaudžiamasis tvarstis ar akis kitaip spaudžiama – gali išsistumti akies turinys ir prarandamas regėjimas.", "Bandoma ištraukti įsmigusį daiktą.", "Jėga atveriama patinusi akis regėjimui patikrinti.", "Neužrašomas regėjimo aštrumas – gydytojai neturi pradinio taško.", "Uždengiama ir sveika akis, kai sužeista tik viena.", "Pamirštamas antibiotikas."], "tccc": ["TCCC 2026 (TFC 9): įtarus penetruojantį akies sužalojimą – greita lauko regėjimo aštrumo patikra ir jos užrašymas; standus akies skydelis (NE spaudžiamasis tvarstis).", "Antibiotikas kuo greičiau: ceftriaksonas 2 g IV/IM arba cefadroksilis 1 g per burną.", "TFC 11: akies sužalojimas nedraudžia ketamino."], "vaizdai": [{"src": "img/tccc/CLS13__cls-skill-card-13-1-penetrating-eye-injury-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS13/cls-skill-card-13-1-penetrating-eye-injury-en.jpg", "cap": "JTS CLS kortelė „Penetrating Eye Injury“: apžiūra, standus skydelis (ne spaudžiamasis tvarstis) ar improvizuotas puodelis, tvirtinimas 45° kampu per kaktą ir skruostą"}, {"src": "img/tccc/tccc-cmc13__skill-card-eye-trauma-rapid-field-test-of-visual-acuity-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc13/skill-card-eye-trauma-rapid-field-test-of-visual-acuity-en.jpg", "cap": "TCCC kortelė: greitas regėjimo aštrumo testas"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS13/video13.mp4", "title": "13.1 Penetrating Eye Injury", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/eye-injuries", "note": "Penetruojančio akies sužalojimo pagalba (EN); senesnis įrašas – antibiotiką skirkite pagal TCCC 2026 (cefadroksilis ar ceftriaksonas)"}, {"url": "https://tccc.org.ua/files/uploads/CLS13/video132.mp4", "title": "13.2 Rigid Eye Shield", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/rigid-eye-shield", "note": "Standaus akies skydelio uždėjimas ir tvirtinimas (EN)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/eye-injuries", "pav": "CLS kortelė 13.1: Penetrating Eye Injury"}, "saltiniai": ["TCCC gairės 2026-05-01, TFC 9 (akies trauma), 11 (analgezija), 12 (antibiotikai)", "JTS CLS kortelė 13.1 „Penetrating Eye Injury“ (#TCCC-CLS-SC1-31, 2019)", "JTS CMC kortelė „Rapid Visual Acuity Testing“ (#TCCC-CMC-SC-44, 2021)", "JTS CLS vaizdo įrašai 13.1 ir 13.2", "M. Grinevičiaus TCCC CLS kursas – „Penetruojantis akies sužalojimas“"]},
  {"id": 24, "grupe": "P", "pav": "Skausmo malšinimas: kovinių žaizdų vaistų paketas (CWMP)", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Kovinių žaizdų vaistų paketas (Combat Wound Medication Pack, CWMP) – iš anksto supakuotos skausmą malšinančios tabletės, kurias sąmoningas sužeistasis, galintis tęsti kovą, išgeria pats arba jam duoda draugas. TCCC 2026 paketą sudaro paracetamolis, meloksikamas ir suzetriginas (ne opioidas) – jie parinkti taip, kad karys liktų kovingas. Antibiotikai į paketą nebeįeina ir skiriami atskirai.", "esme": ["Kam: sąmoningam, galinčiam nuryti ir tęsti kovą (užduotį); geria pats arba padeda draugas. Negalinčiam kovoti – CWMP, jei dar negėrė, o stipriam skausmui medikas (CMC) skiria ketaminą (#25).", "Paracetamolis: 1000–1300 mg per burną kas 8 val. (pvz., 2 prailginto veikimo tabletės po 650 mg; 2 × 500 mg = 1000 mg taip pat atitinka dozę).", "Meloksikamas: 15 mg per burną 1 kartą per parą.", "Suzetriginas: pirmą kartą 100 mg (2 × 50 mg) per burną, vėliau 50 mg kas 12 val.", "Antibiotikai – atskirai: atvirai kovinei žaizdai cefadroksilis 1 g per burną 1 kartą per parą (#26).", "Tikslas – pakenčiamas skausmas, išlaikant kvėpavimo takus, kvėpavimą ir sąmonę; kiekvieną dozę ir laiką užrašykite DD1380, kad nebūtų perdozuota.", "Skausmą mažina ir lūžių įtvėrimas, nudegimų uždengimas, šildymas bei ramus bendravimas."], "zingsniai": ["Įsitikinkite, kad gyvybei pavojingos būklės (MARCH) sutvarkytos – skausmas yra P raidė.", "Įvertinkite, ar sužeistasis sąmoningas (AVPU – A), gali nuryti ir tęsti užduotį; paklauskite apie vaistų alergiją.", "Įvertinkite skausmą skalėje 0–10 ir užrašykite kartu su AVPU.", "Atplėškite CWMP ir patikrinkite turinį.", "Duokite išgerti visas tabletes vienu metu: paracetamolio 1000–1300 mg, meloksikamo 15 mg ir suzetrigino 100 mg (2 × 50 mg).", "Esant atvirai žaizdai – užtikrinkite antibiotiką (cefadroksilis 1 g per burną).", "Užrašykite vaistus, dozes ir laiką DD1380.", "Kartokite pagal grafiką: paracetamolis kas 8 val., suzetriginas 50 mg kas 12 val., meloksikamas – po paros.", "Pakartotinai vertinkite skausmą ir sąmonę; jei skausmas nepakenčiamas ar sužeistasis nebegali kovoti – kvieskite mediką (CMC: ketaminas).", "Perduodami MEDEVAC komandai praneškite, kokie vaistai ir kada duoti."], "klaidos": ["CWMP duodamas be sąmonės ar negalinčiam nuryti – užspringimo ir aspiracijos pavojus.", "Neužrašomas laikas – kartojant viršijamos dozės.", "Manoma, kad CWMP apsaugo nuo infekcijos – 2026 m. pakete antibiotiko nebėra (senesnėse medžiagose – moksifloksacinas).", "Esant nepakenčiamam skausmui medikas nekviečiamas – sužeistasis lieka be tinkamos analgezijos."], "tccc": ["TCCC 2026 (TFC 11a): galintiems kovoti – CWMP, geriamas pačių ar draugo: paracetamolis 1000–1300 mg PO kas 8 val., meloksikamas 15 mg PO 1 k./parą, suzetriginas 100 mg PO vieną kartą, vėliau 50 mg PO kas 12 val.", "TFC 11b: negalintiems kovoti – CWMP, jei dar negėrė; TCCC medikai skiria ketaminą (IM, IN, IV/IO) ar esketaminą IN; prieš ketaminą užrašyti AVPU.", "TFC 12: antibiotikai visoms atviroms kovinėms žaizdoms – galintiems gerti cefadroksilis 1 g PO 1 k./parą (alternatyva – cefaleksinas 500 mg PO kas 6 val.)."], "vaizdai": [{"src": "img/tccc/cls4__module-4-principles-and-application-of-tactical-field-care-en-10.webp", "orig": "https://tccc.org.ua/files/uploads/cls4/module-4-principles-and-application-of-tactical-field-care-en-10.jpg", "cap": "MARCH PAWS: skausmas (P) gydomas sutvarkius gyvybei pavojingas būkles"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS14/video14-3-eng.mp4", "title": "14.3 Combat Wound Medication Pill Pack", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/combat-wound-medication-pill-pack", "note": "CWMP vartojimas (EN); senesnis įrašas – TCCC 2026 paketo sudėtis: paracetamolis, meloksikamas, suzetriginas, be antibiotiko"}, {"url": "https://tccc.org.ua/files/uploads/CLS14/video14-1-eng.mp4", "title": "14.1 Analgesia Administration", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/analgesia-administration", "note": "Nuskausminimo principai CLS lygiu (EN); senesnis įrašas – vaistus ir dozes tikrinkite pagal TCCC 2026"}], "kortele": null, "saltiniai": ["TCCC gairės 2026-05-01, TFC 11 (analgezija), 12 (antibiotikai)", "JTS CLS vaizdo įrašai 14.1 „Analgesia Administration“ ir 14.3 „Combat Wound Medication Pill Pack“", "JTS CMC 11 modulis (skaidrė 4 – MARCH PAWS)", "M. Grinevičiaus TCCC CLS kursas – „Vaistai (P, A)“ (CWMP, paracetamolis 500 mg tabletėmis)"]},
  {"id": 25, "grupe": "P", "pav": "Ketaminas (nuskausminimas)", "lygis": "CMC", "fazes": ["TFC", "TACEVAC"], "aprasas": "Ketaminas – TCCC 2026 stipraus skausmo malšinimo vaistas sužeistajam, kuris negali tęsti kovos užduoties. Jį skiria TCCC medicinos personalas (CMC ir aukštesnis lygis), o CLS lygio gelbėtojas turi mokėti stebėti ketaminą gavusį sužeistąjį evakuacijos metu. Tikslas – pakenčiamas skausmas, išlaikant kvėpavimo takus, kvėpavimą ir sąmonę.", "esme": ["Dozės (TCCC 2026): 100 mg IM ARBA 50 mg IN (100 mg/ml koncentracija – 0,5 ml) ARBA 25 mg (0,2–0,3 mg/kg) IV / IO lėtai per 1 min.", "Alternatyva – esketaminas 14 arba 28 mg IN vieną kartą.", "Ketaminą kartokite kas 30 min pagal poreikį; tikslas – skausmas sumažėjo arba atsirado nistagmas (akių obuolių trūkčiojimas).", "Prieš ketaminą nuginkluokite sužeistąjį, apsvarstykite ryšio priemonių atjungimą ir įrašykite sąmonę (AVPU) į DD 1380.", "Benzodiazepinų su ketaminu, esketaminu ar opioidais neskirkite; dalinė disociacija gydoma papildoma ketamino doze, ne benzodiazepinu.", "Galvos smegenų trauma ir akies sužalojimas ketamino nedraudžia; ketaminą galima skirti ir po opioido.", "Pykinant ar vemiant – ondansetronas 4 mg (tirpstanti tabletė, IV / IO / IM) kas 8 val. pagal poreikį."], "zingsniai": ["Įsitikinkite, kad sužeistasis negali tęsti užduoties; jei dar negavo ir gali nuryti – duokite CWMP.", "Paklauskite apie alergijas; įvertinkite skausmą (0–10) ir sąmonę (AVPU) ir įrašykite į DD 1380 prieš vaistą.", "Nuginkluokite sužeistąjį (ginklas, granatos) ir apsvarstykite ryšio priemonių atjungimą.", "Pasirinkite būdą: IM – 100 mg; IN – 50 mg (100 mg/ml); IV / IO – 25 mg lėtai per 1 min; arba esketaminas 14 ar 28 mg IN vieną kartą.", "Leisdami į nosį patikrinkite, ar šnervė laisva (be kraujo ar skaidraus skysčio), ir naudokite laisvesnę pusę.", "Stebėkite kvėpavimo takus, kvėpavimą ir kraujotaką; kvėpavimui retėjant – „uostymo“ padėtis, toliau – ventiliacija ambu maišu.", "Po 30 min iš naujo įvertinkite skausmą; jei reikia – kartokite ketaminą, kol skausmas sumažės arba atsiras nistagmas.", "Pykinant skirkite ondansetroną 4 mg; vemiantį saugokite nuo aspiracijos (šoninė padėtis).", "Pervežant pritvirtinkite sužeistąjį neštuvų diržais – po ketamino jis gali būti sujaudintas ar dezorientuotas.", "Įrašykite vaistą, dozę, būdą ir laiką į DD 1380; perduodami praneškite paskutinės dozės laiką."], "klaidos": ["Ketaminas suleidžiamas neįrašius AVPU – vėliau neįmanoma atskirti vaisto poveikio nuo šoko ar galvos traumos.", "Ketaminą gavusiam sužeistajam paliekamas ginklas ar granatos.", "Ketaminas analgezijai derinamas su benzodiazepinu (pvz., midazolamu) – TCCC 2026 to neleidžia.", "Supainiojama koncentracija: IN dozei reikia 100 mg/ml (50 mg = 0,5 ml), kitokios koncentracijos tūris nosiai per didelis.", "IV / IO dozė suleidžiama greitai, o ne per 1 min, arba kartojama dažniau nei kas 30 min.", "Po ketamino nestebimas kvėpavimas pervežant."], "tccc": ["TCCC 2026 (TFC 11b): negalinčiam kovoti – CWMP (jei dar negauta) ir ketaminas 100 mg IM, 50 mg IN arba 25 mg IV / IO per 1 min, arba esketaminas 14 / 28 mg IN vieną kartą; ketaminą kartoti kas 30 min iki skausmo kontrolės ar nistagmo.", "TCCC 2026 (TFC 11): prieš ketaminą nuginkluoti, AVPU įrašyti DD 1380; stebėti ABC, kvėpavimui slopstant – „uostymo“ padėtis ir ventiliacija; benzodiazepinų su ketaminu ar opioidais neskirti.", "TCCC 2026 (TFC 11): ondansetronas 4 mg ODT / IV / IO / IM kas 8 val. pagal poreikį."], "vaizdai": [{"src": "img/tccc/tccc-cmc15__module-15-pain-medication-analgesia-20.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc15/module-15-pain-medication-analgesia-20.jpg", "cap": "Ketaminas: šalutinis poveikis, sąveikos, veikimo pradžia ir trukmė"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc15/pain-medication-overview-en.mp4", "title": "15.1 Pain Medication Overview", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/pain-medication-overview-cmc", "note": "TCCC skausmo malšinimo apžvalga, įskaitant ketaminą (JTS CMC; sukurta pagal 2020 m. gaires – dozes tikrinkite pagal TCCC 2026)"}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc15/intranasal-in-administration-of-medication-en.mp4", "title": "15.3 Intranasal (IN) Administration of Medication", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/intranasal-in-administration-of-medication-cmc", "note": "Vaisto leidimas į nosį purkštuvu (IN) – taip leidžiamas ir ketaminas (CMC)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/skill-card-analgesic-medications-cheat-sheet-cmc", "pav": "Skill Card 41: Analgesic Medications Cheat Sheet (2021 m. – senesnė už TCCC 2026 gaires)"}, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 11 (analgezija)", "JTS CMC 15 modulis „Pain Medication (Analgesia)“ (tccc.org.ua)", "JTS CMC video 15.1 ir 15.3"]},
  {"id": 26, "grupe": "P", "pav": "Antibiotikai", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Ankstyvas antibiotikas mažina atvirų kovinių žaizdų infekcijos riziką, todėl TCCC 2026 jį skiria visoms atviroms kovinėms žaizdoms ir po invazinių procedūrų. Geriamąjį antibiotiką sąmoningas sužeistasis gali gauti CLS lygiu, IV / IO / IM – skiria CMC. Evakuacijos metu patikrinkite, ar antibiotikas duotas ir užrašytas su laiku, nes kitą dozę skirs kita grandis.", "esme": ["Indikacija – kiekviena atvira kovinė žaizda ir invazinė procedūra.", "Gali nuryti (CLS): cefadroksilis 1 g per burną kartą per parą; alternatyva – cefaleksinas 500 mg per burną kas 6 val.", "Negali nuryti (šokas, be sąmonės): ceftriaksonas 2 g IV / IO / IM kartą per parą – skiria CMC.", "Penetruojantis akies sužalojimas – ceftriaksonas 2 g IV / IM arba cefadroksilis 1 g per burną kuo skubiau.", "Nudegimai – antibiotikai tik jei yra ir penetruojančių žaizdų; penetruojanti galvos trauma – antibiotikai skiriami.", "Prieš skirdami paklauskite apie alergijas; vaistą, dozę, būdą ir laiką įrašykite į DD 1380."], "zingsniai": ["Pirmiausia sutvarkykite gyvybei pavojingas būkles (MARCH), tada skirkite antibiotiką.", "Įvertinkite, ar yra atvira kovinė žaizda (bet koks traumos sukeltas odos pažeidimas) ar atlikta invazinė procedūra.", "Paklauskite apie alergijas vaistams; esant alergijai – nespręskite patys, praneškite medikui.", "Sąmoningam ir galinčiam nuryti duokite cefadroksilio 1 g per burną su vandeniu.", "Jei cefadroksilio nėra – cefaleksinas 500 mg per burną kas 6 val.", "Negalinčiam nuryti (šokas, be sąmonės) – kvieskite mediką: CMC skiria ceftriaksoną 2 g IV / IO arba IM.", "Įrašykite vaistą, dozę, būdą ir laiką į DD 1380 (skiltis „Antibiotic“).", "Perduodami praneškite dozės laiką: cefadroksilio ir ceftriaksono kita dozė – po 24 val., cefaleksino – po 6 val."], "klaidos": ["Naudojamas pasenęs vaistas: JTS CLS 2020 m. medžiagoje ir M. Grinevičiaus kurse CWMP sudėtyje nurodytas moksifloksacinas 400 mg, o TCCC 2026 geriamasis antibiotikas – cefadroksilis 1 g.", "Geriamasis vaistas duodamas be sąmonės, šoko būklės ar negalinčiam nuryti sužeistajam – jam reikia IV / IO / IM (CMC).", "Antibiotikas atidedamas iki ligoninės, nors ankstyva dozė mažina infekcijos riziką.", "Neužrašomas dozės laikas – kita grandis gali dozę pakartoti per anksti arba praleisti.", "Nepaklausiama apie alergijas."], "tccc": ["TCCC 2026 (TFC 12): antibiotikai – visoms atviroms kovinėms žaizdoms ir invazinėms procedūroms; gali nuryti – cefadroksilis 1 g PO kartą per parą (alt. cefaleksinas 500 mg PO kas 6 val.); negali – ceftriaksonas 2 g IV / IO / IM kartą per parą.", "TCCC 2026 (TFC 9): penetruojantis akies sužalojimas – ceftriaksonas 2 g IV / IM arba cefadroksilis 1 g PO kuo skubiau."], "vaizdai": [], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS14/video14-2-eng.mp4", "title": "14.2 Antibiotics Administration", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/antibiotics-administration", "note": "Antibiotikų skyrimas CLS lygiu (JTS, pagal senesnes gaires – vaisto pavadinimas gali skirtis nuo TCCC 2026)"}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc16/antibiotics-administration-en.mp4", "title": "16. Antibiotics Administration", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/antibiotics-administration-cmc", "note": "Antibiotikų skyrimas CMC lygiu, įskaitant IV / IM (vaistus tikrinkite pagal TCCC 2026)"}], "kortele": null, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 9, 12, 15", "JTS CLS 14 modulis „Analgesia Administration/Antibiotic Administration“ (2020)", "M. Grinevičiaus kursas – „Vaistai (P, A)“ (CWMP sudėtis – senesnė)"]},
  {"id": 27, "grupe": "W", "pav": "Žaizdos: evisceracija, įsmigęs daiktas, amputacija", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Iškritę pilvo organai, įsmigę daiktai ir amputacijos atrodo bauginančiai, bet pirmiausia sprendžiamas kraujavimas ir šokas pagal MARCH. Šios žaizdos sutvarkomos ir pritvirtinamos prieš kiekvieną perkėlimą, nes neštuvuose ir transporte tvarsčiai lengvai pasislenka. Evakuacijos metu žaizdas dažnai tikrinkite – uždėto tvarsčio niekada nepalikite be priežiūros.", "esme": ["Evisceracija: sustabdykite kraujavimą, nuplaukite švariu (jei galima – šiltu) skysčiu, uždenkite drėgnu steriliu ar vandeniui nepralaidžiu tvarsčiu; nieko per burną.", "Vienas trumpas (< 60 s) bandymas be jėgos grąžinti organus – tik jei nėra žarnų turinio nutekėjimo ir kraujavimas sustabdytas; nepavykus – uždenkite skaidria nelipnia vandeniui nepralaidžia plėvele.", "Įsmigusio daikto netraukite: stabilizuokite jį tvarsčiais aplink, kad nejudėtų; galūnėje patikrinkite distalinį pulsą ir įtverkite.", "Amputacija: turniketas 5–7,5 cm aukščiau kraujavimo vietos, tiesiai ant odos; kraujuojant – antras šalia pirmojo; amputuotos galūnės turniketo nekonvertuokite.", "Visoms atviroms kovinėms žaizdoms – antibiotikas; nuskausminimas – pagal TCCC.", "Po kiekvieno perkėlimo patikrinkite, ar nekraujuoja iš po tvarsčių ir turniketų; per stiprų tvarstį (blyški ar melsva oda, stiprėjantis skausmas) atlaisvinkite, išlaikydami kraujavimo kontrolę."], "zingsniai": ["Pirmiausia MARCH: sustabdykite masyvų kraujavimą ir įvertinkite šoką – išorinės žaizdos dydis neparodo sužalojimo sunkumo.", "Evisceracija: paguldykite ant nugaros sulenktais keliais, atidenkite ir apžiūrėkite žaizdą.", "Nuplaukite švariu (šiltu) skysčiu; nekontroliuojamą kraujavimą stabdykite hemostatiniu tvarsčiu.", "Jei nėra žarnų turinio nutekėjimo ir kraujavimas sustabdytas – vieną kartą trumpai (< 60 s) be jėgos pabandykite grąžinti organus ir užsandarinkite odą lipniu tvarsčiu (pvz., krūtinės lipduku).", "Nepavykus – uždenkite drėgnu steriliu tvarsčiu ir skaidria nelipnia vandeniui nepralaidžia plėvele, pritvirtinkite prie odos; aktyviai kraujuojančių organų negrąžinkite.", "Įsmigęs daiktas: atsargiai atidenkite, netraukite; kraujuojant spauskite šalia daikto, ne ant jo.", "Paprašykite kito gelbėtojo laikyti daiktą nejudantį, apdėkite jį tvarsčiais ir pritvirtinkite juosta ar skarelėmis; galūnėje – įtverkite ir patikrinkite pulsą, judesius ir jutimą.", "Amputacija: uždėkite arba patikrinkite turniketą 5–7,5 cm aukščiau, tiesiai ant odos; kraujuojant – antrą šalia; sutvarstykite bigę, pažymėkite turniketo laiką.", "Skirkite antibiotiką ir nuskausminimą; evisceracijos atveju – nieko per burną, antibiotiką skiria CMC IV / IO / IM.", "Prieš keliant ant neštuvų sutvirtinkite tvarsčių galus; po kiekvieno perkėlimo patikrinkite tvarsčius, turniketus ir distalinę kraujotaką.", "Viską įrašykite į DD 1380 ir praneškite perduodami (evisceracija, įsmigęs daiktas, turniketo laikas)."], "klaidos": ["Ištraukiamas įsmigęs daiktas – gali prasidėti nekontroliuojamas kraujavimas.", "Organai grąžinami jėga, nors matyti žarnų turinys ar kraujavimas.", "Iškritę organai paliekami atviri ar sausi – greitai džiūsta ir atšąla.", "Bandoma konvertuoti amputuotos galūnės turniketą.", "Tvarstis uždedamas ir pamirštamas: neštuvuose pasislinkęs tvarstis ar atsinaujinęs kraujavimas nepastebimas."], "tccc": ["TCCC 2026 (TFC 13): evisceracija – kraujavimo kontrolė, nuplovimas švariu (šiltu) skysčiu, drėgnas sterilus ar nepralaidus tvarstis; vienas < 60 s grąžinimo bandymas tik be žarnų turinio nutekėjimo ir sustabdžius kraujavimą; nepavykus – skaidri nelipni plėvelė; nieko per burną.", "TCCC 2026 (TFC 3a, 6a): trauminė amputacija – turniketas 5–7,5 cm virš kraujavimo vietos, prireikus antras šalia; amputuotų galūnių turniketai nekonvertuojami."], "vaizdai": [{"src": "img/tccc/tccc-cmc17__skill-card-open-abdominal-wound-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc17/skill-card-open-abdominal-wound-en.jpg", "cap": "TCCC kortelė: atvira pilvo žaizda"}, {"src": "img/tccc/tccc-cmc17__skill-card-impaled-object-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc17/skill-card-impaled-object-en.jpg", "cap": "TCCC kortelė: įsmigęs daiktas"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc17/wound-management-open-abdominal-wound-tactical-field-en.mp4", "title": "17.1 Wound Management: Open Abdominal Wound (Tactical Field Care)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/wound-management-open-abdominal-wound-tactical-field-care-cmc", "note": "Atviros pilvo žaizdos (evisceracijos) tvarkymas – JTS demonstracija."}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc17/amputation-bandaging-en.mp4", "title": "17.3 Amputation Bandaging", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/amputation-bandaging-cmc", "note": "Amputacijos bigės tvarstymas ir nuplėštos dalies priežiūra."}], "kortele": {"url": "https://tccc.org.ua/en/guide/skill-card-open-abdominal-wound-cmc", "pav": "Skill Card 43: Open Abdominal Wound"}, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 3a, 6a, 13", "JTS CMC kortelės „Open Abdominal Wound“ ir „Impaled Object“", "JTS CLS 15 modulis „Wound Management“", "M. Grinevičiaus kursas – „Visa kita (W, S ir t.t.)“ (evisceracija, žaizdos)"]},
  {"id": 28, "grupe": "W", "pav": "Nudegimai", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Nudegę sužeistieji per pažeistą odą netenka skysčių ir šilumos, todėl jiems ypač gresia šokas ir hipotermija. CLS gelbėtojas sustabdo degimą, įvertina plotą devynių taisykle, uždengia sausais steriliais tvarsčiais ir šildo, o skysčius IV / IO skiria CMC. Veido nudegimai uždaroje erdvėje rodo galimą kvėpavimo takų pažeidimą, todėl evakuacijos metu nuolat stebėkite kvėpavimą.", "esme": ["Plotą skaičiuokite devynių taisykle ir apvalinkite iki artimiausių 10 %; mažus plotus – delnu (~1 %).", "Nudegimus uždenkite sausais steriliais tvarsčiais, laisvai – audiniai tinsta; nuimkite žiedus ir laikrodį.", "> 20 % kūno paviršiaus – šilumą atspindintis apvalkalas (Heat-Reflective Shell ar Blizzard antklodė); nudegusieji ypač linkę į hipotermiją.", "> 20 % – skysčiai IV / IO (CMC): Ringerio laktatas, fiziologinis tirpalas ar Hextend (Hextend – ne daugiau 1000 ml); pradinis greitis – %TBSA × 10 ml/val. (40–80 kg), +100 ml/val. kiekvienam 10 kg virš 80 kg (pvz., 30 % → 300 ml/val.).", "Sąmoningas, galintis nuryti ir nudegęs iki 30 % gali gerti skysčius; hemoraginio šoko gydymas svarbesnis už nudegimų skysčius.", "Veido nudegimai uždaroje erdvėje – stebėkite kvėpavimo takus ir SpO₂; užkimimas, kosulys, sunkėjantis kvėpavimas – skubi evakuacija; CMC svarsto ankstyvą chirurginį kvėpavimo takų atvėrimą.", "Visas būtinas intervencijas galima atlikti ir nudegusiam; antibiotikai – tik jei yra penetruojančių žaizdų."], "zingsniai": ["Pašalinkite degimo šaltinį: užgesinkite liepsną ar užmeskite apklotą; iš degančios technikos ar pastato ištraukite jau apšaudymo metu.", "Ištraukę iš šaltinio atidenkite nudegimą: aplink nukirpkite drabužius ir atsargiai atkelkite; prilipusių prie odos neplėškite.", "Nudegus rankoms ar riešams nuimkite žiedus ir laikrodį.", "Apskaičiuokite plotą devynių taisykle (pvz., 18 + 4,5 + 4,5 + 2 = 29 % → 30 %) ir apibraukite procentus DD 1380 kūno schemoje.", "Uždenkite sausais steriliais tvarsčiais, nespausdami.", "Šildykite ir saugokite nuo hipotermijos; > 20 % – šilumą atspindintis apvalkalas.", "> 20 % – kvieskite CMC skysčiams IV / IO; sąmoningam, galinčiam nuryti ir nudegusiam iki 30 % duokite gerti.", "Nuskausminkite: CWMP, negalinčiam kovoti – ketaminas (CMC).", "Stebėkite kvėpavimo takus, sąmonę ir šoko požymius, ieškokite kitų sužalojimų; po kiekvieno perkėlimo įvertinkite iš naujo.", "Viską įrašykite į DD 1380 ir pritvirtinkite ją prie sužeistojo."], "klaidos": ["Plėšiami prie odos prilipę drabužiai.", "Nudegimai tvarstomi spaudžiamai ar paliekami žiedai – tinstant sutrinka kraujotaka.", "Pamirštama hipotermija – nudegusieji šąla greičiau, ypač vėjuotoje evakuacijos priemonėje.", "Nudegimų skysčiai skiriami nesustabdžius kraujavimo – hemoraginio šoko gydymas svarbesnis.", "Nepastebimas kvėpavimo takų nudegimas po gaisro uždaroje erdvėje."], "tccc": ["TCCC 2026 (TFC 15): plotas – devynių taisyklė iki artimiausių 10 %; sausi sterilūs tvarsčiai; > 20 % – šilumą atspindintis apvalkalas; nudegę pacientai linkę į hipotermiją.", "TCCC 2026 (TFC 15): > 20 % – LR, NS ar Hextend IV / IO, %TBSA × 10 ml/val. (40–80 kg), +100 ml/val. kas 10 kg virš 80 kg; iki 30 % sąmoningas ir galintis nuryti – gerti; hemoraginis šokas – pirmenybė.", "TCCC 2026 (TFC 15): veido nudegimai uždaroje erdvėje – stebėti kvėpavimo takus ir SpO₂, esant distresui ar desaturacijai svarstyti ankstyvą chirurginį kvėpavimo takų atvėrimą."], "vaizdai": [{"src": "img/tccc/CLS16__cls-skill-card-16-burn-treatment-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS16/cls-skill-card-16-burn-treatment-en.jpg", "cap": "JTS CLS kortelė: nudegimų gydymas – šaltinio pašalinimas, drabužių nukirpimas, sausi sterilūs tvarsčiai, šildymas, DD 1380"}, {"src": "img/tccc/tccc-cmc18__module-18-burns-12.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc18/module-18-burns-12.jpg", "cap": "Nudegimų gylis (I–IV laipsnis): paviršinis, dalinio storio, viso storio, poodinis"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS16/video16-eng.mp4", "title": "16. Burn Treatment", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/burns", "note": "Nudegimų gydymas CLS lygiu – JTS demonstracija pagal kortelę"}, {"url": "https://www.youtube.com/watch?v=FIpXkjpZGQs", "title": "Burns in TCCC", "ch": "CoTCCC Committee-on-TCCC", "note": "Nudegimai pagal TCCC: ploto vertinimas, skysčiai, hipotermijos prevencija (oficialus CoTCCC kanalas)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/burns", "pav": "CLS Skill Card 16: Burn Treatment"}, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 15", "JTS CLS kortelė 16 „Burn Treatment“", "M. Grinevičiaus kursas – „Visa kita (W, S ir t.t.)“ (nudegimai)", "CoTCCC video „Burns in TCCC“ (YouTube)"]},
  {"id": 29, "grupe": "W", "pav": "Lūžių įtvėrimas", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Įtvėrimas mažina skausmą ir kraujagyslių bei nervų pažeidimo riziką, ypač ilgai nešant ar vežant. Įtverkite sutvarkę gyvybei pavojingas būkles, o prieš ir po įtvėrimo patikrinkite distalinę kraujotaką. Neštuvuose įtvarą pritvirtinkite taip, kad perkeliant galūnė nejudėtų.", "esme": ["Įtverkite sąnarius virš ir žemiau lūžio; galūnę laikykite funkcinėje (natūralioje ramybės) padėtyje, jei įmanoma.", "Prieš ir po įtvėrimo patikrinkite distalinį pulsą, kapiliarų prisipildymą, judesius ir jutimą.", "Po įtvėrimo pulso nėra – atlaisvinkite, pataisykite ir uždėkite iš naujo.", "Atviras lūžis: pirmiausia sustabdykite kraujavimą ir sutvarstykite žaizdą; skirkite antibiotiką kaip atvirai kovinei žaizdai.", "Uždari šlaunikaulio (iki 1–2 l) ar dubens lūžiai gali sukelti didelį vidinį kraujavimą ir šoką; įtarus dubens lūžį – dubens diržas (CMC).", "Plastinį (SAM) įtvarą matuokite ir formuokite ant sveikos galūnės; išilginiai lenkimai suteikia standumo, tuštumas užpildykite paminkštinimu.", "Nesant įtvaro – ranką pririškite skarele prie krūtinės, koją – prie sveikos kojos."], "zingsniai": ["Nustatykite lūžio vietą; paprašykite sužeistojo ar kito žmogaus prilaikyti galūnę nejudančią.", "Prieš įtvėrimą patikrinkite distalinį pulsą ir kapiliarų prisipildymą, taip pat judesius ir jutimą.", "Nuimkite žiedus ir laikrodį; sutvarstykite atviras žaizdas ir įsitikinkite, kad kraujavimas sustabdytas.", "Paruoškite įtvarą ir tvirtinimo priemones (skareles, elastinius tvarsčius); plastinį įtvarą išmatuokite ir suformuokite ant sveikos galūnės.", "Uždėkite įtvarą galūnei funkcinėje padėtyje, kiek įmanoma jos nejudindami.", "Įtverkite sąnarius virš ir žemiau lūžio; tuštumas paminkštinkite.", "Pritvirtinkite įtvarą tvirtai, bet neužspausdami kraujotakos.", "Po įtvėrimo vėl patikrinkite distalinį pulsą; jo nėra – atlaisvinkite, pataisykite ir uždėkite iš naujo.", "Nuskausminkite: sąmoningam ir galinčiam nuryti – CWMP su vandeniu; atviram lūžiui – ir antibiotikas.", "Įrašykite į DD 1380 (pažymėkite „Splint“); evakuacijos metu, ypač po perkėlimų, kartokite pulso patikrą."], "klaidos": ["Neįtveriami sąnariai virš ir žemiau lūžio – lūžgaliai juda.", "Nepatikrinamas distalinis pulsas prieš ir po įtvėrimo.", "Įtvaras užveržiamas per stipriai arba tampa veržiantis, kai galūnė tinsta per evakuaciją.", "Įtveriama anksčiau, nei sustabdytas masyvus kraujavimas ar sutvarkyti kvėpavimo takai."], "tccc": ["TCCC 2026 (TFC 16): įtverkite lūžius ir pakartotinai patikrinkite distalinius pulsus.", "TCCC 2026 (TFC 6a): dubens diržas – sunki buka ar sprogimo trauma ir bent vienas požymis: dubens skausmas, didelė kojos amputacija ar beveik amputacija, dubens lūžio požymiai, sąmonės netekimas, šokas."], "vaizdai": [{"src": "img/tccc/tccc-cmc19__skill-card-malleable-splint-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc19/skill-card-malleable-splint-en.jpg", "cap": "TCCC kortelė: plastinis (SAM) įtvaras"}, {"src": "img/tccc/tccc-cmc19__skill-card-rigid-splint-en.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc19/skill-card-rigid-splint-en.jpg", "cap": "TCCC kortelė: standus įtvaras"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS17/video17-eng.mp4", "title": "17. Splinting", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/splinting", "note": "Įtvėrimas CLS lygiu: pulso patikra, įtvaro formavimas ir tvirtinimas"}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc19/malleable-splinting-en.mp4", "title": "19.1 Malleable Splinting", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/malleable-splinting-cmc", "note": "Plastinio (SAM) įtvaro formavimas ir uždėjimas."}], "kortele": {"url": "https://tccc.org.ua/en/guide/splinting", "pav": "CLS 17. Splinting (tccc.org.ua)"}, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 6a, 16", "JTS CLS kortelė 17 „Splint Application“", "JTS CMC kortelė „Malleable Splint Instruction“", "M. Grinevičiaus kursas – „Visa kita (W, S ir t.t.)“ (lūžiai, įtvėrimas)"]},
  {"id": 30, "grupe": "E", "pav": "Stebėjimas ir pakartotinis vertinimas evakuacijos metu", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Evakuacijos metu sužeistojo būklė keičiasi: gali atsinaujinti kraujavimas, išsivystyti šokas, įtampos pneumotoraksas ar hipotermija. Todėl kas 5–10 min ir po kiekvieno perkėlimo (ant neštuvų, į transportą ir iš jo) pakartokite MARCH ir įrašykite rodiklius su laiku. CLS lygiu vertinama sąmonė (AVPU), kvėpavimas ir pulsas, CMC – papildomai prietaisais (SpO₂, EtCO₂, AKS).", "esme": ["Iki perdavimo medikams pakartotinai vertinkite kas 5–10 min ir po kiekvieno perkėlimo.", "Sąmonė (AVPU): kas 15 min, sunkiai sužeistam – kas 5–10 min; blogėjanti sąmonė – būklės blogėjimo požymis. Ne visiškai budrus (ne A) sužeistasis neturi laikyti ginklo ar ryšio priemonių.", "Pulsas: radialinis ir miego arterijos; skaičiuokite 15 s ir dauginkite iš 4. Silpnas ar nečiuopiamas radialinis pulsas ir sutrikusi sąmonė be galvos traumos – hemoraginio šoko požymiai.", "Kvėpavimas: žiūrėkite, klausykite, jauskite (15 s); pastangų požymiai – šnervių judėjimas, tarpšonkaulinių tarpų įtraukimas, „trikojo“ padėtis.", "Kiekvieną kartą patikrinkite intervencijas: turniketus, tvarsčius, krūtinės lipdukus, NPA, (CMC) IV / IO linijas.", "Pulsoksimetras, jei yra – visiems su vidutine ar sunkia galvos trauma; šoko ir hipotermijos metu rodmenys gali klaidinti.", "Galvos trauma – neurologinė patikra kas 5–10 min; visus rodiklius ir pokyčius su laiku įrašykite į DD 1380."], "zingsniai": ["Po kiekvieno perkėlimo ar būklės pokyčio sustokite ir greitai pakartokite MARCH.", "M: patikrinkite, ar nekraujuoja iš po turniketų, tamponavimo ir tvarsčių, ieškokite nepastebėtų žaizdų; ar turniketo laikas pažymėtas.", "A: ar kvėpavimo takai laisvi; be sąmonės – šoninė padėtis; ar NPA (jei įvestas) vietoje.", "R: įvertinkite kvėpavimo dažnį ir pastangas (15 s), ar laikosi krūtinės lipdukas; progresuojantis dusulys – įtarkite įtampos pneumotoraksą: atkelkite ar nuimkite lipduką, nepadeda – NDC.", "C: radialinį pulsą čiuopkite dviem pirštais nykščio pusėje, skaičiuokite 15 s ir dauginkite iš 4; nečiuopiamas – tikrinkite miego arteriją, stipriai nespausdami.", "Sąmonę vertinkite AVPU skale; jai blogėjant – kartokite visą MARCH ir praneškite.", "H: patikrinkite, ar hipotermijos apvalkalas sandarus ir sausas; evakuacijos priemonėje saugokite nuo vėjo ir kritulių.", "CMC: stebėkite SpO₂, (jei yra) EtCO₂ ir AKS; patikrinkite IV / IO linijas ir infuzijas.", "Kiekvieną matavimą su laiku įrašykite į DD 1380: pulsas ir vieta, AKS, kvėpavimo dažnis, SpO₂, AVPU, skausmas 0–10.", "Būklei pablogėjus praneškite vadui ar evakuacijos medikui ir, jei reikia, patikslinkite evakuacijos skubumą.", "Atvykus medikui – nutraukite vertinimą ir iškart perduokite sužeistąjį (MIST)."], "klaidos": ["Pasitenkinama vienkartine apžiūra – po perkėlimo neperžiūrimi turniketai ir tvarsčiai.", "Rodikliai neužrašomi su laiku – priimanti grandis nemato dinamikos.", "Šoko ar hipotermijos metu pasitikima vien pulsoksimetru.", "Per stipriai spaudžiama miego arterija – sužeistajam gali imti svaigti galva.", "Blogėjanti sąmonė nurašoma nuovargiui ar vaistams, nepakartojus MARCH."], "tccc": ["TCCC 2026 (TFC 3, 8): pakartotinai vertinkite hemoraginį šoką (sutrikusi sąmonė be galvos traumos ir / ar silpnas, nečiuopiamas radialinis pulsas); galvos trauma – neurologinė patikra kas 5–10 min.", "TCCC 2026 (TFC 10): elektroninis stebėjimas, jei indikuotinas ir yra; pulsoksimetrija – visiems su vidutine / sunkia galvos trauma, šoko ir hipotermijos metu gali klaidinti.", "TCCC 2026 (TACEVAC 1): evakuacijos medicinos personalas iš naujo įvertina visus sužeistuosius, visus sužalojimus ir ankstesnes intervencijas."], "vaizdai": [{"src": "img/tccc/CLS18__cls-skill-card-18-1-radial-pulse-assessment-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS18/cls-skill-card-18-1-radial-pulse-assessment-en.jpg", "cap": "JTS CLS kortelė: radialinio pulso vertinimas – du pirštai nykščio pusėje, 15 s × 4"}, {"src": "img/tccc/tccc-cmc20__module-20-casualty-monitoring-13.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc20/module-20-casualty-monitoring-13.jpg", "cap": "Kvėpavimo vertinimas: žiūrėkite, klausykite, jauskite 15 s; pastangų požymiai – šnervių judėjimas, įtraukimai, „trikojo“ padėtis"}, {"src": "img/tccc/CLS5__module-5-tactical-trauma-assessment-en-26.webp", "orig": "https://tccc.org.ua/files/uploads/CLS5/module-5-tactical-trauma-assessment-en-26.jpg", "cap": "TACEVAC: stebėjimas ir pakartotinis vertinimas, MIST, pasiruošimas evakuacijai"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS18/video182-eng.mp4", "title": "18.2 Carotid Pulse Assessment", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/assessing-radialcarotid-pulse", "note": "Miego arterijos pulso radimas ir skaičiavimas (CLS)"}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc20/monitoring-electric-vital-signs-en.mp4", "title": "20.8 Monitoring: Electric Vital Signs", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/monitoring-electric-vital-signs-cmc", "note": "Elektroninio gyvybinių rodiklių monitoriaus naudojimas (CMC)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/assessing-radialcarotid-pulse", "pav": "CLS Skill Card 18.2: Carotid Pulse Assessment"}, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 3, 7, 8, 10; TACEVAC 1", "JTS CLS 18 modulis „Casualty Monitoring“ ir kortelės 18.1–18.2", "JTS CMC 20 modulis „Casualty Monitoring“", "M. Grinevičiaus kursas – „Taktinė evakuacijos pagalba“, „Kraujotaka (C)“"]},
  {"id": 31, "grupe": "E", "pav": "Nukentėjusiojo kortelė (DD 1380)", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "TCCC kortelė (DD Form 1380) – dokumentas, kuriame užrašomas traumos mechanizmas, sužalojimai, gyvybiniai rodikliai ir suteikta pagalba su laikais. Ji keliauja kartu su sužeistuoju per visas evakuacijos grandis, o iš jos sudaromas MIST pranešimas. Naudokite junginio patvirtintą formą (DD 1380 ar LK nukentėjusiojo kortelę) – pildymo principai tie patys.", "esme": ["Pildykite nuo pirmųjų veiksmų ir atnaujinkite po kiekvieno vertinimo, intervencijos ar būklės pokyčio.", "Laiką rašykite 24 val. formatu ir nurodykite, vietinis (L) ar Zulu (Z), pvz., „1300Z“.", "Mechanizmą pažymėkite X; sužalojimus – X kūno schemoje; nudegimų procentus apibraukite; turniketo tipą ir laiką rašykite atitinkamos galūnės langelyje.", "Gyvybiniai rodikliai su laiku: pulsas (dažnis ir vieta), AKS, kvėpavimo dažnis, SpO₂, AVPU, skausmas 0–10.", "Gydymas: pažymėkite C, A, B intervencijas; skysčiai ir kraujo produktai – pavadinimas, tūris, būdas, laikas; vaistai – pavadinimas, dozė, būdas, laikas.", "Pažymėkite CWMP, akies skydelį, įtvarą ir hipotermijos prevenciją (aktyvi ar pasyvi); pastabose – kita svarbi informacija; apačioje – pagalbą suteikusio asmens duomenys.", "Kortelę pritvirtinkite prie sužeistojo matomoje vietoje (pvz., prie riešo ar diržo kilpos) – kortelė ir sužeistasis neturi būti atskirti."], "zingsniai": ["Pasiimkite kortelę ir nenusitrinantį žymeklį; pildyti pradėkite, kai tik leidžia taktinė situacija.", "A dalis: sužeistojo ir junginio duomenys, evakuacijos kategorija (Urgent, Priority, Routine), data, traumos laikas, alergijos.", "B dalis: pažymėkite traumos mechanizmą; sužalojimus – X priekinėje ir užpakalinėje kūno schemoje; nudegimų procentus apibraukite.", "Turniketus įrašykite atitinkamos galūnės langelyje (tipas ir laikas); tą patį laiką užrašykite ir ant turniketo.", "C dalis: įrašykite gyvybinius rodiklius ir laiką; kiekvieną pakartotinį vertinimą rašykite naujame stulpelyje.", "E dalis: pažymėkite atliktas intervencijas (turniketas, tvarsčiai, kvėpavimo takai, krūtinės lipdukas, NDC) ir skysčius.", "F dalis: vaistai – pavadinimas, dozė, būdas, laikas (nuskausminamieji, antibiotikai, kiti, pvz., TXA); prieš ketaminą – AVPU.", "Pažymėkite CWMP, akies skydelį, įtvarą ir hipotermijos prevencijos tipą; pastabose – kas netilpo; trūkstant vietos pildykite antrą kortelę su žyma „#2“.", "H dalis: įrašykite savo, kaip pagalbą suteikusio asmens, duomenis.", "Pritvirtinkite kortelę prie sužeistojo matomoje vietoje ir perduokite su juo; perduodami MIST pranešimą remkitės kortele."], "klaidos": ["Kortelė pildoma tik pabaigoje iš atminties – pamirštami laikai ir dozės.", "Laikas rašomas be nuorodos L ar Z arba ne 24 val. formatu.", "Neįrašomas turniketo uždėjimo, pakartotinio uždėjimo, konversijos ar nuėmimo laikas.", "Kortelė įkišama į kišenę ar kuprinę ir atsiskiria nuo sužeistojo.", "Rodikliai užrašomi be laiko – nematyti dinamikos."], "tccc": ["TCCC 2026 (TFC 19, TACEVAC 18): vertinimus, gydymą ir būklės pokyčius dokumentuokite TCCC kortelėje (DD 1380) ir perduokite ją kartu su sužeistuoju.", "TCCC 2026 (TFC 6a): turniketą pažymėkite laiku nenuplaunamu žymekliu; uždėjimo, pakartotinio uždėjimo, konversijos ir nuėmimo laikus įrašykite į kortelę.", "TCCC 2026 (TFC 11): prieš ketaminą AVPU įrašykite į DD 1380."], "vaizdai": [{"src": "img/tccc/CLS19__cls-skill-card-19-1-dd-1380-tccc-casualty-card-1-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS19/cls-skill-card-19-1-dd-1380-tccc-casualty-card-1-en.jpg", "cap": "JTS CLS kortelė: DD 1380 priekinė pusė – asmens duomenys, mechanizmas, sužalojimai, turniketai, gyvybiniai rodikliai"}, {"src": "img/tccc/CLS19__cls-skill-card-19-1-dd-1380-tccc-casualty-card-2-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS19/cls-skill-card-19-1-dd-1380-tccc-casualty-card-2-en.jpg", "cap": "JTS CLS kortelė: DD 1380 antroji pusė – intervencijos, skysčiai, vaistai, pastabos, pagalbą suteikęs asmuo"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS19/video19-eng.mp4", "title": "19.1 DD Form 1380 TCCC Card", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/dd-form-1380-combat-casualty-care-card", "note": "DD 1380 kortelės pildymas CLS lygiu"}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc23/dd-form-1380-combat-casualty-care-card-en.mp4", "title": "23. DD FORM 1380 Combat Casualty Care Card", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/dd-form-1380-combat-casualty-care-card-cmc", "note": "Išsamesnis DD 1380 pildymas (CMC)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/dd-form-1380-combat-casualty-care-card", "pav": "CLS Skill Card 19.1: DD 1380 TCCC Casualty Card"}, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 6a, 11, 19; TACEVAC 18", "JTS CLS kortelė 19.1 „DD 1380 TCCC Casualty Card“", "JTS CLS 19 modulis „Pre-Evacuation Procedures, Comms and Doc“", "M. Grinevičiaus kursas – „Dokumentacija“"]},
  {"id": 32, "grupe": "E", "pav": "9 eilučių MEDEVAC prašymas ir MIST", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "9 eilučių prašymas (9-Line MEDEVAC) – standartinis radijo pranešimas evakuacijos priemonei iškviesti; jis skirtas evakuacijos koordinatoriams, ne medikams. Pirmų 5 eilučių pakanka priemonei išsiųsti, 6–9 eilutes galima perduoti jai jau judant. MIST pranešimas apie kiekvieną sužeistąjį perduodamas evakuacijos medikams ar priimančiai grandžiai.", "esme": ["Prieš kviesdami surinkite visą informaciją; eilutes perduokite iš eilės, aiškiai, su eilučių numeriais, laikydamiesi ryšio saugumo ir kodų pagal operacijos planą ir SOP.", "Pirmo ryšio metu perduokite bent 1–5 eilutes; 6–9 – kol priemonė pakeliui.", "Skubumas (3 eil.): A – Urgent (skubi), B – Urgent-surgical (skubi chirurginė), C – Priority (prioritetinė), D – Routine (įprastinė), E – Convenience (patogumo); tarp kategorijų sakykite „break“.", "Terminai priklauso nuo doktrinos ir SOP: JTS CLS (2020) – Urgent ir Urgent-surgical per 2 val., Priority – per 4 val., Routine – per 24 val.; kai kurios JAV ir NATO procedūros skubiai kategorijai numato 1 val. ar 90 min. Vadovaukitės savo vieneto SOP.", "Pervertinimas (per aukšta kategorija) atima priemones iš labiausiai jų reikalingų; kategoriją tikslinkite keičiantis būklei.", "MIST: M – mechanizmas ir traumos laikas, I – sužalojimai (sunkiausi pirmiausia), S – simptomai ir gyvybiniai rodikliai, T – suteiktas gydymas; sudaromas iš DD 1380.", "Taikos metu 6 eil. – sužalojimų skaičius ir tipas, 9 eil. – vietovės aprašymas."], "zingsniai": ["Susisiekite su evakuacijos priemones valdančiu padaliniu ir pasakykite „I HAVE A MEDEVAC REQUEST, OVER“ (arba SOP nustatytą frazę); palaukite atsakymo.", "1 eil.: paėmimo vietos koordinatės (8 skaitmenų tinklelio koordinatė).", "2 eil.: paėmimo vietos radijo dažnis, šaukinys ir priesaga.", "3 eil.: sužeistųjų skaičius pagal skubumą – A Urgent, B Urgent-surgical, C Priority, D Routine, E Convenience; tarp kategorijų – „break“.", "4 eil.: specialioji įranga – A nereikia, B gervė (hoist), C ištraukimo įranga, D plaučių ventiliatorius.", "5 eil.: sužeistieji pagal tipą – L# neštuvuose, A# vaikštantys; tarp jų – „break“.", "6 eil. (karo metu) – paėmimo vietos saugumas: N – priešo nėra, P – galimas priešas, E – priešas yra, artėti atsargiai, X – priešas yra, reikia ginkluotos palydos; taikos metu – sužalojimų skaičius ir tipas.", "7 eil.: vietos žymėjimas – A skydai, B pirotechnika, C dūmai, D nežymima, E kita.", "8 eil.: pilietybė ir statusas – A savos ir sąjungininkų (koalicijos) pajėgos, B savos šalies ir sąjungininkų civiliai, C ne koalicijos kariai ar saugumo pajėgos, D ne koalicijos civiliai, E priešo kariai ar sulaikytieji (JTS kortelėje – JAV / ne JAV; vadovaukitės vieneto SOP).", "9 eil. (karo metu) – CBRN užterštumas: N branduolinis, B biologinis, C cheminis (R radiologinis – jei numato SOP); taikos metu – vietovės aprašymas.", "Paruoškite ir perduokite MIST apie kiekvieną sužeistąjį pagal DD 1380; būklei pasikeitus – atnaujinkite."], "klaidos": ["Kviečiama nesurinkus informacijos – užimamas ryšio kanalas, pamirštamos eilutės.", "Pervertinama skubumo kategorija.", "2 eilutėje nurodomas retransliatoriaus, o ne paėmimo vietos radijo dažnis.", "Koordinatės ar kategorijos perduodamos atvirai, nors SOP reikalauja kodų.", "9 eilučių prašymas painiojamas su MIST: 9-Line skirtas priemonei išsiųsti, MIST – medikams.", "Kategorija neatnaujinama, kai sužeistojo būklė pasikeičia."], "tccc": ["TCCC 2026 (TFC 18): kuo anksčiau informuokite taktinę vadovybę apie sužeistojo būklę ir evakuacijos poreikius; per evakuacijos sistemą (koordinavimo celę) organizuokite TACEVAC.", "TCCC 2026 (TFC 18, TACEVAC 17): evakuacijos medikams perduokite mechanizmą, sužalojimus, požymius ir simptomus bei gydymą."], "vaizdai": [{"src": "img/tccc/CLS19__module-19-pre-evacuation-procedures-comms-and-doc-en-09.webp", "orig": "https://tccc.org.ua/files/uploads/CLS19/module-19-pre-evacuation-procedures-comms-and-doc-en-09.jpg", "cap": "9 eilučių prašymas: 1–5 eilutės, būtinos priemonei išsiųsti"}, {"src": "img/tccc/CLS19__module-19-pre-evacuation-procedures-comms-and-doc-en-12.webp", "orig": "https://tccc.org.ua/files/uploads/CLS19/module-19-pre-evacuation-procedures-comms-and-doc-en-12.jpg", "cap": "Sužeistųjų kategorijos (JTS CLS): skubi, skubi chirurginė, prioritetinė, įprastinė, patogumo"}, {"src": "img/tccc/CLS19__cls-skill-card-19-2-9-line-mist-medevac-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS19/cls-skill-card-19-2-9-line-mist-medevac-en.jpg", "cap": "JTS CLS kortelė: 9 eilučių MEDEVAC prašymas ir MIST"}], "video": [{"url": "https://tccc.org.ua/files/uploads/CLS19/video192-eng.mp4", "title": "19.2 9-Line MEDEVAC and MIST Preparation", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/9-line-medevac-mist-report-tfc", "note": "9 eilučių MEDEVAC prašymo ir MIST paruošimas (CLS)"}, {"url": "https://tccc.org.ua/files/uploads/tccc-cmc21/9-line-medevac-mist-report-tactical-field-care-en.mp4", "title": "21.1 9-Line MEDEVAC/MIST Report (Tactical Field Care)", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/9-line-medevacmist-report-tactical-field-care-cmc", "note": "9 eilučių MEDEVAC prašymo ir MIST pranešimo pavyzdys (JAV kariuomenė, CMC)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/9-line-medevac-mist-report-tfc", "pav": "CLS Skill Card 19.2: 9-Line MEDEVAC and MIST Preparation"}, "saltiniai": ["JTS CLS kortelė 19.2 „9-Line MEDEVAC and MIST Preparation“", "JTS CMC kortelė 51 „9-Line MEDEVAC and MIST Preparation“", "JTS CLS 19 modulis; JTS CMC 21 modulis „Communication Procedures“", "TCCC gairės 2026-05-01 – TFC 18; TACEVAC 17", "JTS CLS kortelė 19.1 (DD 1380 evakuacijos terminai)"]},
  {"id": 33, "grupe": "E", "pav": "Pasiruošimas evakuacijai ir neštuvai", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Prieš evakuaciją sužeistasis „supakuojamas“: kortelė pritvirtinta, tvarsčių galai, hipotermijos apvalkalas ir neštuvų diržai sutvirtinti, ginklas ir įranga sutvarkyti pagal junginio standartines veiklos procedūras (SOP). Neštuvai palengvina judėjimą ir pakelia sužeistąjį nuo šaltos žemės, bet kiekvienas pakėlimas gali pajudinti tvarsčius ar turniketus. Todėl po kiekvieno perkėlimo – trumpas pakartotinis vertinimas.", "esme": ["TCCC 2026 tvarka: DD 1380 užpildyta ir pritvirtinta, sutvirtinti tvarsčių galai, hipotermijos apvalkalai ir diržai, neštuvų diržai (bent 2), ilgai evakuacijai – papildomas paminkštinimas, nurodymai vaikštantiems, rikiavimas ir evakuacijos taško sauga pagal SOP.", "Laisvi galai ir antklodės užkliūva ar sraigtasparnio oro sraute tampa sviediniais – viską sutvirtinkite juosta ar diržais.", "Ant neštuvų perkelkite kuo anksčiau – pakėlimas nuo žemės padeda išvengti hipotermijos; svarbią įrangą (pvz., ambu maišą) laikykite prie sužeistojo.", "Padėtis – patogi ir sauganti kvėpavimo takus (nebūtinai ant nugaros); įtarus stuburo traumą po bukos traumos – kuo tiesesnis stuburas ir standūs neštuvai; esant vien penetruojančiai traumai kaklo stabilizacija nebūtina.", "Su sužeistuoju keliaujantį ginklą iškraukite ir padarykite saugų; sprogmenų su juo stenkitės nesiųsti.", "Nešimui vadovauja vienas – keliama ir nuleidžiama tik jo komanda; paprastai nešama kojomis į priekį, išskyrus kylant į kalną ar laiptais; neštuvai – kuo horizontaliau.", "Neštuvai parenkami pagal užduotį, vietovę, žmones ir evakuacijos priemonę – ne visi telpa į transportą ar tinka kelti gerve; jų naudojimą repetuokite iš anksto."], "zingsniai": ["Užbaikite MARCH PAWS ir prieš judėdami pakartotinai įvertinkite visas intervencijas.", "Užpildykite DD 1380 ir pritvirtinkite ją prie sužeistojo matomoje vietoje.", "Sutvirtinkite visus tvarsčių galus; turniketai turi likti atidengti ir pažymėti.", "Ginklą iškraukite ir padarykite saugų; įrangą sutvarkykite pagal SOP (pvz., ant neštuvų tarp kojų arba ją neša kiti kariai).", "Paruoškite ir patikrinkite neštuvus; paguldykite sužeistąjį ant izoliacijos, apvyniokite hipotermijos apvalkalu (veido neuždenkite) ir sutvirtinkite juosta.", "Pritvirtinkite neštuvų diržus (bent 2); ilgai evakuacijai papildomai paminkštinkite.", "Pakelkite vienu metu pagal vieno vado komandą – kojų gale keliantiems lengviau, todėl blogai pritvirtintas sužeistasis gali nuslysti galva žemyn.", "Neškite kojomis į priekį (kylant į kalną ar laiptais – galva į priekį), neštuvus laikykite horizontaliai, judėkite švelniai ir neskubėdami; galiniai nešėjai prisitaiko prie priekinių.", "Reguliariai sustokite ir pasikeiskite pozicijomis (per vieną pagal laikrodžio rodyklę); sustoję patikrinkite turniketus, tvarsčius ir kvėpavimą.", "Vaikštantiems duokite nurodymus: tegul patys tikrina savo tvarsčius, padeda nešti ar saugoti; dezorientuotus ar blogai matančius veskite ranka ant peties.", "Evakuacijos taške sustatykite sužeistuosius pakrovimo tvarka, kategorijas pažymėkite pagal SOP (kortelės, spalvoti cheminiai šviestuvai) ir palaikykite taško saugumą.", "Po užduoties atlikite medicininį aptarimą (AAR) – kas pavyko, kas ne, ką tobulinti – ir papildykite įrangą."], "klaidos": ["Laisvi tvarsčių galai, antklodės ar diržai užkliūva perkeliant arba sraigtasparnio oro sraute.", "Sužeistasis nepritvirtinamas prie neštuvų ir nuslysta keliant ar kertant kliūtį.", "Keliama ne pagal vieną komandą; neštuvai pakreipiami kertant griovius.", "Kortelė ar ginklas atskiriami nuo sužeistojo arba su juo paliekamas užtaisytas ginklas ar sprogmenys.", "Po perkėlimo neperžiūrimi turniketai ir tvarsčiai.", "Sužeistasis ilgai laikomas ant žemės ir greitai šąla."], "tccc": ["TCCC 2026 (TFC 20): pasiruošimas evakuacijai – DD 1380 pritvirtinta, sutvirtinti tvarsčių galai, hipotermijos apvalkalai ir diržai, neštuvų diržai, ilgai evakuacijai – papildomas paminkštinimas; nurodymai vaikštantiems; rikiavimas ir evakuacijos taško sauga pagal SOP.", "TCCC 2026 (TFC 4): kaklo stabilizacija nebūtina, kai trauma tik penetruojanti.", "TCCC 2026 (TFC 7): izoliacija nuo žemės, šlapius drabužius pakeisti sausais, evakuacijos priemonėje saugoti nuo vėjo ir kritulių."], "vaizdai": [{"src": "img/tccc/cls20__module-20-evacuation-procedures-en-10.webp", "orig": "https://tccc.org.ua/files/uploads/cls20/module-20-evacuation-procedures-en-10.jpg", "cap": "Supakuokite sužeistąjį: sutvirtinkite tvarsčių galus, antklodes ir hipotermijos priemones, pritvirtinkite prie neštuvų"}, {"src": "img/tccc/cls20__module-20-evacuation-procedures-en-08.webp", "orig": "https://tccc.org.ua/files/uploads/cls20/module-20-evacuation-procedures-en-08.jpg", "cap": "Neštuvai: sužeistasis turi būti pritvirtintas prieš judant"}, {"src": "img/tccc/CLS11__cls-skill-card-11-hypothermia-treatment-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS11/cls-skill-card-11-hypothermia-treatment-en.jpg", "cap": "JTS CLS kortelė: hipotermijos prevencija – apvyniokite visą sužeistąjį (veido neuždenkite) ir sutvirtinkite juosta prieš nešant"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc24/casualty-preparation-for-evacuation-en.mp4", "title": "24. Casualty Preparation for Evacuation", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/casualty-preparation-for-evacuation-cmc", "note": "Pagrindiniai sužeistojo paruošimo evakuacijai žingsniai (CMC)"}, {"url": "https://www.youtube.com/watch?v=EYfgxODBlwY", "title": "DIY Stretchers Tested & Reviewed", "ch": "Base Medical", "note": "Improvizuotų neštuvų iš turimų priemonių išbandymas (iš M. Grinevičiaus kurso pamokos „Neštuvai“)"}], "kortele": null, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 4, 7, 20", "JTS CLS 20 modulis „Evacuation Procedures“", "JTS CMC 24 modulis „Prepare for Evacuation“", "JTS CLS kortelė 11 „Hypothermia Treatment“", "M. Grinevičiaus kursas – „Neštuvai“, „Taktinė evakuacijos pagalba“"]},
  {"id": 34, "grupe": "E", "pav": "Perdavimas evakuacijos komandai ir perėmimas", "lygis": "CLS", "fazes": ["TACEVAC"], "aprasas": "Perdavimas – vienas pavojingiausių momentų: triukšmas, sraigtasparnio oro srautas ir laiko spaudimas lengvai „pameta“ informaciją. MEDEVAC gelbėtojas perima sužeistąjį iš taktinio padalinio ir vėliau perduoda kitai grandžiai, todėl abiem kryptimis naudojama ta pati struktūra – MIST ir DD 1380. Perėmus visada iš naujo įvertinami visi sužeistieji, sužalojimai ir ankstesnės intervencijos.", "esme": ["Minimali perduodama informacija (TCCC 2026): stabilus ar nestabilus, nustatyti sužalojimai, suteiktas gydymas.", "Žodinis MIST: mechanizmas ir laikas, sužalojimai (sunkiausi pirmiausia), simptomai ir gyvybiniai rodikliai, gydymas – įskaitant tęstiną (pvz., turniketo laikas, paskutinė vaisto dozė).", "DD 1380 turi būti užpildyta, aktuali ir pritvirtinta – ji keliauja su sužeistuoju.", "Nustatykite priimantį asmenį, užmegzkite tiesioginį kontaktą, susitarkite dėl ryšio būdo ir atsakykite į klausimus prieš išvykstant.", "Taktinis padalinys užtikrina evakuacijos taško saugumą ir surikiuoja sužeistuosius; evakuacijos komanda juos pakrauna ir pritvirtina pagal platformos konfigūraciją ir saugos reikalavimus.", "Pakrovimo tvarką nustato evakuacijos priemonės įgula ir SOP – sužeistuosius iš anksto sustatykite pakrovimo eile ir pažymėkite kategorijas."], "zingsniai": ["Prieš atvykdami gaukite 9 eilučių duomenis ir, jei įmanoma, MIST; paruoškite įrangą.", "Evakuacijos taške nustatykite, kas perduoda kiekvieną sužeistąjį, ir užmegzkite tiesioginį kontaktą.", "Išklausykite MIST apie kiekvieną sužeistąjį ir sutikrinkite su DD 1380: stabilus ar nestabilus, sužalojimai, gydymas, laikai.", "Klausimus užduokite iškart – po išvykimo perdavusio asmens jau nebus.", "Iš naujo įvertinkite sužeistąjį (MARCH): turniketai ir jų laikas, tvarsčiai, kvėpavimo takai, krūtinės lipdukai, (CMC) IV / IO.", "Įsitikinkite, kad su sužeistuoju keliaujantys ginklai iškrauti ir saugūs, sprogmenų nėra, o sutrikusios sąmonės sužeistasis nuginkluotas.", "Pakraukite pagal įgulos nurodymus, pritvirtinkite neštuvus ir sužeistąjį pagal platformos reikalavimus; po pakrovimo vėl trumpai įvertinkite.", "Kelionės metu stebėkite, šildykite, saugokite nuo vėjo ir kritulių, pokyčius įrašykite į DD 1380.", "Jei leidžia ryšys, iš anksto informuokite priimančią grandį: sužeistųjų skaičius, būklė, MIST.", "Perduokite tiesiogiai priimančiam medikui: MIST, pokyčiai kelionės metu, kas tęstina (turniketo laikas, kada kita dozė, alergijos); perduokite DD 1380.", "Prieš išvykdami įsitikinkite, kad klausimų nebeliko; po užduoties – aptarimas (AAR) ir įrangos papildymas."], "klaidos": ["Perduodama nesustojus ir be tiesioginio kontakto – svarbi informacija dingsta triukšme.", "Pasitikima vien gauta informacija ir neatliekamas pakartotinis vertinimas.", "DD 1380 neatnaujinta arba atsiskyrusi nuo sužeistojo.", "Nepasakoma, kas tęstina: turniketo laikas, paskutinė analgetiko ar antibiotiko dozė, alergijos.", "Esant keliems sužeistiesiems, MIST ir kortelės supainiojamos."], "tccc": ["TCCC 2026 (TACEVAC 1): taktinis padalinys užtikrina evakuacijos taško saugumą ir surikiuoja sužeistuosius; perduodama bent: stabilus ar nestabilus, sužalojimai, suteiktas gydymas.", "TCCC 2026 (TACEVAC 1): evakuacijos personalas pritvirtina sužeistuosius pagal junginio taisykles, platformos konfigūraciją ir saugą, o medicinos personalas iš naujo įvertina visus sužalojimus ir ankstesnes intervencijas.", "TCCC 2026 (TACEVAC 17–18): kitai grandžiai perduokite mechanizmą, sužalojimus, požymius ir simptomus bei gydymą; dokumentuokite DD 1380."], "vaizdai": [{"src": "img/tccc/cls20__module-20-evacuation-procedures-en-13.webp", "orig": "https://tccc.org.ua/files/uploads/cls20/module-20-evacuation-procedures-en-13.jpg", "cap": "Sužeistųjų sustatymas: pasiruoškite evakuacijos priemonės atvykimui, sustatykite pakrovimo eile, saugokite tašką"}, {"src": "img/tccc/CLS19__cls-skill-card-19-2-9-line-mist-medevac-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS19/cls-skill-card-19-2-9-line-mist-medevac-en.jpg", "cap": "MIST pranešimas (kortelės apačioje) – perdavimo pagrindas: mechanizmas ir laikas, sužalojimai, simptomai ir rodikliai, gydymas"}], "video": [], "kortele": null, "saltiniai": ["TCCC gairės 2026-05-01 – TACEVAC 1, 17, 18", "JTS CMC 24 modulis „Prepare for Evacuation“ (transition of care, staging)", "JTS CLS 19 modulis (relaying data and handoff)", "JTS CLS 18 modulis (perdavimas atvykus medikui)", "JTS CLS 20 modulis „Evacuation Procedures“"]},
  {"id": 35, "grupe": "C", "pav": "Gaivinimas TCCC fazėse (abipusė NDC)", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Po sprogimo ar penetruojančios traumos be gyvybės požymių gaivinimas mūšio lauke nebūna sėkmingas, eikvoja išteklius ir kelia pavojų gelbėtojams, todėl TFC fazėje jis nepradedamas. Liemens traumos ar politraumos atveju prieš nutraukiant pagalbą atliekama abipusė adatinė dekompresija, o TACEVAC metu gaivinti galima, jei nėra akivaizdžiai mirtinų sužalojimų ir chirurginė pagalba bus pasiekta per trumpą laiką. Abipusę adatinę dekompresiją atlieka bet kuris jos apmokytas gelbėtojas (CLS ir aukštesnis); jei yra medikas (CMC) – sprendimą dėl gaivinimo priima jis.", "esme": ["TFC: sprogimo ar penetruojanti trauma be pulso, be kvėpavimo ir be kitų gyvybės požymių – gaivinimas nebus sėkmingas ir nepradedamas.", "Liemens trauma ar politrauma be pulso ir kvėpavimo – abipusė NDC prieš nutraukiant pagalbą, kad būtų atmestas įtampos pneumotoraksas.", "NDC: 14 G ar 10 G, 8 cm adata-kateteris; 5 tarpšonkaulinis tarpas priekinėje pažasties linijoje ARBA 2 tarpas vidurinėje raktikaulio linijoje (ne mediališkiau spenelio linijos); statmenai, virš apatinio šonkaulio krašto, iki galo, 5–10 s, adatą ištraukite, kateterį palikite.", "Sėkmės požymis sustojusiam – grįžta sąmonė ar radialinis pulsas.", "TACEVAC: gaivinti galima, jei nėra akivaizdžiai mirtinų sužalojimų ir sužeistasis per trumpą laiką pateks į chirurginę pagalbą; gaivinimas negali kenkti užduočiai ar atimti gyvybę gelbstinčios pagalbos iš kitų.", "Ne TCCC 2026 (pagal ERC ir vieneto SOP): netrauminis sustojimas (sunki hipotermija, skendimas, elektros trauma) – gaivinimą galima svarstyti, įvertinus saugumą, žmones, trukmę ir evakuacijos galimybes.", "Abipusę NDC atlieka bet kuris NDC apmokytas gelbėtojas (CLS ir aukštesnis). Jei yra kovos medikas (CMC) ar medikas – sprendimą dėl gaivinimo priima jis, kitaip – pagal TCCC ir vieneto SOP."], "zingsniai": ["Užtikrinkite saugumą; nustatykite, ar yra pulsas (miego arterija), kvėpavimas ir kiti gyvybės požymiai.", "Įvertinkite traumos pobūdį: TFC fazėje sprogimo ar penetruojanti trauma be gyvybės požymių – gaivinimo nepradėkite.", "Liemens trauma ar politrauma be pulso ir kvėpavimo – atlikite NDC abiejose pusėse prieš nutraukdami pagalbą.", "Pasirinkite vietą: 5 tarpšonkaulinis tarpas priekinėje pažasties linijoje arba 2 tarpas vidurinėje raktikaulio linijoje.", "Įveskite 14 G ar 10 G, 8 cm adatą-kateterį statmenai krūtinės sienai, virš apatinio šonkaulio krašto, iki galo; palaikykite 5–10 s, adatą ištraukite, kateterį palikite.", "Pakartokite kitoje pusėje; įvertinkite, ar grįžo sąmonė ar radialinis pulsas.", "TACEVAC metu gaivinimą svarstykite tik jei nėra akivaizdžiai mirtinų sužalojimų, chirurginė pagalba greitai pasiekiama ir gaivinimas netrukdo užduočiai ar kitų sužeistųjų gydymui.", "Netrauminio sustojimo (hipotermija, skendimas, elektros trauma) atveju – pagal ERC ir vieneto SOP (ne TCCC 2026) – svarstykite gaivinimą, įvertinę saugumą, žmones ir evakuacijos galimybes.", "Sprendimą, laiką ir atliktus veiksmus įrašykite į DD 1380 ir praneškite vadui."], "klaidos": ["Gaivinimas pradedamas sprogimo ar penetruojančios traumos be gyvybės požymių atveju TFC fazėje – rizikuojama gelbėtojais ir atimama pagalba iš kitų.", "Pagalba nutraukiama neatlikus abipusės NDC liemens traumos ar politraumos atveju.", "NDC adata įvedama mediališkiau spenelio linijos ar ne virš apatinio šonkaulio krašto.", "Gaivinimas tęsiamas evakuacijos metu, nors chirurginė pagalba toli ar trūksta žmonių kitiems sužeistiesiems."], "tccc": ["TCCC 2026 (TFC 17): sprogimo ar penetruojanti trauma be pulso, kvėpavimo ir kitų gyvybės požymių – gaivinimo nebandyti; liemens trauma / politrauma be pulso ir kvėpavimo – abipusė NDC prieš nutraukiant pagalbą.", "TCCC 2026 (TACEVAC 16): gaivinti galima, jei nėra akivaizdžiai mirtinų žaizdų ir sužeistasis greitai pasieks chirurginę pagalbą; gaivinimas negali kenkti užduočiai ar atimti gyvybę gelbstinčios pagalbos iš kitų.", "TCCC 2026 (TFC 5): NDC – 14 G ar 10 G, 8 cm adata; 5 tarpas priekinėje pažasties arba 2 tarpas vidurinėje raktikaulio linijoje; sėkmė sustojusiam – grįžta sąmonė ar radialinis pulsas."], "vaizdai": [{"src": "img/tccc/tccc-cmc22__module-22-cardiopulmonary-resuscitation-in-tfc-04.webp", "orig": "https://tccc.org.ua/files/uploads/tccc-cmc22/module-22-cardiopulmonary-resuscitation-in-tfc-04.jpg", "cap": "Gaivinimas po traumos lauke: kada CPR netaikoma"}, {"src": "img/tccc/CLS8__cls-skill-card-8-2-needle-decompression-chest-en.webp", "orig": "https://tccc.org.ua/files/uploads/CLS8/cls-skill-card-8-2-needle-decompression-chest-en.jpg", "cap": "JTS CLS kortelė: adatinė krūtinės dekompresija – vietos A ir B, adata statmenai virš apatinio šonkaulio, 5–10 s"}], "video": [{"url": "https://tccc.org.ua/files/uploads/tccc-cmc22/bilateral-needle-decompression-en.mp4", "title": "22. Bilateral needle decompression of the chest", "ch": "Joint Trauma System (tccc.org.ua)", "page": "https://tccc.org.ua/en/guide/bilateral-needle-decompression-cmc", "note": "Abipusė adatinė krūtinės dekompresija trauminio širdies sustojimo atveju (CMC)"}], "kortele": {"url": "https://tccc.org.ua/en/guide/skill-card-needle-decompression-of-the-chest-ndc-cmc", "pav": "Skill Card 29: Needle Decompression of the Chest (NDC)"}, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 5, 17; TACEVAC 16", "JTS CMC 22 modulis „Cardiopulmonary Resuscitation in TFC“", "JTS CLS kortelė 8.2 „Needle Decompression of the Chest (NDC)“", "M. Grinevičiaus kursas – „Visa kita (W, S ir t.t.)“ (gaivinimas)"]},
  {"id": 36, "grupe": "K", "pav": "Rūšiavimas ir evakuacijos skubumas", "lygis": "CLS", "fazes": ["TFC", "TACEVAC"], "aprasas": "Rūšiavimas (triažas) – sužeistųjų skirstymas pagal pagalbos ir evakuacijos skubumą, kai sužeistųjų daugiau nei gelbėtojų ar evakuacijos priemonių. Tikslas – turimomis priemonėmis išgelbėti kuo daugiau gyvybių. Kategorijas, žymėjimą ir eiliškumą galutinai nustato junginio SOP ir medikas – čia pateikti tik principai.", "esme": ["Neatidėliotina (Immediate) – reikia gyvybę gelbstinčios intervencijos dabar (pvz., masyvus kraujavimas, kvėpavimo takų obstrukcija, įtampos pneumotoraksas, šokas).", "Atidėta (Delayed) – sunkūs sužalojimai, kuriems reikės chirurgo, bet būklė leidžia palaukti (pvz., sustabdytas kraujavimas be šoko, lūžiai).", "Minimali (Minimal) – lengvai sužeisti, dažniausiai vaikštantys; gali padėti sau, kitiems ar saugoti.", "Laukiančioji (Expectant) – sužalojimai tokie sunkūs, kad turimomis priemonėmis išgyventi mažai tikėtina; neapleiskite – nuskausminkite ir įvertinkite iš naujo, kai atsiras išteklių.", "Rūšiavimas dinamiškas: kartokite po kiekvieno vertinimo ir perkėlimo – kategorija gali keistis.", "Ryšys su evakuacijos skubumu (paprastai): neatidėliotina → Urgent / Urgent-surgical, atidėta → Priority, minimali → Routine; laukiančiųjų evakuaciją lemia SOP ir ištekliai.", "Venkite pervertinimo – per aukšta kategorija atima priemones iš tų, kuriems jų labiausiai reikia."], "zingsniai": ["Užtikrinkite saugumą ir apžvelkite vietą: kiek sužeistųjų, kiek gelbėtojų, kokios evakuacijos priemonės.", "Vaikštančius nukreipkite į nurodytą vietą ir paskirkite jiems atsakingą nesužeistą asmenį; vėliau juos taip pat įvertinkite.", "Greitai įvertinkite kiekvieną likusį: masyvus kraujavimas, kvėpavimo takai, kvėpavimas, radialinis pulsas ir sąmonė.", "Atlikite tik greitas gyvybę gelbstinčias intervencijas (turniketas, kvėpavimo takų atvėrimas, šoninė padėtis) ir eikite prie kito.", "Priskirkite kategoriją – neatidėliotina, atidėta, minimali, laukiančioji – ir pažymėkite pagal SOP (kortelės, spalvoti cheminiai šviestuvai).", "Sutrikusios sąmonės sužeistiesiems paimkite ginklus ir granatas.", "Praneškite vadui sužeistųjų skaičių ir kategorijas – iš jų sudaromos 9 eilučių prašymo 3 ir 5 eilutės.", "Evakuacijos skubumą nustatykite pagal būklę, pvz.: Urgent – šautinė krūtinės, pilvo ar dubens žaizda, hemoraginis šokas, sąmonės netekimas; Priority – kontroliuojami atviri lūžiai, didelio ploto 2 laipsnio nudegimai; Routine – lengva galvos trauma, uždari lūžiai su išlikusiu distaliniu pulsu (terminai – pagal SOP).", "Kartokite rūšiavimą po kiekvieno vertinimo ir perkėlimo; būklei pasikeitus – atnaujinkite kategoriją ir praneškite.", "Evakuacijos taške sustatykite sužeistuosius pakrovimo tvarka pagal SOP ir įgulos nurodymus."], "klaidos": ["Užstringama prie vieno sunkiausio sužeistojo, kol kiti lieka neįvertinti.", "Pervertinimas – per daug sužeistųjų pažymima Urgent.", "Kategorija nustatoma vieną kartą ir nebeatnaujinama.", "Laukiančioji kategorija paliekama be priežiūros ir nuskausminimo.", "Sutrikusios sąmonės sužeistiesiems paliekami ginklai ir granatos."], "tccc": ["TCCC 2026 (TFC 2): rūšiuokite sužeistuosius pagal poreikį (Supplement A – Triage in TCCC).", "TCCC 2026 (TFC 20): sužeistuosius evakuacijai rikiuokite pagal junginio SOP."], "vaizdai": [{"src": "img/tccc/cls4__module-4-principles-and-application-of-tactical-field-care-en-13.webp", "orig": "https://tccc.org.ua/files/uploads/cls4/module-4-principles-and-application-of-tactical-field-care-en-13.jpg", "cap": "Rūšiavimas: pirmiausia – masyvus kraujavimas, penetruojanti liemens trauma, kvėpavimo takai, kvėpavimo distresas, sutrikusi sąmonė"}, {"src": "img/tccc/CLS19__module-19-pre-evacuation-procedures-comms-and-doc-en-13.webp", "orig": "https://tccc.org.ua/files/uploads/CLS19/module-19-pre-evacuation-procedures-comms-and-doc-en-13.jpg", "cap": "Pervertinimas: per aukšta kategorija atima evakuacijos priemones iš kitų"}], "video": [], "kortele": null, "saltiniai": ["TCCC gairės 2026-05-01 – TFC 2, 20 (Supplement A – Triage in TCCC)", "JTS CLS 19 modulis (evakuacijos kategorijos, pervertinimas)", "JTS CLS 19 modulis, 12 skaidrė „Casualty Categories“ (pavyzdžiai)", "JTS CMC 24 modulis „Prepare for Evacuation“ (vaikštantys, pakrovimo tvarka)"]}
];
